// Banque de questions de connaissances générales (ETG) — 10 thèmes officiels.
// Généré/enrichi à partir de la banque initiale ; chaque question a une explication pédagogique.
const knowledgeQuestions = [
  {"id": "kq1", "type": "knowledge", "theme": "circulation", "question": "Quel est le temps de réaction moyen d'un conducteur attentif ?", "options": ["Environ 1 seconde","Environ 0,1 seconde","Environ 3 secondes","Environ 5 secondes"], "correctIndex": 0, "explanation": "Un conducteur attentif met en moyenne 1 seconde pour percevoir un danger et commencer à réagir ; ce délai augmente fortement avec la fatigue, l'alcool ou la distraction."},
  {"id": "kq2", "type": "knowledge", "theme": "circulation", "question": "À 50 km/h, quelle distance parcours-tu pendant ton temps de réaction ?", "options": ["Environ 5 mètres","Environ 14 mètres","Environ 30 mètres","Environ 50 mètres"], "correctIndex": 1, "explanation": "À 50 km/h, on parcourt environ 14 mètres pendant la seconde de réaction, avant même d'avoir commencé à freiner."},
  {"id": "kq3", "type": "knowledge", "theme": "circulation", "question": "Si la vitesse double, la distance de freinage est multipliée par :", "options": ["2","3","4","6"], "correctIndex": 2, "explanation": "La distance de freinage dépend du carré de la vitesse : si la vitesse double, l'énergie cinétique à absorber est multipliée par 4."},
  {"id": "kq4", "type": "knowledge", "theme": "circulation", "question": "Sur route mouillée, la distance de freinage :", "options": ["Reste identique","Diminue légèrement","Est divisée par deux","Peut doubler"], "correctIndex": 3, "explanation": "L'eau réduit fortement l'adhérence des pneus : la distance de freinage peut doubler, voire plus sur route glissante ou avec des pneus usés."},
  {"id": "kq5", "type": "knowledge", "theme": "circulation", "question": "À une intersection sans aucun panneau ni marquage, qui a la priorité ?", "options": ["Le véhicule venant de la droite","Le véhicule qui roule le plus vite","Le véhicule qui arrive en premier","Le plus gros véhicule"], "correctIndex": 0, "explanation": "En l'absence de toute signalisation, la règle de la priorité à droite s'applique : c'est le véhicule venant de la droite qui passe en premier."},
  {"id": "kq6", "type": "knowledge", "theme": "circulation", "question": "En France, à l'entrée d'un rond-point avec un panneau « Cédez le passage », qui est prioritaire ?", "options": ["Les véhicules qui entrent dans le rond-point","Les véhicules déjà engagés dans l'anneau du rond-point","Le véhicule le plus rapide","Le véhicule venant de la droite, toujours"], "correctIndex": 1, "explanation": "Dans la très grande majorité des ronds-points français, un panneau cédez-le-passage impose de laisser la priorité aux véhicules déjà engagés dans l'anneau."},
  {"id": "kq7", "type": "knowledge", "theme": "circulation", "question": "Que signifie un panneau STOP à une intersection ?", "options": ["Ralentir fortement puis passer si la voie est libre","S'arrêter seulement si un véhicule est visible","S'arrêter complètement, même si aucune voiture n'arrive","Céder le passage sans obligation de s'arrêter"], "correctIndex": 2, "explanation": "Le panneau STOP impose un arrêt complet du véhicule, même en l'absence de circulation visible, avant de repartir si la voie est libre."},
  {"id": "kq8", "type": "knowledge", "theme": "circulation", "question": "Quelle est la différence entre un panneau « Cédez le passage » et un panneau STOP ?", "options": ["Il n'y a aucune différence","Le cédez le passage impose un arrêt total, pas le stop","Le stop ne s'applique qu'aux poids lourds","Le stop impose un arrêt total, le cédez le passage non si la voie est libre"], "correctIndex": 3, "explanation": "Le STOP oblige toujours à un arrêt complet, alors que le cédez-le-passage permet de continuer sans s'arrêter si la voie est réellement libre."},
  {"id": "kq9", "type": "knowledge", "theme": "circulation", "question": "Quelle distance latérale minimale un automobiliste doit-il laisser en dépassant un cycliste ?", "options": ["1 mètre en agglomération, 1,5 mètre hors agglomération","Aucune distance n'est fixée par la loi","50 centimètres partout","2 mètres uniquement sur autoroute"], "correctIndex": 0, "explanation": "La loi impose une distance latérale de sécurité d'au moins 1 mètre en agglomération et 1,5 mètre hors agglomération lors d'un dépassement de cycliste."},
  {"id": "kq10", "type": "knowledge", "theme": "circulation", "question": "Le franchissement d'une ligne blanche continue pour dépasser est :", "options": ["Toujours autorisé si la voie est libre","Interdit, quelle que soit la visibilité","Autorisé uniquement de nuit","Autorisé pour les véhicules prioritaires seulement en intervention"], "correctIndex": 1, "explanation": "Une ligne continue interdit tout franchissement, y compris pour dépasser, car elle signale un manque de visibilité ou un danger."},
  {"id": "kq11", "type": "knowledge", "theme": "circulation", "question": "Sur autoroute, par temps de pluie, la vitesse maximale autorisée est :", "options": ["130 km/h","90 km/h","110 km/h","80 km/h"], "correctIndex": 2, "explanation": "Par temps de pluie, la vitesse maximale sur autoroute est abaissée de 130 à 110 km/h en raison de l'allongement des distances de freinage."},
  {"id": "kq12", "type": "knowledge", "theme": "circulation", "question": "En agglomération, sauf indication contraire, la vitesse est limitée à :", "options": ["30 km/h","70 km/h","90 km/h","50 km/h"], "correctIndex": 3, "explanation": "La vitesse par défaut en agglomération est de 50 km/h, sauf signalisation particulière indiquant une autre limite (zone 30, zone de rencontre...)."},
  {"id": "kq13", "type": "knowledge", "theme": "circulation", "question": "Dans une zone 30, la vitesse maximale autorisée est :", "options": ["30 km/h","20 km/h","50 km/h","Il n'y a pas de limite précise"], "correctIndex": 0, "explanation": "Une zone 30, signalée par des panneaux d'entrée et de sortie, limite la vitesse à 30 km/h pour l'ensemble de la zone concernée."},
  {"id": "kq14", "type": "knowledge", "theme": "circulation", "question": "La distance de sécurité entre deux véhicules qui se suivent doit permettre de respecter :", "options": ["Un intervalle d'au moins 5 mètres, quelle que soit la vitesse","Un intervalle d'au moins 2 secondes avec le véhicule qui précède","Un intervalle égal à la longueur du véhicule","Aucune règle précise n'existe"], "correctIndex": 1, "explanation": "La règle des deux secondes permet d'estimer une distance de sécurité suffisante adaptée à la vitesse, en comptant le temps entre le passage du véhicule précédent et le sien à un même point fixe."},
  {"id": "kq15", "type": "knowledge", "theme": "circulation", "question": "Avant de changer de direction ou de voie, un conducteur doit :", "options": ["Actionner son clignotant juste après avoir tourné","Klaxonner pour prévenir","Actionner son clignotant suffisamment à l'avance","Ralentir brutalement pour avertir"], "correctIndex": 2, "explanation": "Le clignotant doit être actionné suffisamment tôt avant de tourner ou de changer de voie, pour informer clairement les autres usagers de son intention."},
  {"id": "kq16", "type": "knowledge", "theme": "circulation", "question": "À un feu orange clignotant, un conducteur doit :", "options": ["S'arrêter obligatoirement","Passer sans ralentir","Accélérer pour dégager le carrefour","Ralentir et redoubler de prudence, la priorité à droite s'applique"], "correctIndex": 3, "explanation": "Un feu orange clignotant signale un carrefour à prudence renforcée : les règles de priorité normales, notamment la priorité à droite, s'appliquent."},
  {"id": "kq17", "type": "knowledge", "theme": "circulation", "question": "En sortant d'un parking ou d'un chemin privé pour s'engager sur une route, un conducteur doit :", "options": ["Céder le passage à tous les usagers de la route","Avoir automatiquement la priorité","Klaxonner puis s'engager","S'engager rapidement pour ne pas gêner"], "correctIndex": 0, "explanation": "Un véhicule qui débouche d'un accès privé, d'un parking ou d'un chemin de terre doit toujours céder le passage à la circulation déjà engagée sur la route."},
  {"id": "kq18", "type": "knowledge", "theme": "circulation", "question": "La bande d'arrêt d'urgence sur autoroute peut être empruntée :", "options": ["Pour rouler plus vite en cas d'embouteillage","Uniquement en cas d'urgence ou de panne","Librement si elle est vide","Uniquement par les motos"], "correctIndex": 1, "explanation": "La bande d'arrêt d'urgence est strictement réservée aux véhicules en panne, aux urgences et aux véhicules de secours ; y circuler ou s'y arrêter sans motif est interdit."},
  {"id": "kq19", "type": "knowledge", "theme": "circulation", "question": "Sur autoroute, la vitesse minimale imposée sur la voie de gauche par conditions normales est :", "options": ["Aucune vitesse minimale n'est fixée","60 km/h","80 km/h","100 km/h"], "correctIndex": 2, "explanation": "Sur autoroute, la vitesse minimale sur la voie la plus à gauche (hors dépassement) est fixée à 80 km/h afin de fluidifier la circulation."},
  {"id": "kq20", "type": "knowledge", "theme": "circulation", "question": "Pour dépasser un autre véhicule, il faut avant tout :", "options": ["Accélérer immédiatement sans vérifier","Klaxonner puis se déporter","Attendre que l'autre véhicule ralentisse","S'assurer d'une visibilité suffisante et de l'absence de danger"], "correctIndex": 3, "explanation": "Avant tout dépassement, il faut vérifier la visibilité, l'absence de véhicule en face ou en train de doubler, et signaler son intention avant de se déporter."},
  {"id": "kq21", "type": "knowledge", "theme": "circulation", "question": "Un panneau annonçant une intersection où tu es prioritaire :", "options": ["N'annule pas l'obligation de rester vigilant","Dispense de toute prudence","Autorise à accélérer fortement","N'existe pas en France"], "correctIndex": 0, "explanation": "Même annoncé prioritaire, un conducteur doit rester vigilant : un autre usager peut ne pas respecter la priorité, notamment un piéton ou un véhicule ne cédant pas le passage."},
  {"id": "kq22", "type": "knowledge", "theme": "circulation", "question": "Sur une route à trois voies avec sens de circulation alterné au centre, la voie centrale sert :", "options": ["Exclusivement aux véhicules lents","Au dépassement, à utiliser avec prudence et de façon temporaire","De voie de stationnement","De piste cyclable"], "correctIndex": 1, "explanation": "Sur ce type de route, la voie centrale est réservée au dépassement temporaire dans un sens ou dans l'autre, et doit être quittée dès la manœuvre terminée."},
  {"id": "kq23", "type": "knowledge", "theme": "circulation", "question": "À un carrefour à sens giratoire, il faut céder le passage :", "options": ["Aux véhicules qui souhaitent entrer dans le giratoire","Aux deux-roues uniquement","Aux véhicules déjà présents dans l'anneau","À personne, la priorité est à celui qui entre"], "correctIndex": 2, "explanation": "Sauf signalisation contraire exceptionnelle, les véhicules circulant déjà dans l'anneau du giratoire sont prioritaires sur ceux qui souhaitent y entrer."},
  {"id": "kq24", "type": "knowledge", "theme": "circulation", "question": "Le clignotant doit être coupé :", "options": ["Jamais, il peut rester allumé en continu","Seulement à l'arrêt complet du véhicule","Uniquement par un autre conducteur","Dès que la manœuvre de changement de direction ou de voie est terminée"], "correctIndex": 3, "explanation": "Une fois le changement de direction ou de voie effectué, le clignotant doit être coupé pour ne pas induire les autres usagers en erreur."},
  {"id": "kq25", "type": "knowledge", "theme": "conducteur", "question": "Quel est le taux d'alcoolémie maximal autorisé avec un permis classique en France ?", "options": ["0,5 g/L de sang","0,2 g/L de sang","0,8 g/L de sang","1 g/L de sang"], "correctIndex": 0, "explanation": "Le taux légal maximal pour un permis classique est de 0,5 gramme d'alcool par litre de sang, soit 0,25 mg par litre d'air expiré."},
  {"id": "kq26", "type": "knowledge", "theme": "conducteur", "question": "Pour un conducteur en permis probatoire, le taux limite d'alcoolémie est :", "options": ["0,5 g/L de sang","0,2 g/L de sang","0,8 g/L de sang","Le même que pour un permis classique"], "correctIndex": 1, "explanation": "Pendant la période probatoire, le taux d'alcoolémie autorisé est abaissé à 0,2 g/L de sang, soit une quasi-tolérance zéro."},
  {"id": "kq27", "type": "knowledge", "theme": "conducteur", "question": "Concernant les stupéfiants au volant, la règle est :", "options": ["Autorisé sous un certain seuil","Autorisé la nuit uniquement","Tolérance zéro, quel que soit le taux","Autorisé pour un trajet court"], "correctIndex": 2, "explanation": "Pour les stupéfiants, la loi française applique une tolérance zéro : la moindre trace détectée dans l'organisme est sanctionnée."},
  {"id": "kq28", "type": "knowledge", "theme": "conducteur", "question": "Utiliser une oreillette ou un casque au volant en France est :", "options": ["Autorisé si les mains restent sur le volant","Autorisé uniquement sur autoroute","Autorisé pour les livreurs","Interdit, comme le téléphone en main"], "correctIndex": 3, "explanation": "Le port d'une oreillette ou d'un casque audio au volant est interdit, car il isole le conducteur des bruits environnants indispensables à la conduite."},
  {"id": "kq29", "type": "knowledge", "theme": "conducteur", "question": "Tenir son téléphone en main au volant expose à :", "options": ["Une amende de 135€ et un retrait de 3 points","Aucune sanction si l'appel est bref","Un simple avertissement oral","Une amende uniquement en agglomération"], "correctIndex": 0, "explanation": "Tenir son téléphone en main en conduisant est sanctionné par une amende forfaitaire de 135€ et un retrait de 3 points sur le permis."},
  {"id": "kq30", "type": "knowledge", "theme": "conducteur", "question": "Les signes annonciateurs de la fatigue au volant comprennent :", "options": ["Une vision plus nette et des réflexes plus rapides","Bâillements, picotements des yeux et difficulté à se concentrer","Une envie soudaine d'accélérer","Aucun signe n'est identifiable"], "correctIndex": 1, "explanation": "Bâillements répétés, yeux qui piquent, paupières lourdes et perte de concentration sont des signaux d'alerte à prendre au sérieux avant qu'il ne soit trop tard."},
  {"id": "kq31", "type": "knowledge", "theme": "conducteur", "question": "Que faire dès les premiers signes de somnolence au volant ?", "options": ["Ouvrir la fenêtre et continuer à rouler","Augmenter la vitesse pour arriver plus vite","S'arrêter dès que possible pour faire une vraie pause ou dormir","Mettre la musique plus forte"], "correctIndex": 2, "explanation": "Face aux signes de somnolence, il faut s'arrêter au plus vite : seule une vraie pause, voire une sieste courte, restaure réellement la vigilance."},
  {"id": "kq32", "type": "knowledge", "theme": "conducteur", "question": "Les bandes rugueuses (ou bandes sonores) situées sur le bas-côté de certaines routes servent à :", "options": ["Décorer la chaussée","Faciliter le stationnement","Indiquer une limitation de vitesse","Alerter un conducteur qui s'endort ou dévie de sa trajectoire"], "correctIndex": 3, "explanation": "Ces bandes rugueuses provoquent un bruit et des vibrations qui alertent un conducteur somnolent en train de sortir de sa voie."},
  {"id": "kq33", "type": "knowledge", "theme": "conducteur", "question": "Concernant les médicaments et la conduite, un pictogramme de niveau 3 (fond rouge) signifie :", "options": ["Danger : ne pas conduire sans avis médical","Le médicament n'a aucun effet sur la conduite","Il faut simplement éviter l'alcool en plus","Le médicament améliore la vigilance"], "correctIndex": 0, "explanation": "Le pictogramme rouge (niveau 3) signale un danger potentiellement grave pour la conduite : il faut impérativement consulter un médecin avant de prendre le volant."},
  {"id": "kq34", "type": "knowledge", "theme": "conducteur", "question": "La vision périphérique d'un conducteur :", "options": ["S'élargit quand la vitesse augmente","Se réduit quand la vitesse augmente","Reste identique quelle que soit la vitesse","N'a aucun rôle dans la conduite"], "correctIndex": 1, "explanation": "Plus la vitesse augmente, plus le champ de vision périphérique se rétrécit, ce qui réduit la perception des dangers latéraux."},
  {"id": "kq35", "type": "knowledge", "theme": "conducteur", "question": "Un angle mort est :", "options": ["Une zone toujours visible dans les rétroviseurs","Un défaut mécanique du véhicule","Une zone autour du véhicule non visible dans les rétroviseurs ni de face","Une zone uniquement présente sur les motos"], "correctIndex": 2, "explanation": "L'angle mort désigne les zones proches du véhicule que le conducteur ne peut pas voir directement ni dans ses rétroviseurs, d'où le besoin de tourner la tête avant de changer de direction."},
  {"id": "kq36", "type": "knowledge", "theme": "conducteur", "question": "À quel âge minimum peut-on commencer la conduite accompagnée (AAC) en France ?", "options": ["14 ans","17 ans","18 ans","15 ans"], "correctIndex": 3, "explanation": "La conduite accompagnée est accessible dès 15 ans, après avoir suivi une formation initiale et réussi l'examen du code de la route."},
  {"id": "kq37", "type": "knowledge", "theme": "conducteur", "question": "La durée du permis probatoire est de :", "options": ["3 ans, réduite à 2 ans en cas de conduite accompagnée","1 an, quel que soit le mode d'apprentissage","5 ans dans tous les cas","Il n'existe pas de période probatoire"], "correctIndex": 0, "explanation": "Le permis probatoire dure normalement 3 ans, réduit à 2 ans pour les conducteurs ayant suivi la conduite accompagnée (AAC)."},
  {"id": "kq38", "type": "knowledge", "theme": "conducteur", "question": "Un conducteur qui perd tous ses points de permis :", "options": ["Peut continuer à conduire normalement","Voit son permis invalidé et doit repasser les examens après un délai","Reçoit automatiquement 12 nouveaux points","N'a qu'un simple avertissement"], "correctIndex": 1, "explanation": "La perte de la totalité des points entraîne l'invalidation du permis : il faut respecter un délai avant de pouvoir repasser le code et la conduite."},
  {"id": "kq39", "type": "knowledge", "theme": "conducteur", "question": "Un taux d'alcoolémie égal ou supérieur à 0,8 g/L de sang constitue :", "options": ["Une simple contravention","Une infraction sans conséquence sur le permis","Un délit, avec de lourdes sanctions possibles","Une infraction uniquement pour les professionnels"], "correctIndex": 2, "explanation": "Au-delà de 0,8 g/L, l'infraction devient un délit : amende pouvant atteindre 4 500€, suspension ou annulation du permis, voire peine de prison en cas de récidive ou d'accident."},
  {"id": "kq40", "type": "knowledge", "theme": "conducteur", "question": "Après combien d'heures de conduite continue est-il recommandé de faire une pause ?", "options": ["Toutes les 30 minutes","Toutes les six heures","Une seule pause par trajet suffit, quelle que soit sa durée","Environ toutes les deux heures"], "correctIndex": 3, "explanation": "Il est recommandé de faire une vraie pause de 15 à 20 minutes toutes les deux heures environ, ou tous les 200 km, pour préserver sa vigilance."},
  {"id": "kq41", "type": "knowledge", "theme": "conducteur", "question": "Les stages de récupération de points permettent de récupérer :", "options": ["Jusqu'à 4 points, dans la limite du plafond du permis, une fois par an","Un nombre illimité de points","Automatiquement tous les points perdus","Uniquement 1 point par stage"], "correctIndex": 0, "explanation": "Un stage de sensibilisation à la sécurité routière permet de récupérer jusqu'à 4 points, sans dépasser le plafond du permis, et n'est valable qu'une fois par période de 12 mois."},
  {"id": "kq42", "type": "knowledge", "theme": "conducteur", "question": "La consommation de cannabis avant de conduire :", "options": ["N'altère pas les réflexes","Peut altérer les réflexes et la perception plusieurs heures après la prise","N'est détectable qu'après 24 heures","Est autorisée en dessous d'un certain seuil"], "correctIndex": 1, "explanation": "Le cannabis altère les réflexes, la coordination et la perception des distances pendant plusieurs heures, tout en étant soumis à une tolérance zéro sur la route."},
  {"id": "kq43", "type": "knowledge", "theme": "route", "question": "Un panneau de danger a généralement la forme :", "options": ["D'un cercle à fond bleu","D'un rectangle bleu","D'un triangle à fond blanc bordé de rouge","D'un octogone rouge"], "correctIndex": 2, "explanation": "Les panneaux de danger sont traditionnellement des triangles à fond blanc avec une bordure rouge, annonçant un risque particulier sur la route."},
  {"id": "kq44", "type": "knowledge", "theme": "route", "question": "Un panneau d'interdiction a généralement la forme :", "options": ["D'un triangle jaune","D'un rectangle vert","D'un losange jaune","D'un cercle à bordure rouge"], "correctIndex": 3, "explanation": "Les panneaux d'interdiction sont ronds, avec un fond généralement blanc et une bordure rouge, parfois un pictogramme barré."},
  {"id": "kq45", "type": "knowledge", "theme": "route", "question": "Un panneau d'obligation a généralement la forme :", "options": ["Un cercle à fond bleu","Un triangle rouge","Un rectangle blanc","Un octogone rouge"], "correctIndex": 0, "explanation": "Les panneaux d'obligation sont ronds avec un fond bleu, indiquant une direction ou un comportement obligatoire (piste cyclable, vitesse minimale...)."},
  {"id": "kq46", "type": "knowledge", "theme": "route", "question": "Les panneaux d'indication (parkings, services, directions) ont le plus souvent la forme :", "options": ["D'un triangle rouge","D'un carré ou rectangle, fond bleu ou vert","D'un cercle rouge","D'un losange noir"], "correctIndex": 1, "explanation": "Les panneaux d'indication sont carrés ou rectangulaires, à fond bleu (ou vert sur autoroute) et donnent des informations utiles sans imposer d'obligation."},
  {"id": "kq47", "type": "knowledge", "theme": "route", "question": "Une ligne blanche continue au sol signifie :", "options": ["Le franchissement est autorisé avec prudence","Elle sépare uniquement les voies de bus","Le franchissement est interdit","Elle indique un stationnement autorisé"], "correctIndex": 2, "explanation": "Une ligne continue interdit tout franchissement, quelle que soit la manœuvre envisagée, car elle marque une zone où la visibilité ou la sécurité est insuffisante."},
  {"id": "kq48", "type": "knowledge", "theme": "route", "question": "Une ligne blanche discontinue au sol signifie :", "options": ["Le franchissement est interdit dans tous les cas","Elle indique uniquement une sortie d'autoroute","Elle remplace un panneau STOP","Le franchissement est autorisé si la manœuvre est sûre"], "correctIndex": 3, "explanation": "Une ligne discontinue autorise le franchissement, par exemple pour dépasser ou changer de voie, à condition que la manœuvre soit faite en toute sécurité."},
  {"id": "kq49", "type": "knowledge", "theme": "route", "question": "Lorsqu'une ligne continue et une ligne discontinue sont accolées, la règle à respecter est celle :", "options": ["De la ligne la plus proche de son propre véhicule","De la ligne discontinue uniquement","De la ligne continue uniquement, quel que soit le côté","Du conducteur qui choisit"], "correctIndex": 0, "explanation": "C'est la ligne située du côté où circule le véhicule qui s'applique : si elle est continue de son côté, le franchissement est interdit ; si elle est discontinue, il est autorisé sous conditions de sécurité."},
  {"id": "kq50", "type": "knowledge", "theme": "route", "question": "La signalisation temporaire de chantier, généralement de couleur jaune-orange :", "options": ["N'a aucune valeur légale","Prévaut sur la signalisation permanente en cas de contradiction","S'applique uniquement la nuit","Concerne uniquement les poids lourds"], "correctIndex": 1, "explanation": "En cas de chantier ou de danger temporaire, la signalisation jaune-orange prévaut sur la signalisation permanente, le temps que dure la situation."},
  {"id": "kq51", "type": "knowledge", "theme": "route", "question": "Sur autoroute, les panneaux de direction sont généralement de couleur :", "options": ["Verte","Jaune","Bleue","Rouge"], "correctIndex": 2, "explanation": "Les panneaux de direction sur autoroute sont bleus, tandis que ceux des routes nationales sont généralement verts et ceux des petites routes blancs."},
  {"id": "kq52", "type": "knowledge", "theme": "route", "question": "Une voie réservée aux bus est le plus souvent signalée par :", "options": ["Une ligne continue jaune uniquement","Aucun marquage particulier","Un panneau STOP permanent","Un marquage au sol et un panneau spécifique, parfois avec le mot « BUS »"], "correctIndex": 3, "explanation": "Ces voies sont identifiées par un marquage au sol dédié et une signalisation verticale spécifique, réservant leur usage aux bus (et parfois taxis, vélos)."},
  {"id": "kq53", "type": "knowledge", "theme": "route", "question": "Une bande cyclable se différencie d'une piste cyclable par le fait qu'elle :", "options": ["Est simplement marquée au sol, sur la chaussée partagée","Est physiquement séparée de la chaussée par un obstacle","Est réservée aux piétons","N'existe pas en France"], "correctIndex": 0, "explanation": "La bande cyclable est un espace délimité par un marquage au sol sur la chaussée, alors que la piste cyclable est physiquement séparée du reste de la circulation."},
  {"id": "kq54", "type": "knowledge", "theme": "route", "question": "Une voie verte est réservée :", "options": ["Aux seuls véhicules motorisés","Aux déplacements non motorisés : piétons, cyclistes, cavaliers","Uniquement aux bus","Aux poids lourds en transit"], "correctIndex": 1, "explanation": "Une voie verte est un aménagement réservé aux usagers non motorisés : piétons, cyclistes, rollers, cavaliers, etc."},
  {"id": "kq55", "type": "knowledge", "theme": "route", "question": "Sur une chaussée à double sens sans séparateur physique, l'axe central :", "options": ["N'a aucune importance","Indique un sens unique","Sépare virtuellement les deux sens de circulation","Signale toujours un danger imminent"], "correctIndex": 2, "explanation": "Même sans séparateur physique, l'axe central (souvent marqué) délimite les deux sens de circulation que chaque conducteur doit respecter."},
  {"id": "kq56", "type": "knowledge", "theme": "route", "question": "Le panneau STOP est reconnaissable entre tous les panneaux car il est le seul à avoir la forme :", "options": ["Ronde","Triangulaire","Carrée","Octogonale"], "correctIndex": 3, "explanation": "Le panneau STOP a une forme octogonale unique en signalisation routière, ce qui permet de le reconnaître même de dos ou masqué partiellement."},
  {"id": "kq57", "type": "knowledge", "theme": "route", "question": "Sur la chaussée, des flèches blanches obliques au sol avant un rétrécissement de voie servent à :", "options": ["Inviter les conducteurs à se rabattre progressivement","Indiquer un parking","Signaler une priorité à droite","Indiquer une zone de dépassement autorisé"], "correctIndex": 0, "explanation": "Ces flèches de rabattement invitent les conducteurs à anticiper la fusion des voies et à se rabattre en douceur, en respectant l'alternat si besoin."},
  {"id": "kq58", "type": "knowledge", "theme": "route", "question": "Le panneau annonçant un « Cédez le passage » a la forme :", "options": ["D'un octogone rouge","D'un triangle pointe en bas, fond blanc, bordure rouge","D'un cercle bleu","D'un carré vert"], "correctIndex": 1, "explanation": "Le panneau cédez-le-passage est un triangle inversé (pointe vers le bas) à fond blanc bordé de rouge, unique par cette orientation."},
  {"id": "kq59", "type": "knowledge", "theme": "route", "question": "Un panneau à fond blanc et bordure rouge portant un chiffre indique généralement :", "options": ["Une vitesse minimale obligatoire","Un numéro de route uniquement","Une vitesse maximale autorisée","Une distance jusqu'à la prochaine ville"], "correctIndex": 2, "explanation": "Un panneau rond à fond blanc bordé de rouge affichant un nombre indique la vitesse maximale autorisée à cet endroit."},
  {"id": "kq60", "type": "knowledge", "theme": "usagers", "question": "Sur un passage piéton, dès qu'un piéton est engagé ou s'apprête clairement à traverser :", "options": ["Le conducteur peut continuer sans ralentir","Seuls les piétons âgés sont prioritaires","La priorité dépend de la couleur du feu uniquement","Le conducteur doit s'arrêter pour le laisser passer"], "correctIndex": 3, "explanation": "Dès qu'un piéton est engagé ou sur le point de traverser sur un passage protégé, il est prioritaire et le conducteur doit s'arrêter."},
  {"id": "kq61", "type": "knowledge", "theme": "usagers", "question": "Un poids lourd qui tourne à droite présente un risque particulier lié :", "options": ["À ses angles morts très étendus","À sa vitesse excessive","À son absence de clignotants","À sa faible hauteur"], "correctIndex": 0, "explanation": "Les poids lourds ont des angles morts très importants, notamment côté passager : il faut éviter de se placer à leur droite lorsqu'ils s'apprêtent à tourner."},
  {"id": "kq62", "type": "knowledge", "theme": "usagers", "question": "Au feu rouge, un cycliste peut parfois tourner à droite (ou aller tout droit à une intersection en T) si :", "options": ["Cela est toujours autorisé sans condition","Un panonceau spécifique (« cédez-le-passage cycliste ») l'y autorise","Il est seul sur la route","Le feu est orange fixe"], "correctIndex": 1, "explanation": "Un panonceau spécifique (type M12) peut autoriser les cyclistes à franchir un feu rouge pour tourner à droite ou continuer tout droit, en cédant le passage aux autres usagers prioritaires."},
  {"id": "kq63", "type": "knowledge", "theme": "usagers", "question": "Les trottinettes électriques sont en principe autorisées à circuler :", "options": ["Sur les trottoirs, à toute vitesse","Uniquement sur autoroute","Sur la chaussée, les pistes et bandes cyclables, pas sur le trottoir (sauf autorisation locale à vitesse limitée)","Nulle part en agglomération"], "correctIndex": 2, "explanation": "Les trottinettes électriques doivent circuler sur la chaussée ou les aménagements cyclables ; l'usage du trottoir est en principe interdit, sauf autorisation municipale à vitesse réduite."},
  {"id": "kq64", "type": "knowledge", "theme": "usagers", "question": "Une personne à mobilité réduite disposant d'une carte de stationnement peut :", "options": ["Se garer n'importe où sans restriction","Ignorer tous les panneaux de stationnement","Se garer en double file sans limite de temps","Bénéficier de places réservées et parfois de facilités de stationnement selon la réglementation locale"], "correctIndex": 3, "explanation": "La carte de stationnement pour personnes handicapées donne accès à des places réservées et à certaines facilités, définies par la réglementation locale, mais ne dispense pas de respecter la sécurité."},
  {"id": "kq65", "type": "knowledge", "theme": "usagers", "question": "La nuit, hors agglomération, un cycliste doit porter :", "options": ["Un gilet ou des équipements rétro-réfléchissants","Aucun équipement particulier","Un casque intégral obligatoire","Des warnings clignotants"], "correctIndex": 0, "explanation": "Hors agglomération et de nuit (ou par visibilité insuffisante), le port d'un gilet ou d'équipements rétro-réfléchissants est obligatoire pour les cyclistes."},
  {"id": "kq66", "type": "knowledge", "theme": "usagers", "question": "Face à un deux-roues motorisé, un automobiliste doit :", "options": ["Réduire ses distances de sécurité par rapport à une voiture","Conserver une distance de sécurité au moins équivalente, en tenant compte de sa plus grande vulnérabilité","Ignorer sa présence s'il roule vite","Le doubler sans laisser d'espace latéral"], "correctIndex": 1, "explanation": "Les deux-roues sont plus vulnérables et moins visibles : il faut leur laisser une distance de sécurité au moins équivalente à celle d'une voiture, voire plus grande."},
  {"id": "kq67", "type": "knowledge", "theme": "usagers", "question": "Sur autoroute, la vitesse maximale autorisée pour un poids lourd est généralement inférieure à celle des voitures, soit environ :", "options": ["130 km/h, comme les voitures","50 km/h","90 km/h","110 km/h dans tous les cas"], "correctIndex": 2, "explanation": "Les poids lourds sont limités à environ 90 km/h sur autoroute (selon leur catégorie), une vitesse inférieure à celle des véhicules légers."},
  {"id": "kq68", "type": "knowledge", "theme": "usagers", "question": "Doubler un poids lourd nécessite en général :", "options": ["Moins de distance que pour doubler une voiture","Aucune précaution particulière","Un freinage juste avant le dépassement","Plus de distance et d'anticipation en raison de sa longueur"], "correctIndex": 3, "explanation": "En raison de sa longueur, dépasser un poids lourd demande davantage de distance et d'anticipation qu'un dépassement de voiture classique."},
  {"id": "kq69", "type": "knowledge", "theme": "usagers", "question": "À proximité d'une école, un conducteur doit :", "options": ["Redoubler de prudence et ralentir, en particulier aux heures d'entrée et de sortie","Accélérer pour dégager rapidement la zone","Ignorer les enfants qui jouent sur le trottoir","Klaxonner systématiquement"], "correctIndex": 0, "explanation": "Aux abords des écoles, la prudence et une vitesse réduite sont indispensables, car le comportement des enfants peut être imprévisible."},
  {"id": "kq70", "type": "knowledge", "theme": "usagers", "question": "Un piéton muni d'une canne blanche qui traverse hors passage piéton est :", "options": ["Jamais prioritaire hors passage piéton","Prioritaire dans tous les cas","Prioritaire uniquement le jour","Soumis aux mêmes règles qu'un piéton valide"], "correctIndex": 1, "explanation": "Un piéton non-voyant ou malvoyant muni d'une canne blanche, ou accompagné d'un chien guide, est toujours prioritaire, même en dehors d'un passage protégé."},
  {"id": "kq71", "type": "knowledge", "theme": "usagers", "question": "Le stationnement sur une piste cyclable est :", "options": ["Autorisé le temps de charger/décharger un véhicule","Autorisé uniquement pour les motos","Interdit, car il oblige les cyclistes à se rabattre dangereusement sur la chaussée","Toléré si la piste est large"], "correctIndex": 2, "explanation": "Stationner sur une piste cyclable est interdit et dangereux, car cela force les cyclistes à se déporter brusquement vers la circulation motorisée."},
  {"id": "kq72", "type": "knowledge", "theme": "usagers", "question": "Un motard peut circuler entre deux files de véhicules à l'arrêt ou circulant lentement :", "options": ["Toujours librement, partout en France","Uniquement de nuit","Jamais, c'est totalement interdit","Uniquement là où cette pratique est expérimentée et encadrée par arrêté"], "correctIndex": 3, "explanation": "La circulation inter-files n'est autorisée que dans les zones où elle a été expérimentée et encadrée par arrêté préfectoral, avec des règles de vitesse précises."},
  {"id": "kq73", "type": "knowledge", "theme": "usagers", "question": "Face à une personne âgée qui traverse lentement sur un passage piéton, un conducteur doit :", "options": ["Patienter le temps nécessaire, sans manifester d'impatience dangereuse","Klaxonner pour la faire accélérer","Redémarrer dès qu'elle a fait un pas","La contourner en roulant"], "correctIndex": 0, "explanation": "Il faut laisser le temps nécessaire à toute personne traversant plus lentement, notamment les personnes âgées ou à mobilité réduite, sans mettre la pression."},
  {"id": "kq74", "type": "knowledge", "theme": "usagers", "question": "Le port du casque pour un passager de deux-roues motorisé est :", "options": ["Facultatif si le trajet est court","Obligatoire, comme pour le conducteur","Réservé aux enfants","Non requis en agglomération"], "correctIndex": 1, "explanation": "Le port du casque homologué est obligatoire pour le conducteur ET pour tout passager d'un deux-roues motorisé, quelle que soit la distance parcourue."},
  {"id": "kq75", "type": "knowledge", "theme": "usagers", "question": "Face à un cycliste circulant devant soi sur une route étroite, un automobiliste doit :", "options": ["Klaxonner avant de le dépasser dans tous les cas","Le doubler au plus près pour gagner du temps","Ralentir et attendre un espace suffisant pour dépasser en toute sécurité","Lui demander de se ranger sur le bas-côté"], "correctIndex": 2, "explanation": "Sur une route étroite, il vaut mieux ralentir et patienter jusqu'à disposer d'un espace suffisant pour dépasser le cycliste en toute sécurité et à distance réglementaire."},
  {"id": "kq76", "type": "knowledge", "theme": "reglementation", "question": "Le permis de conduire français fonctionne sur un barème de :", "options": ["6 points maximum","20 points maximum","Il n'existe pas de système à points","12 points maximum"], "correctIndex": 3, "explanation": "Le permis de conduire dispose d'un capital initial de 12 points au maximum pour un conducteur expérimenté (hors période probatoire)."},
  {"id": "kq77", "type": "knowledge", "theme": "reglementation", "question": "Pendant la période probatoire, le capital de points du permis est de :", "options": ["6 points, augmentant progressivement jusqu'à 12","12 points dès l'obtention","3 points seulement","Il n'y a pas de limite"], "correctIndex": 0, "explanation": "En période probatoire, le permis démarre avec 6 points et gagne 2 points par an sans infraction (ou en une fois avec la conduite accompagnée), jusqu'à atteindre 12 points."},
  {"id": "kq78", "type": "knowledge", "theme": "reglementation", "question": "Lorsqu'un conducteur perd la totalité de ses points, son permis est :", "options": ["Suspendu pendant une semaine seulement","Invalidé ; il doit repasser le code (et parfois la conduite) après un délai","Automatiquement renouvelé","Sans conséquence s'il n'y a pas eu d'accident"], "correctIndex": 1, "explanation": "La perte totale des points entraîne l'invalidation du permis : le conducteur doit attendre un délai fixé par la loi avant de pouvoir repasser les examens."},
  {"id": "kq79", "type": "knowledge", "theme": "reglementation", "question": "L'assurance responsabilité civile automobile est :", "options": ["Facultative si le véhicule ne sort jamais","Réservée aux véhicules neufs","Obligatoire pour tout véhicule motorisé, même à l'arrêt sur la voie publique","Uniquement obligatoire sur autoroute"], "correctIndex": 2, "explanation": "Tout véhicule à moteur doit être couvert au minimum par une assurance responsabilité civile, dès lors qu'il est susceptible de circuler ou même simplement stationné sur la voie publique."},
  {"id": "kq80", "type": "knowledge", "theme": "reglementation", "question": "Le contrôle technique d'un véhicule particulier doit être renouvelé :", "options": ["Tous les ans, dès la première année","Une seule fois dans la vie du véhicule","Jamais s'il roule peu","Tous les 2 ans, après un premier contrôle 4 ans après la mise en circulation"], "correctIndex": 3, "explanation": "Après un premier contrôle technique 4 ans après la mise en circulation, celui-ci doit ensuite être renouvelé tous les 2 ans."},
  {"id": "kq81", "type": "knowledge", "theme": "reglementation", "question": "Conduire sans assurance expose à :", "options": ["Une amende importante, une possible confiscation du véhicule et d'autres sanctions","Une simple remarque orale","Aucune sanction si aucun accident n'a eu lieu","Une suspension de 3 jours seulement"], "correctIndex": 0, "explanation": "Défaut d'assurance est une infraction grave, sanctionnée par une amende pouvant être élevée, une possible confiscation du véhicule et d'autres peines complémentaires."},
  {"id": "kq82", "type": "knowledge", "theme": "reglementation", "question": "Les documents qu'un conducteur doit pouvoir présenter en cas de contrôle comprennent :", "options": ["Uniquement sa carte d'identité","Le permis de conduire, la carte grise et l'attestation d'assurance","Uniquement le certificat de contrôle technique","Aucun document n'est obligatoire"], "correctIndex": 1, "explanation": "En cas de contrôle, un conducteur doit pouvoir présenter son permis de conduire, le certificat d'immatriculation (carte grise) et l'attestation d'assurance du véhicule."},
  {"id": "kq83", "type": "knowledge", "theme": "reglementation", "question": "Un excès de vitesse inférieur à 20 km/h au-dessus de la limite autorisée entraîne :", "options": ["Aucune sanction","Un retrait automatique de 6 points","Une amende et un retrait d'au moins 1 point","Une suspension immédiate du permis"], "correctIndex": 2, "explanation": "Même un petit excès de vitesse (moins de 20 km/h au-dessus de la limite) donne lieu à une amende et à un retrait de points, généralement 1 point."},
  {"id": "kq84", "type": "knowledge", "theme": "reglementation", "question": "Un excès de vitesse de 50 km/h ou plus au-dessus de la limite autorisée constitue :", "options": ["Une simple contravention mineure","Une infraction sans incidence sur le permis","Un cas exceptionnel non prévu par la loi","Un délit, pouvant entraîner suspension du permis et lourde amende"], "correctIndex": 3, "explanation": "Un grand excès de vitesse (50 km/h et plus) est un délit : il peut entraîner une suspension immédiate du permis par les forces de l'ordre, une lourde amende et une comparution devant un tribunal."},
  {"id": "kq85", "type": "knowledge", "theme": "reglementation", "question": "Le non-respect d'un feu rouge ou d'un STOP entraîne généralement :", "options": ["Une amende et un retrait de 4 points","Aucun retrait de points","Un simple avertissement","Une amende sans retrait de points"], "correctIndex": 0, "explanation": "Griller un feu rouge ou un STOP est sanctionné par une amende forfaitaire et un retrait de 4 points sur le permis de conduire."},
  {"id": "kq86", "type": "knowledge", "theme": "reglementation", "question": "Le stationnement dit « très gênant » (sur trottoir, passage piéton, piste cyclable...) est sanctionné par une amende :", "options": ["Identique à un stationnement gênant classique","Plus élevée qu'un stationnement simplement gênant","Inexistante, ce n'est jamais verbalisé","Réservée aux seuls poids lourds"], "correctIndex": 1, "explanation": "Le stationnement très gênant, qui met en danger ou bloque fortement d'autres usagers, est sanctionné plus lourdement qu'un simple stationnement gênant."},
  {"id": "kq87", "type": "knowledge", "theme": "reglementation", "question": "Le délit de fuite après un accident expose à :", "options": ["Aucune sanction si le véhicule n'est pas endommagé","Une simple amende légère","De lourdes sanctions pénales, bien plus graves que l'accident lui-même","Une sanction uniquement civile"], "correctIndex": 2, "explanation": "Quitter les lieux d'un accident sans s'identifier constitue un délit pénal grave, souvent sanctionné plus lourdement que l'accident lui-même."},
  {"id": "kq88", "type": "knowledge", "theme": "reglementation", "question": "Vendre ou faire circuler un véhicule sans contrôle technique valide est :", "options": ["Autorisé si le véhicule a moins de 10 ans","Autorisé pour les particuliers uniquement","Sans conséquence","Interdit, sauf exceptions prévues par la loi"], "correctIndex": 3, "explanation": "Un véhicule doit disposer d'un contrôle technique en cours de validité pour circuler ou être vendu, sauf cas particuliers prévus par la réglementation."},
  {"id": "kq89", "type": "knowledge", "theme": "reglementation", "question": "L'immatriculation d'un véhicule doit être visible :", "options": ["À l'avant et à l'arrière du véhicule","Uniquement à l'arrière","Uniquement sur le pare-brise","Aucune plaque n'est obligatoire"], "correctIndex": 0, "explanation": "Un véhicule doit porter une plaque d'immatriculation réglementaire à l'avant et à l'arrière, lisible et conforme."},
  {"id": "kq90", "type": "knowledge", "theme": "reglementation", "question": "Le défaut de port de la ceinture de sécurité entraîne :", "options": ["Aucune sanction pour les passagers arrière","Une amende et un retrait de points pour la personne non attachée","Une sanction uniquement pour le conducteur, jamais pour les passagers","Un simple rappel à l'ordre"], "correctIndex": 1, "explanation": "Le non-port de la ceinture est sanctionné par une amende forfaitaire et un retrait de points, que ce soit pour le conducteur ou pour tout passager non attaché."},
  {"id": "kq91", "type": "knowledge", "theme": "reglementation", "question": "En France, un conducteur peut demander la restitution intégrale de ses points de permis après :", "options": ["1 an sans aucune infraction retirant des points","Un stage payant obligatoire à chaque fois","3 ans (ou 2 ans pour un simple retrait de 1 point) sans nouvelle infraction","Il n'est jamais possible de récupérer tous ses points"], "correctIndex": 2, "explanation": "Un conducteur récupère l'intégralité de ses points après un délai de 3 ans (ou 2 ans si seule une infraction à 1 point a été commise) sans nouvelle infraction entraînant un retrait."},
  {"id": "kq92", "type": "knowledge", "theme": "reglementation", "question": "Un grand excès de vitesse peut entraîner une rétention immédiate du permis par les forces de l'ordre :", "options": ["Faux, seul un juge peut retirer un permis","Uniquement en cas d'accident corporel","Uniquement pour les conducteurs étrangers","Vrai, une rétention immédiate est possible sur place"], "correctIndex": 3, "explanation": "En cas de grand excès de vitesse ou d'infraction grave (alcool, stupéfiants...), les forces de l'ordre peuvent procéder à une rétention immédiate du permis sur place."},
  {"id": "kq93", "type": "knowledge", "theme": "reglementation", "question": "Un jeune conducteur en période probatoire qui commet une infraction entraînant un retrait de 3 points ou plus :", "options": ["Peut être tenu de suivre un stage de sensibilisation obligatoire","N'a aucune obligation particulière","Perd automatiquement son permis","Doit repasser uniquement l'épreuve pratique"], "correctIndex": 0, "explanation": "En période probatoire, une infraction entraînant le retrait d'au moins 3 points peut obliger le conducteur à suivre un stage de sensibilisation à la sécurité routière."},
  {"id": "kq94", "type": "knowledge", "theme": "environnement", "question": "L'écoconduite consiste principalement à :", "options": ["Rouler le plus vite possible entre chaque feu","Anticiper la circulation pour limiter accélérations et freinages brusques","Couper le moteur en pleine conduite","Rouler uniquement de nuit"], "correctIndex": 1, "explanation": "L'écoconduite repose sur l'anticipation et la régularité de la conduite : moins d'accélérations et de freinages brusques réduisent la consommation et les émissions."},
  {"id": "kq95", "type": "knowledge", "theme": "environnement", "question": "La vignette Crit'Air permet :", "options": ["De payer moins cher ses amendes","D'obtenir une réduction sur le contrôle technique","De classer les véhicules selon leur niveau de pollution, notamment pour circuler en zone à faibles émissions","De rouler plus vite en ville"], "correctIndex": 2, "explanation": "La vignette Crit'Air classe les véhicules par niveau de pollution ; elle est notamment nécessaire pour circuler dans les zones à faibles émissions (ZFE)."},
  {"id": "kq96", "type": "knowledge", "theme": "environnement", "question": "Une zone à faibles émissions (ZFE) a pour but de :", "options": ["Favoriser les véhicules les plus polluants","Interdire tous les véhicules sans exception","Réduire uniquement le bruit","Restreindre ou interdire la circulation des véhicules les plus polluants dans certaines zones"], "correctIndex": 3, "explanation": "Les ZFE visent à améliorer la qualité de l'air en limitant ou en interdisant l'accès des véhicules les plus polluants à certaines zones urbaines."},
  {"id": "kq97", "type": "knowledge", "theme": "environnement", "question": "Couper le moteur lors d'un arrêt prolongé (feu long, passage à niveau) permet de :", "options": ["Réduire la consommation de carburant et les émissions inutiles","Augmenter la pollution","Endommager systématiquement le moteur","N'a aucun effet"], "correctIndex": 0, "explanation": "Couper le moteur lors d'un arrêt prolongé évite une consommation et des émissions inutiles, sans risque pour un moteur en bon état."},
  {"id": "kq98", "type": "knowledge", "theme": "environnement", "question": "Une conduite avec des accélérations progressives, plutôt que brusques, permet de :", "options": ["Consommer davantage de carburant","Réduire la consommation de carburant et les émissions de CO2","N'a aucun impact sur la consommation","Uniquement d'améliorer le confort, pas la pollution"], "correctIndex": 1, "explanation": "Des accélérations progressives sollicitent moins le moteur et réduisent la consommation de carburant ainsi que les émissions de CO2."},
  {"id": "kq99", "type": "knowledge", "theme": "environnement", "question": "Un entretien régulier du véhicule (filtres, moteur, pneus) contribue à :", "options": ["Augmenter la pollution","N'a aucun effet sur l'environnement","Réduire la consommation et les émissions polluantes","Uniquement à améliorer l'esthétique du véhicule"], "correctIndex": 2, "explanation": "Un véhicule bien entretenu consomme moins et pollue moins : filtres propres, moteur réglé et pneus corrects optimisent le fonctionnement."},
  {"id": "kq100", "type": "knowledge", "theme": "environnement", "question": "Le covoiturage contribue à réduire l'impact environnemental de la route principalement en :", "options": ["Augmentant le nombre de véhicules en circulation","N'ayant aucun effet sur le trafic","Concernant uniquement les trajets longue distance","Réduisant le nombre de véhicules utilisés pour un même trajet"], "correctIndex": 3, "explanation": "En partageant un même véhicule pour un trajet, le covoiturage réduit le nombre total de véhicules en circulation, donc les émissions et la congestion."},
  {"id": "kq101", "type": "knowledge", "theme": "environnement", "question": "Des pneus sous-gonflés entraînent :", "options": ["Une consommation de carburant augmentée et une usure prématurée","Une consommation de carburant réduite","Aucun effet sur la consommation","Une meilleure adhérence dans tous les cas"], "correctIndex": 0, "explanation": "Des pneus sous-gonflés augmentent la résistance au roulement, ce qui accroît la consommation de carburant et use les pneus plus rapidement."},
  {"id": "kq102", "type": "knowledge", "theme": "environnement", "question": "Rouler à vitesse stabilisée plutôt qu'en accélérant et freinant sans cesse permet de :", "options": ["Consommer plus de carburant","Réduire significativement la consommation de carburant","N'a aucun effet mesurable","Uniquement de gagner du temps"], "correctIndex": 1, "explanation": "Une vitesse stabilisée, sans à-coups, réduit nettement la consommation de carburant par rapport à une conduite en accélérations et freinages répétés."},
  {"id": "kq103", "type": "knowledge", "theme": "environnement", "question": "Transporter un poids inutile dans son véhicule (coffre chargé, galerie non utilisée) :", "options": ["N'a aucun impact sur la consommation","Réduit la consommation de carburant","Augmente la consommation de carburant","Améliore l'aérodynamisme"], "correctIndex": 2, "explanation": "Un poids ou une résistance aérodynamique supplémentaire (charge inutile, galerie de toit) augmente la consommation de carburant du véhicule."},
  {"id": "kq104", "type": "knowledge", "theme": "environnement", "question": "L'usage intensif de la climatisation en ville :", "options": ["N'a aucun effet sur la consommation de carburant","Réduit systématiquement la consommation","Concerne uniquement les véhicules électriques","Peut augmenter sensiblement la consommation de carburant"], "correctIndex": 3, "explanation": "La climatisation sollicite le moteur (ou la batterie) et peut augmenter sensiblement la consommation, en particulier en usage intensif en ville."},
  {"id": "kq105", "type": "knowledge", "theme": "environnement", "question": "Le transport routier est l'une des principales sources d'émissions de :", "options": ["Dioxyde de carbone (CO2), un gaz à effet de serre","Oxygène pur","Vapeur d'eau uniquement inoffensive","Aucun gaz notable"], "correctIndex": 0, "explanation": "Le transport routier est l'un des principaux secteurs émetteurs de CO2, un gaz à effet de serre qui contribue au réchauffement climatique."},
  {"id": "kq106", "type": "knowledge", "theme": "environnement", "question": "Sur une place de stationnement équipée d'une borne de recharge pour véhicule électrique :", "options": ["Tout véhicule peut se garer sans restriction","Le stationnement est réservé aux véhicules en cours de recharge","Seuls les poids lourds peuvent s'y garer","Aucune règle particulière ne s'applique"], "correctIndex": 1, "explanation": "Ces places sont réservées aux véhicules électriques ou hybrides rechargeables en cours de recharge ; les autres véhicules ne doivent pas y stationner."},
  {"id": "kq107", "type": "knowledge", "theme": "environnement", "question": "L'utilisation du régulateur de vitesse sur autoroute, en conditions stables, peut aider à :", "options": ["Augmenter la consommation de carburant","Rendre la conduite plus dangereuse dans tous les cas","Maintenir une vitesse stable et réduire la consommation","N'a aucun effet sur l'écoconduite"], "correctIndex": 2, "explanation": "En maintenant une vitesse constante sur autoroute, le régulateur évite les variations inutiles de vitesse et peut contribuer à réduire la consommation."},
  {"id": "kq108", "type": "knowledge", "theme": "environnement", "question": "Un filtre à particules encrassé sur un véhicule diesel entraîne :", "options": ["Une réduction de la pollution","Aucun effet sur les émissions","Une amélioration de la consommation","Une augmentation des émissions polluantes et des risques de panne"], "correctIndex": 3, "explanation": "Un filtre à particules encrassé ou défaillant laisse passer davantage de particules polluantes et peut entraîner des dysfonctionnements du moteur."},
  {"id": "kq109", "type": "knowledge", "theme": "notions", "question": "Un enfant de moins de 10 ans doit voyager :", "options": ["Dans un dispositif de retenue adapté à sa taille et son poids","Sans dispositif particulier s'il est calme","Uniquement sur les genoux d'un adulte","Debout à l'arrière, tenu par la ceinture d'un adulte"], "correctIndex": 0, "explanation": "Tout enfant de moins de 10 ans doit être installé dans un dispositif de retenue homologué (siège auto, réhausseur) adapté à sa morphologie."},
  {"id": "kq110", "type": "knowledge", "theme": "notions", "question": "Un enfant mesurant moins de 135 cm doit :", "options": ["Voyager sans aucune retenue spécifique","Utiliser un siège auto ou un réhausseur adapté à sa taille","S'asseoir obligatoirement à l'avant","Porter uniquement un casque"], "correctIndex": 1, "explanation": "En dessous de 135 cm, un enfant doit obligatoirement être installé dans un système de retenue adapté (siège auto ou réhausseur), sauf exceptions très limitées."},
  {"id": "kq111", "type": "knowledge", "theme": "notions", "question": "Installer un siège enfant dos à la route à l'avant nécessite de :", "options": ["Ne rien faire de particulier","Retirer la ceinture de sécurité du véhicule","Désactiver l'airbag frontal passager","Installer le siège face à la route uniquement"], "correctIndex": 2, "explanation": "Un siège dos à la route ne doit jamais être installé à l'avant avec un airbag frontal actif : celui-ci doit impérativement être désactivé, sous peine de danger grave pour l'enfant."},
  {"id": "kq112", "type": "knowledge", "theme": "notions", "question": "Un chargement qui dépasse à l'arrière du véhicule doit :", "options": ["Rester invisible pour ne pas gêner","Ne jamais dépasser de plus de 10 cm sans aucune règle","Être ignoré s'il fait moins d'un mètre","Être signalé par un dispositif visible (panneau, tissu rouge et blanc, etc.)"], "correctIndex": 3, "explanation": "Tout chargement dépassant l'aplomb du véhicule doit être signalé par un dispositif visible, conforme à la réglementation, afin d'alerter les autres usagers."},
  {"id": "kq113", "type": "knowledge", "theme": "notions", "question": "Avec un permis B classique, on peut en général tracter une remorque à condition que :", "options": ["Le poids total en charge de l'ensemble ne dépasse pas certaines limites réglementaires","Il n'existe aucune limite de poids","Seul un permis remorque spécifique le permette dans tous les cas","La remorque soit toujours vide"], "correctIndex": 0, "explanation": "Le permis B permet de tracter une remorque dans certaines limites de poids total en charge de l'ensemble véhicule + remorque, au-delà desquelles une formation ou catégorie supplémentaire est nécessaire."},
  {"id": "kq114", "type": "knowledge", "theme": "notions", "question": "Un chargement mal arrimé qui se détache sur la route constitue :", "options": ["Une simple négligence sans conséquence légale","Une infraction pouvant être sanctionnée, en plus du danger créé","Un cas de force majeure toujours excusé","Une situation sans rapport avec le conducteur"], "correctIndex": 1, "explanation": "Un chargement mal arrimé qui se détache est dangereux et engage la responsabilité du conducteur, en plus d'être une infraction sanctionnable."},
  {"id": "kq115", "type": "knowledge", "theme": "notions", "question": "Le poids total en charge d'un véhicule (chargement inclus) doit respecter :", "options": ["Aucune limite particulière","Uniquement le bon sens du conducteur","Le poids total autorisé en charge (PTAC) indiqué sur la carte grise","La seule limite est le volume du coffre"], "correctIndex": 2, "explanation": "Le poids total en charge doit respecter le PTAC indiqué sur le certificat d'immatriculation, sous peine de sanctions et de risques pour la tenue de route."},
  {"id": "kq116", "type": "knowledge", "theme": "notions", "question": "Le covoiturage régulier permet notamment de :", "options": ["Augmenter la congestion routière","Est interdit en France","N'a aucun avantage pratique","Réduire le nombre de véhicules en circulation et partager les frais de trajet"], "correctIndex": 3, "explanation": "Le covoiturage permet de réduire le nombre de véhicules utilisés pour un même trajet tout en partageant les frais entre les passagers."},
  {"id": "kq117", "type": "knowledge", "theme": "notions", "question": "Le transport d'un animal dans le véhicule doit se faire :", "options": ["De façon sécurisée (caisse de transport, harnais, grille de séparation...)","Librement sans aucune précaution","Uniquement sur les genoux du conducteur","Interdit dans tous les cas"], "correctIndex": 0, "explanation": "Un animal doit être transporté de manière sécurisée, afin de ne pas gêner la conduite ni risquer de se blesser ou de blesser les occupants en cas de freinage."},
  {"id": "kq118", "type": "knowledge", "theme": "notions", "question": "En tractant une caravane ou une remorque, la vitesse maximale sur autoroute est en général :", "options": ["Identique à celle d'un véhicule seul (130 km/h)","Réduite par rapport à un véhicule seul, généralement 110 km/h","Illimitée","Réduite à 50 km/h"], "correctIndex": 1, "explanation": "Avec une remorque ou une caravane, la vitesse maximale autorisée sur autoroute est généralement abaissée, souvent à 110 km/h, en raison du poids et de l'inertie supplémentaires."},
  {"id": "kq119", "type": "knowledge", "theme": "notions", "question": "Avec une caravane large tractée, il est souvent nécessaire d'équiper le véhicule de :", "options": ["Rien de particulier","Feux de brouillard supplémentaires uniquement","Rétroviseurs additionnels élargis","Pneus spécifiques obligatoires"], "correctIndex": 2, "explanation": "Des rétroviseurs élargis peuvent être nécessaires pour compenser la largeur de la caravane et assurer une visibilité suffisante sur les côtés."},
  {"id": "kq120", "type": "knowledge", "theme": "notions", "question": "Un enfant ne peut en principe pas être installé à l'avant du véhicule :", "options": ["Quel que soit son âge, sans exception","Uniquement s'il pèse plus de 40 kg","Jamais, quelle que soit la configuration du véhicule","S'il est âgé de moins de 10 ans, sauf conditions particulières prévues par la loi"], "correctIndex": 3, "explanation": "En principe, un enfant de moins de 10 ans ne doit pas être installé à l'avant, sauf exceptions prévues (véhicule sans place arrière, sièges arrière déjà occupés par d'autres enfants, etc.), avec les précautions adaptées."},
  {"id": "kq121", "type": "knowledge", "theme": "notions", "question": "Le passager d'une moto ou d'un scooter doit obligatoirement :", "options": ["Porter un casque homologué et un équipement de protection adapté","N'avoir aucune obligation particulière","Se tenir uniquement avec les mains","Être majeur dans tous les cas"], "correctIndex": 0, "explanation": "Comme le conducteur, tout passager d'un deux-roues motorisé doit porter un casque homologué et un équipement de protection adapté (gants notamment)."},
  {"id": "kq122", "type": "knowledge", "theme": "notions", "question": "La conduite accompagnée (AAC) permet à un jeune conducteur de :", "options": ["Conduire seul dès 15 ans sans accompagnateur","Conduire dès 15 ans accompagné d'un conducteur expérimenté, avant de passer seul","Éviter de passer l'examen du permis","N'a aucune règle spécifique de vitesse"], "correctIndex": 1, "explanation": "L'apprentissage anticipé de la conduite (AAC) permet de conduire dès 15 ans accompagné d'un conducteur expérimenté, avant de se présenter à l'épreuve pratique du permis."},
  {"id": "kq123", "type": "knowledge", "theme": "notions", "question": "Un chargement dépassant l'arrière du véhicule de plus d'un mètre doit être signalé, y compris de nuit, par :", "options": ["Un simple morceau de tissu de couleur quelconque","Rien, la loi ne prévoit rien","Un panneau ou dispositif réglementaire visible, y compris réfléchissant la nuit","Uniquement un clignotant supplémentaire"], "correctIndex": 2, "explanation": "Un chargement qui dépasse significativement doit être signalé par un dispositif réglementaire (panneau à bandes rouges et blanches), visible également de nuit grâce à un système réfléchissant."},
  {"id": "kq124", "type": "knowledge", "theme": "securite_passagers", "question": "Le port de la ceinture de sécurité est obligatoire :", "options": ["Uniquement pour le conducteur","Uniquement à l'avant","Uniquement en dehors des agglomérations","Pour tous les occupants du véhicule, à l'avant comme à l'arrière"], "correctIndex": 3, "explanation": "La ceinture de sécurité doit être portée par tous les occupants du véhicule, à l'avant comme à l'arrière, dès que des ceintures sont installées."},
  {"id": "kq125", "type": "knowledge", "theme": "securite_passagers", "question": "Le non-port de la ceinture de sécurité est sanctionné par :", "options": ["Une amende de 135€ et un retrait de 3 points","Un simple avertissement","Une amende sans retrait de points","Aucune sanction pour les passagers"], "correctIndex": 0, "explanation": "Le défaut de port de la ceinture entraîne une amende forfaitaire de 135€ et un retrait de 3 points sur le permis de la personne non attachée."},
  {"id": "kq126", "type": "knowledge", "theme": "securite_passagers", "question": "Le port du casque est obligatoire :", "options": ["Uniquement pour le conducteur d'un deux-roues motorisé","Pour le conducteur et tout passager d'un deux-roues motorisé","Uniquement sur autoroute","Uniquement pour les trajets longs"], "correctIndex": 1, "explanation": "Le casque homologué est obligatoire aussi bien pour le conducteur que pour tout passager d'un deux-roues motorisé, quelle que soit la distance à parcourir."},
  {"id": "kq127", "type": "knowledge", "theme": "securite_passagers", "question": "Un siège enfant installé dos à la route à l'avant impose :", "options": ["De laisser l'airbag frontal actif","De retirer le siège avant tout freinage","De désactiver impérativement l'airbag frontal passager","N'impose aucune précaution"], "correctIndex": 2, "explanation": "Le déclenchement d'un airbag frontal sur un siège dos à la route peut gravement blesser l'enfant : la désactivation de l'airbag est impérative dans ce cas."},
  {"id": "kq128", "type": "knowledge", "theme": "securite_passagers", "question": "Les sièges auto homologués sont généralement classés selon :", "options": ["La couleur du véhicule","La marque du véhicule","L'âge du conducteur","Le poids ou la taille de l'enfant (groupes 0+, 1, 2, 3 ou norme i-Size)"], "correctIndex": 3, "explanation": "Les sièges auto sont homologués selon des groupes basés sur le poids (0+, 1, 2, 3) ou, plus récemment, selon la taille de l'enfant pour la norme i-Size."},
  {"id": "kq129", "type": "knowledge", "theme": "securite_passagers", "question": "Un enfant de moins de 10 ans doit en principe voyager :", "options": ["À l'arrière du véhicule, sauf exceptions prévues par la loi","À l'avant, sans exception","Debout, tenu par un adulte","Sans aucune retenue si le trajet est court"], "correctIndex": 0, "explanation": "Sauf exceptions prévues par la réglementation, un enfant de moins de 10 ans doit être installé à l'arrière du véhicule, dans un dispositif adapté."},
  {"id": "kq130", "type": "knowledge", "theme": "securite_passagers", "question": "Le casque d'un motard doit impérativement être :", "options": ["Simplement posé sur la tête sans être attaché","Correctement attaché avec la jugulaire fermée","Retiré dès l'arrêt à un feu","Facultatif en ville"], "correctIndex": 1, "explanation": "Un casque non attaché ne protège pas efficacement en cas de choc : la jugulaire doit toujours être correctement fermée avant de rouler."},
  {"id": "kq131", "type": "knowledge", "theme": "securite_passagers", "question": "Le gilet de haute visibilité doit être enfilé par le conducteur :", "options": ["Uniquement s'il pleut","Uniquement dans les zones urbaines","Avant de sortir du véhicule en cas de panne ou d'accident, notamment de nuit ou sur autoroute","Jamais, ce n'est pas obligatoire en France"], "correctIndex": 2, "explanation": "En cas d'arrêt d'urgence ou de panne, il faut enfiler le gilet haute visibilité avant de sortir du véhicule, pour être vu par les autres usagers, en particulier de nuit ou sur autoroute."},
  {"id": "kq132", "type": "knowledge", "theme": "securite_passagers", "question": "Une ceinture de sécurité à trois points offre :", "options": ["Une protection identique à une ceinture ventrale seule","Une protection inférieure à l'absence de ceinture","Aucun avantage particulier","Une meilleure répartition des forces et une meilleure protection qu'une ceinture ventrale seule"], "correctIndex": 3, "explanation": "La ceinture trois points répartit les forces sur le bassin et le buste, offrant une protection nettement supérieure à une simple ceinture ventrale."},
  {"id": "kq133", "type": "knowledge", "theme": "securite_passagers", "question": "Les airbags du véhicule :", "options": ["Complètent la ceinture de sécurité mais ne la remplacent pas","Remplacent totalement la ceinture de sécurité","Sont inutiles si la ceinture est attachée","Ne servent qu'en cas de choc arrière"], "correctIndex": 0, "explanation": "Les airbags sont conçus pour compléter la ceinture de sécurité, pas pour la remplacer : leur efficacité est optimale seulement si la ceinture est également attachée."},
  {"id": "kq134", "type": "knowledge", "theme": "securite_passagers", "question": "Il est recommandé de maintenir un enfant dans un siège dos à la route :", "options": ["Le moins longtemps possible","Le plus longtemps possible, tant que sa taille le permet","Uniquement jusqu'à 6 mois","Cela n'a aucune importance pour la sécurité"], "correctIndex": 1, "explanation": "Voyager dos à la route protège mieux la tête et la nuque de l'enfant en cas de choc frontal ; il est donc recommandé de conserver cette position le plus longtemps possible."},
  {"id": "kq135", "type": "knowledge", "theme": "securite_passagers", "question": "Le verrouillage de sécurité enfant sur les portières arrière sert à :", "options": ["Empêcher les portières de se fermer","Activer automatiquement les airbags","Bloquer l'ouverture des portières de l'intérieur pour éviter une ouverture accidentelle","N'a aucune utilité pratique"], "correctIndex": 2, "explanation": "Ce dispositif empêche l'ouverture des portières arrière depuis l'intérieur, évitant qu'un enfant ne les ouvre accidentellement en roulant."},
  {"id": "kq136", "type": "knowledge", "theme": "securite_passagers", "question": "Ne pas utiliser un dispositif de retenue adapté pour un enfant expose le conducteur à :", "options": ["Aucune conséquence","Une simple mise en garde verbale","Une sanction uniquement en cas d'accident","Une amende et un retrait de points"], "correctIndex": 3, "explanation": "L'absence de dispositif de retenue adapté pour un enfant qui doit en être équipé est sanctionnée par une amende et un retrait de points."},
  {"id": "kq137", "type": "knowledge", "theme": "securite_passagers", "question": "Un appui-tête correctement réglé permet notamment de :", "options": ["Réduire le risque de coup du lapin (traumatisme cervical) en cas de choc arrière","N'a aucun rôle en cas d'accident","Uniquement améliorer le confort de conduite","Remplacer la ceinture de sécurité"], "correctIndex": 0, "explanation": "Un appui-tête bien positionné, proche de la tête, limite le mouvement brusque de la nuque en cas de choc arrière et réduit le risque de traumatisme cervical."},
  {"id": "kq138", "type": "knowledge", "theme": "securite_passagers", "question": "Concernant les vitres avant du véhicule, la réglementation impose :", "options": ["Aucune règle de transparence","Un niveau de transparence minimal pour le pare-brise et les vitres avant","Une teinte obligatoire foncée","Des vitres opaques autorisées à l'avant"], "correctIndex": 1, "explanation": "La réglementation impose un niveau minimal de transparence pour le pare-brise et les vitres avant, afin de garantir une bonne visibilité du conducteur et des autres usagers."},
  {"id": "kq139", "type": "knowledge", "theme": "securite_passagers", "question": "En cas de choc, un passager non attaché à l'arrière :", "options": ["Ne représente aucun danger pour les autres occupants","Est automatiquement protégé par les airbags avant","Peut être projeté et blesser gravement les occupants situés devant lui","N'a aucune obligation légale d'être attaché"], "correctIndex": 2, "explanation": "Un passager arrière non attaché peut être projeté violemment vers l'avant lors d'un choc et blesser gravement les occupants situés devant lui, en plus de se mettre lui-même en danger."},
  {"id": "kq140", "type": "knowledge", "theme": "equipements", "question": "Le kit de sécurité obligatoire à bord d'une voiture comprend au minimum :", "options": ["Un extincteur et une trousse de secours","Une roue de secours uniquement","Rien n'est obligatoire en France","Un triangle de présignalisation et un gilet de haute visibilité"], "correctIndex": 3, "explanation": "Depuis 2008, tout véhicule doit disposer à bord d'un triangle de présignalisation et d'un gilet de haute visibilité, à utiliser en cas d'arrêt d'urgence."},
  {"id": "kq141", "type": "knowledge", "theme": "equipements", "question": "Le système ABS (antiblocage des roues) sert à :", "options": ["Éviter le blocage des roues lors d'un freinage brusque, pour garder la maîtrise du véhicule","Bloquer complètement les roues en cas de freinage","Augmenter la vitesse maximale du véhicule","Remplacer les freins classiques"], "correctIndex": 0, "explanation": "L'ABS empêche les roues de se bloquer lors d'un freinage d'urgence, ce qui permet de conserver la maîtrise de la direction du véhicule."},
  {"id": "kq142", "type": "knowledge", "theme": "equipements", "question": "Le système ESP (contrôle électronique de stabilité) intervient principalement pour :", "options": ["Augmenter la puissance du moteur","Corriger une perte d'adhérence ou un début de dérapage","Remplacer la ceinture de sécurité","Gonfler automatiquement les pneus"], "correctIndex": 1, "explanation": "L'ESP détecte une perte d'adhérence ou un début de dérapage et freine automatiquement certaines roues pour aider à stabiliser la trajectoire du véhicule."},
  {"id": "kq143", "type": "knowledge", "theme": "equipements", "question": "La profondeur minimale légale des sculptures d'un pneu en France est de :", "options": ["0,5 mm","4 mm","1,6 mm","Il n'existe pas de minimum légal"], "correctIndex": 2, "explanation": "La profondeur minimale légale des sculptures est de 1,6 mm ; en dessous, l'adhérence et l'évacuation de l'eau sont fortement compromises, surtout sur route mouillée."},
  {"id": "kq144", "type": "knowledge", "theme": "equipements", "question": "La pression des pneus doit idéalement être vérifiée :", "options": ["Une seule fois à l'achat du véhicule","Uniquement après un contrôle technique","Elle n'a pas besoin d'être vérifiée","Régulièrement, de préférence à froid"], "correctIndex": 3, "explanation": "La pression des pneus doit être contrôlée régulièrement, de préférence à froid (pneus non chauffés par la route), pour garantir sécurité et consommation optimales."},
  {"id": "kq145", "type": "knowledge", "theme": "equipements", "question": "Les feux de croisement doivent être allumés :", "options": ["De nuit et dès que la visibilité est insuffisante, même le jour (brouillard, forte pluie)","Uniquement en pleine nuit sur autoroute","Jamais en agglomération","Uniquement sur demande des forces de l'ordre"], "correctIndex": 0, "explanation": "Les feux de croisement sont obligatoires de nuit, mais aussi de jour dès que la visibilité est réduite (brouillard, forte pluie, tunnel)."},
  {"id": "kq146", "type": "knowledge", "theme": "equipements", "question": "Les feux de détresse (warnings) doivent être utilisés :", "options": ["En continu pendant tout trajet de nuit","En cas d'arrêt d'urgence, de danger ou pour signaler un ralentissement brutal","Uniquement pour se garer en double file","Jamais sur autoroute"], "correctIndex": 1, "explanation": "Les feux de détresse signalent un danger ou un arrêt d'urgence, par exemple en cas de panne ou pour avertir d'un ralentissement brutal de la circulation."},
  {"id": "kq147", "type": "knowledge", "theme": "equipements", "question": "Concernant l'extincteur dans une voiture particulière en France :", "options": ["Il est obligatoire dans tous les véhicules","Il remplace le triangle de présignalisation","Il n'est pas obligatoire pour une voiture particulière, mais reste recommandé","Il est obligatoire uniquement sur autoroute"], "correctIndex": 2, "explanation": "Contrairement à une idée reçue, l'extincteur n'est pas obligatoire dans une voiture particulière en France (à la différence de certains véhicules professionnels), mais il reste recommandé."},
  {"id": "kq148", "type": "knowledge", "theme": "equipements", "question": "Des essuie-glaces en mauvais état constituent :", "options": ["Un simple inconfort sans conséquence sur la sécurité","Un équipement facultatif","Un problème uniquement esthétique","Un risque pour la visibilité et un point de contrôle technique"], "correctIndex": 3, "explanation": "Des essuie-glaces usés ou inefficaces réduisent la visibilité par temps de pluie et constituent un point vérifié lors du contrôle technique."},
  {"id": "kq149", "type": "knowledge", "theme": "equipements", "question": "Avant de démarrer, il est important de régler :", "options": ["Ses rétroviseurs et son siège pour une bonne visibilité et posture de conduite","Uniquement le volume de l'autoradio","Uniquement la climatisation","Rien n'a besoin d'être réglé"], "correctIndex": 0, "explanation": "Régler correctement rétroviseurs et siège avant de démarrer est essentiel pour une bonne visibilité, réduire les angles morts et adopter une posture de conduite sûre."},
  {"id": "kq150", "type": "knowledge", "theme": "equipements", "question": "Vérifier le niveau d'huile moteur régulièrement permet de :", "options": ["N'a aucune utilité","Prévenir l'usure prématurée et les pannes moteur","Uniquement d'améliorer l'esthétique du moteur","Remplacer le contrôle technique"], "correctIndex": 1, "explanation": "Un niveau d'huile insuffisant peut endommager gravement le moteur ; une vérification régulière permet de prévenir l'usure prématurée et les pannes."},
  {"id": "kq151", "type": "knowledge", "theme": "equipements", "question": "Les feux de brouillard arrière doivent être utilisés :", "options": ["En permanence de nuit","Jamais, ils sont réservés aux professionnels","Uniquement lorsque la visibilité est inférieure à environ 50 mètres","Uniquement en ville"], "correctIndex": 2, "explanation": "Les feux de brouillard arrière, très puissants, ne doivent être utilisés qu'en cas de visibilité très réduite (moins de 50 mètres environ), pour ne pas éblouir les autres conducteurs."},
  {"id": "kq152", "type": "knowledge", "theme": "equipements", "question": "Concernant l'éthylotest à bord du véhicule :", "options": ["Il est obligatoire et sanctionné en son absence","Il remplace le triangle de sécurité","Il est obligatoire uniquement pour les jeunes conducteurs","Sa présence à bord n'est plus sanctionnée depuis 2013, bien qu'il reste recommandé"], "correctIndex": 3, "explanation": "L'obligation de disposer d'un éthylotest à bord existe toujours dans les textes, mais la sanction pour son absence a été supprimée en 2013 ; il reste néanmoins un outil de prévention recommandé."},
  {"id": "kq153", "type": "knowledge", "theme": "equipements", "question": "Avant un long trajet, il est recommandé de vérifier notamment :", "options": ["L'état des pneus, les niveaux de fluides et l'éclairage","Uniquement le niveau de carburant","Uniquement la propreté extérieure du véhicule","Rien de particulier n'est nécessaire"], "correctIndex": 0, "explanation": "Avant un long trajet, il est conseillé de vérifier l'état des pneus, les niveaux (huile, liquide de refroidissement, lave-glace) et le bon fonctionnement de l'éclairage."},
  {"id": "kq154", "type": "knowledge", "theme": "equipements", "question": "L'usage de l'avertisseur sonore (klaxon) est réservé :", "options": ["À un usage libre à tout moment en ville","À un danger immédiat, ou pour prévenir en cas de dépassement hors agglomération","Exclusivement à la nuit","Aux seuls véhicules prioritaires"], "correctIndex": 1, "explanation": "Le klaxon doit être utilisé uniquement en cas de danger immédiat en agglomération, ou pour avertir avant un dépassement hors agglomération ; un usage abusif est sanctionnable."},
  {"id": "kq155", "type": "knowledge", "theme": "equipements", "question": "Le triangle de présignalisation doit être placé, en cas de panne sur route normale, à une distance minimale d'environ :", "options": ["5 mètres","300 mètres","30 mètres","Il n'y a pas de distance recommandée"], "correctIndex": 2, "explanation": "Le triangle doit être positionné à une distance suffisante (environ 30 mètres minimum, davantage sur autoroute) pour prévenir les autres usagers à temps."},
  {"id": "kq156", "type": "knowledge", "theme": "secours", "question": "En cas d'accident, la conduite à tenir se résume par le sigle PAS, qui signifie :", "options": ["Prévenir, Attendre, Soigner","Partir, Appeler, Stationner","Patienter, Analyser, Signaler","Protéger, Alerter, Secourir"], "correctIndex": 3, "explanation": "PAS résume la marche à suivre : Protéger la zone, Alerter les secours, puis Secourir les victimes si l'on en a la capacité."},
  {"id": "kq157", "type": "knowledge", "theme": "secours", "question": "La première étape « Protéger » face à un accident consiste à :", "options": ["Sécuriser la zone pour éviter un sur-accident (signalisation, gilet, triangle)","Se précipiter immédiatement vers les victimes","Déplacer tous les véhicules impliqués","Appeler la famille des victimes"], "correctIndex": 0, "explanation": "Protéger consiste à sécuriser les lieux avant toute autre action, pour éviter qu'un nouvel accident ne se produise (baliser, se signaler, couper le contact des véhicules)."},
  {"id": "kq158", "type": "knowledge", "theme": "secours", "question": "En France, les numéros d'urgence à connaître comprennent notamment :", "options": ["Uniquement le 112","Le 15 (SAMU), le 17 (Police), le 18 (Pompiers) et le 112 (numéro d'urgence européen)","Uniquement le 18","Il n'existe qu'un seul numéro d'urgence"], "correctIndex": 1, "explanation": "Plusieurs numéros d'urgence existent en France : 15 pour le SAMU, 17 pour la police, 18 pour les pompiers, et le 112, numéro d'urgence unique valable partout en Europe."},
  {"id": "kq159", "type": "knowledge", "theme": "secours", "question": "La Position Latérale de Sécurité (PLS) s'applique à une victime :", "options": ["Consciente et qui parle normalement","En arrêt cardiaque","Inconsciente mais qui respire normalement","Qui se plaint uniquement de douleurs au bras"], "correctIndex": 2, "explanation": "La PLS est utilisée pour une victime inconsciente qui respire, afin de dégager ses voies respiratoires et éviter qu'elle ne s'étouffe en cas de vomissement."},
  {"id": "kq160", "type": "knowledge", "theme": "secours", "question": "Face à un motard accidenté portant son casque, il faut en principe :", "options": ["Le retirer systématiquement dès l'arrivée sur place","Le retirer uniquement s'il fait chaud","Le retirer pour vérifier son identité","Ne pas le retirer, sauf nécessité vitale absolue et avec les précautions adéquates"], "correctIndex": 3, "explanation": "Retirer le casque d'un motard accidenté peut aggraver une éventuelle blessure de la nuque ; il ne doit être retiré qu'en cas de nécessité vitale absolue (arrêt respiratoire par exemple) et avec grande précaution."},
  {"id": "kq161", "type": "knowledge", "theme": "secours", "question": "Un blessé conscient et douloureux après un accident doit en général être :", "options": ["Laissé dans la position où il se trouve, sauf danger immédiat (incendie, sur-accident)","Déplacé immédiatement pour plus de confort","Assis de force dans un véhicule","Mis debout pour vérifier qu'il tient sur ses jambes"], "correctIndex": 0, "explanation": "Sauf danger immédiat (incendie, risque de sur-accident), il ne faut pas déplacer un blessé, au risque d'aggraver d'éventuelles fractures ou lésions internes."},
  {"id": "kq162", "type": "knowledge", "theme": "secours", "question": "Avant de partir en trajet, il est conseillé de vérifier notamment le niveau :", "options": ["Uniquement du réservoir de carburant","D'huile moteur, de liquide de refroidissement et de lave-glace","Du volume de l'autoradio","De la pression des sièges"], "correctIndex": 1, "explanation": "Vérifier les niveaux essentiels (huile, liquide de refroidissement, lave-glace) avant un trajet permet d'anticiper d'éventuelles pannes ou surchauffes."},
  {"id": "kq163", "type": "knowledge", "theme": "secours", "question": "En cas de panne sur autoroute, il est recommandé de :", "options": ["Rester dans le véhicule sur la voie de circulation","Sortir du véhicule côté circulation","Se garer sur la bande d'arrêt d'urgence, mettre son gilet et se mettre à l'abri derrière la glissière","Marcher sur la chaussée pour signaler la panne aux autres véhicules"], "correctIndex": 2, "explanation": "En cas de panne sur autoroute, il faut se garer le plus à droite possible sur la BAU, enfiler son gilet avant de sortir, sortir côté passager si possible, et se mettre à l'abri derrière la glissière en attendant les secours."},
  {"id": "kq164", "type": "knowledge", "theme": "secours", "question": "Le triangle de présignalisation doit être posé, en cas de panne sur autoroute, en marchant :", "options": ["Sur la chaussée en direction de la circulation","Au milieu de la voie de circulation","Il n'est pas utile sur autoroute","Le long de la glissière de sécurité, à distance suffisante, jamais sur la chaussée"], "correctIndex": 3, "explanation": "Sur autoroute, il faut placer le triangle en restant à l'abri, en longeant la glissière de sécurité, sans jamais marcher sur la chaussée où circulent les véhicules."},
  {"id": "kq165", "type": "knowledge", "theme": "secours", "question": "Le numéro d'urgence européen 112 :", "options": ["Fonctionne dans tous les pays de l'Union européenne","Ne fonctionne qu'en France","Est réservé aux seuls appels professionnels","Ne permet pas de joindre les pompiers"], "correctIndex": 0, "explanation": "Le 112 est un numéro d'urgence unique, gratuit, joignable dans tous les pays de l'Union européenne, y compris depuis un téléphone sans carte SIM."},
  {"id": "kq166", "type": "knowledge", "theme": "secours", "question": "Lors d'un appel aux secours après un accident, il faut préciser notamment :", "options": ["Uniquement son propre nom","Le lieu précis, le nombre de victimes et leur état apparent","Uniquement la marque des véhicules impliqués","Rien n'a besoin d'être précisé, les secours localisent tout automatiquement"], "correctIndex": 1, "explanation": "Un appel de secours efficace précise la localisation exacte, le nombre de victimes, la nature de l'accident et l'état apparent des blessés, pour permettre une intervention adaptée."},
  {"id": "kq167", "type": "knowledge", "theme": "secours", "question": "Face à une hémorragie externe importante, le premier geste à effectuer est :", "options": ["Donner à boire à la victime","Retirer immédiatement l'objet en cause quelle que soit la situation","Comprimer fortement la plaie avec un tissu propre","Attendre l'arrivée des secours sans intervenir"], "correctIndex": 2, "explanation": "En cas d'hémorragie externe, il faut comprimer directement la plaie avec un tissu propre pour limiter la perte de sang, en attendant les secours."},
  {"id": "kq168", "type": "knowledge", "theme": "secours", "question": "Il ne faut jamais donner à boire ou à manger à un blessé grave car :", "options": ["Cela n'a aucune importance","Cela accélère toujours sa guérison","C'est uniquement une question de confort","Cela peut être dangereux, notamment en cas d'anesthésie ou de chirurgie à venir"], "correctIndex": 3, "explanation": "Donner à boire ou à manger à un blessé grave peut être risqué, en particulier en cas de besoin d'anesthésie ultérieure ; il vaut mieux s'abstenir et laisser agir les secours."},
  {"id": "kq169", "type": "knowledge", "theme": "secours", "question": "En cas de début d'incendie sous le capot du véhicule, il ne faut surtout pas :", "options": ["Ouvrir le capot en grand immédiatement, ce qui peut attiser les flammes","Couper le contact","S'éloigner du véhicule","Prévenir les secours"], "correctIndex": 0, "explanation": "Ouvrir le capot en grand apporte brusquement de l'oxygène au feu et peut aggraver l'incendie ; il vaut mieux couper le contact, s'éloigner et alerter les secours."},
  {"id": "kq170", "type": "knowledge", "theme": "secours", "question": "Face à une victime consciente qui se plaint de douleurs après un choc, il faut :", "options": ["La faire marcher pour vérifier qu'elle va bien","La rassurer, éviter de la mobiliser inutilement et attendre les secours","Lui masser énergiquement la zone douloureuse","L'installer immédiatement au volant d'un véhicule"], "correctIndex": 1, "explanation": "Il faut rassurer la victime, éviter tout mouvement inutile pouvant aggraver une éventuelle lésion, et attendre l'arrivée des secours en surveillant son état."},
  {"id": "kq171", "type": "knowledge", "theme": "secours", "question": "Après avoir alerté les secours, en attendant leur arrivée, il convient de :", "options": ["Quitter les lieux dès que possible","Déplacer les véhicules accidentés sans attendre","Rester sur place, si possible en sécurité, pour surveiller la victime et guider les secours","Empêcher toute autre personne de s'approcher, même pour aider"], "correctIndex": 2, "explanation": "Il faut rester sur place en sécurité pour surveiller l'évolution de l'état de la victime et guider les secours à leur arrivée sur les lieux."},
  {"id": "kq172", "type": "knowledge", "theme": "circulation", "question": "Hors agglomération, sur une route à double sens sans séparateur central, la vitesse maximale par défaut est :", "options": ["110 km/h","90 km/h","70 km/h","80 km/h"], "correctIndex": 3, "explanation": "Depuis la réforme de 2018, la vitesse par défaut hors agglomération sur une route bidirectionnelle sans séparateur central est de 80 km/h, certains départements pouvant relever cette limite à 90 km/h par arrêté et signalisation spécifique."},
  {"id": "kq173", "type": "knowledge", "theme": "circulation", "question": "Hors agglomération, sur une route à chaussées séparées par un terre-plein central (2x2 voies) sans autre limitation signalée, la vitesse maximale est de :", "options": ["110 km/h","130 km/h","90 km/h","80 km/h"], "correctIndex": 0, "explanation": "Sur une route à chaussées séparées par un terre-plein central, la vitesse maximale par défaut est de 110 km/h, contre 130 km/h réservés aux autoroutes."},
  {"id": "kq174", "type": "knowledge", "theme": "circulation", "question": "À l'approche d'un passage à niveau dont les barrières s'abaissent ou dont le feu rouge clignote, un conducteur doit :", "options": ["Accélérer pour passer avant la fermeture","S'arrêter, même si le passage semble encore libre","Klaxonner puis continuer prudemment","Faire demi-tour immédiatement sur la voie"], "correctIndex": 1, "explanation": "Dès que le feu rouge clignote ou que les barrières commencent à s'abaisser, l'arrêt est obligatoire : il ne faut jamais tenter de franchir un passage à niveau en cours de fermeture."},
  {"id": "kq175", "type": "knowledge", "theme": "circulation", "question": "En cas d'aquaplaning (perte d'adhérence sur une flaque d'eau), la réaction correcte est de :", "options": ["Freiner fort et braquer pour se stabiliser","Accélérer pour retrouver le contact avec la route","Relâcher progressivement l'accélérateur sans freiner ni braquer brusquement","Donner un coup de frein à main"], "correctIndex": 2, "explanation": "En cas d'aquaplaning, il faut relâcher doucement l'accélérateur, garder le volant droit et éviter tout freinage ou braquage brusque tant que l'adhérence n'est pas retrouvée."},
  {"id": "kq176", "type": "knowledge", "theme": "circulation", "question": "Dépasser un véhicule au sommet d'une côte ou juste avant un sommet de côte est :", "options": ["Autorisé si la route est large","Autorisé uniquement de jour","Autorisé pour les motos uniquement","Interdit en raison du manque de visibilité sur ce qui arrive en face"], "correctIndex": 3, "explanation": "Le sommet d'une côte réduit fortement la visibilité sur la voie opposée ; dépasser à cet endroit est interdit car un véhicule peut survenir en face sans que l'on puisse l'anticiper."},
  {"id": "kq177", "type": "knowledge", "theme": "circulation", "question": "En agglomération, lorsqu'un autobus signale son intention de quitter un arrêt, les autres véhicules doivent :", "options": ["Lui céder le passage si la vitesse est limitée à 50 km/h ou moins","Continuer normalement, le bus doit attendre","Accélérer pour le doubler avant qu'il ne démarre","Klaxonner pour l'empêcher de partir"], "correctIndex": 0, "explanation": "Depuis 2015, en agglomération où la vitesse est limitée à 50 km/h ou moins, les véhicules doivent céder le passage à un autobus ou autocar qui signale son intention de quitter son arrêt."},
  {"id": "kq178", "type": "knowledge", "theme": "circulation", "question": "En circulant dans un tunnel, il est recommandé de :", "options": ["Réduire ses distances de sécurité pour ne pas gêner","Conserver une distance de sécurité accrue et ne s'arrêter qu'en cas d'urgence absolue","Couper ses feux pour ne pas éblouir","Doubler librement quelle que soit la signalisation"], "correctIndex": 1, "explanation": "Dans un tunnel, il faut garder une distance de sécurité importante, allumer ses feux de croisement, et ne s'arrêter qu'en cas d'urgence absolue, en utilisant si besoin les issues de secours."},
  {"id": "kq179", "type": "knowledge", "theme": "circulation", "question": "À l'approche d'un véhicule prioritaire (pompiers, police, SAMU) circulant gyrophares et sirène activés, un conducteur doit :", "options": ["Accélérer pour dégager la route","L'ignorer si sa propre priorité est respectée","Faciliter son passage en se rangeant dès que possible, sans paniquer ni freiner brutalement","S'arrêter net sur place quelle que soit sa position"], "correctIndex": 2, "explanation": "Face à un véhicule d'intérêt général prioritaire, il faut faciliter son passage en se rangeant dès que possible, sans manœuvre brusque ni freinage dangereux pour les autres usagers."},
  {"id": "kq180", "type": "knowledge", "theme": "circulation", "question": "Face à un convoi exceptionnel précédé d'un véhicule pilote (gyrophare orange), un conducteur doit :", "options": ["Le doubler dès que possible sans attendre","L'ignorer, il n'a aucune priorité","S'arrêter immédiatement sur place","Suivre les indications du véhicule pilote et ne pas tenter de dépasser le convoi"], "correctIndex": 3, "explanation": "Un convoi exceptionnel est annoncé et encadré par des véhicules pilotes : il faut suivre leurs indications et ne jamais tenter de le dépasser sans y être invité."},
  {"id": "kq181", "type": "knowledge", "theme": "circulation", "question": "Le dépassement par la droite est :", "options": ["Interdit, sauf cas particuliers comme une file de véhicules à l'arrêt ou une chaussée à plusieurs voies dans le même sens","Autorisé dans toutes les circonstances","Autorisé uniquement sur autoroute","Autorisé uniquement pour les deux-roues"], "correctIndex": 0, "explanation": "Le dépassement par la droite est en principe interdit ; il n'est toléré que dans des cas particuliers, comme doubler une file de véhicules à l'arrêt ou circuler sur une chaussée à plusieurs voies dans le même sens en respectant la discipline de voie."},
  {"id": "kq182", "type": "knowledge", "theme": "circulation", "question": "Un panneau annonçant une « chaussée déformée » invite le conducteur à :", "options": ["Accélérer pour passer rapidement la zone","Réduire sa vitesse et rester attentif aux irrégularités de la route","Ignorer le panneau si la route paraît normale","S'arrêter obligatoirement"], "correctIndex": 1, "explanation": "Ce panneau de danger signale des irrégularités du revêtement (bosses, nids-de-poule) qui imposent de ralentir pour garder la maîtrise du véhicule."},
  {"id": "kq183", "type": "knowledge", "theme": "circulation", "question": "Dans un giratoire équipé de feux tricolores à son entrée, la règle qui prévaut est :", "options": ["Toujours la priorité aux véhicules déjà engagés dans l'anneau","La priorité à droite","Celle du feu tricolore, qui prime sur la règle générale du giratoire","Aucune règle ne s'applique, chacun se débrouille"], "correctIndex": 2, "explanation": "Lorsqu'un giratoire est équipé de feux tricolores, ceux-ci priment sur la règle habituelle de priorité à l'anneau : il faut respecter la signalisation lumineuse en priorité."},
  {"id": "kq184", "type": "knowledge", "theme": "circulation", "question": "En cas de début de dérapage de l'arrière du véhicule sur route glissante, il faut :", "options": ["Freiner immédiatement et fortement","Accélérer pour reprendre le contrôle","Tourner le volant fortement dans le sens opposé au dérapage","Relâcher l'accélérateur et braquer légèrement dans le sens du dérapage, sans freiner brusquement"], "correctIndex": 3, "explanation": "Face à un dérapage arrière, il faut relâcher doucement l'accélérateur et corriger la trajectoire en braquant légèrement dans le sens du dérapage, sans freiner ni braquer brutalement, ce qui aggraverait la perte de contrôle."},
  {"id": "kq185", "type": "knowledge", "theme": "circulation", "question": "Sur une portion de route réduite à une seule voie de circulation alternée (chantier), la priorité de passage est déterminée par :", "options": ["La signalisation en place : feux tricolores, panneaux ou agent régulant la circulation","Le véhicule le plus rapide","Toujours le sens montant","Le premier arrivé, sans autre règle"], "correctIndex": 0, "explanation": "Sur un alternat de circulation, la priorité est fixée par la signalisation mise en place (feux tricolores temporaires, panneaux B15/C18, ou agent), qu'il faut impérativement respecter."},
  {"id": "kq186", "type": "knowledge", "theme": "circulation", "question": "Dépasser dans un virage où la visibilité est insuffisante est :", "options": ["Autorisé si aucun véhicule n'est visible en face","Interdit, quelle que soit l'absence apparente de circulation","Autorisé uniquement de jour","Autorisé pour les véhicules les plus puissants"], "correctIndex": 1, "explanation": "Dans un virage sans visibilité suffisante, le dépassement est interdit car un véhicule peut arriver en sens inverse sans que l'on puisse l'anticiper à temps."},
  {"id": "kq187", "type": "knowledge", "theme": "circulation", "question": "En cas de véhicule circulant à contresens repéré sur autoroute (annonce radio ou panneau), il faut :", "options": ["Faire demi-tour pour l'éviter","Continuer normalement sans réagir","Ralentir, serrer à droite, ne jamais faire demi-tour ni marche arrière, et prévenir le 112","Accélérer pour s'éloigner rapidement"], "correctIndex": 2, "explanation": "Face à un véhicule fantôme circulant à contresens, il faut ralentir, se déporter à droite, ne jamais faire demi-tour ni marche arrière sur la chaussée, et alerter les secours dès que possible."},
  {"id": "kq188", "type": "knowledge", "theme": "circulation", "question": "En s'insérant sur autoroute depuis une bretelle d'accès, le conducteur doit :", "options": ["S'attendre à ce que les véhicules déjà sur l'autoroute s'écartent automatiquement","S'arrêter sur la voie d'insertion pour attendre une place","Klaxonner pour prévenir de son insertion","Adapter sa vitesse à celle du trafic avant de s'insérer, sans priorité particulière"], "correctIndex": 3, "explanation": "Le conducteur qui s'insère n'a pas la priorité : il doit utiliser la voie d'insertion pour accélérer et adapter sa vitesse à celle du flux avant de s'insérer en toute sécurité."},
  {"id": "kq189", "type": "knowledge", "theme": "circulation", "question": "Les distances de sécurité entre véhicules doivent être augmentées notamment :", "options": ["Par temps de pluie, de brouillard, de nuit ou sur chaussée glissante","Uniquement en cas de forte chaleur","Uniquement en agglomération","Jamais, la règle des deux secondes suffit toujours"], "correctIndex": 0, "explanation": "Les distances de sécurité doivent être augmentées dès que les conditions de visibilité ou d'adhérence se dégradent : pluie, brouillard, nuit, verglas ou neige."},
  {"id": "kq190", "type": "knowledge", "theme": "circulation", "question": "À un carrefour dont les feux tricolores sont totalement éteints (panne de courant), un conducteur doit :", "options": ["Passer sans précaution, aucun feu n'étant actif","Considérer le carrefour comme non réglementé et appliquer la priorité à droite","S'arrêter et attendre le retour du courant","Faire systématiquement demi-tour"], "correctIndex": 1, "explanation": "Lorsque des feux sont hors service, le carrefour redevient un carrefour sans signalisation : la priorité à droite s'applique, avec une vigilance renforcée."},
  {"id": "kq191", "type": "knowledge", "theme": "circulation", "question": "Coller délibérément au véhicule qui précède pour le presser d'accélérer ou de se déporter est :", "options": ["Une pratique tolérée si le trafic est fluide","Autorisé sur autoroute uniquement","Une infraction dangereuse, pouvant être sanctionnée comme du harcèlement routier","Sans conséquence tant qu'il n'y a pas de collision"], "correctIndex": 2, "explanation": "Ce comportement, appelé talonnage ou harcèlement routier, supprime toute distance de sécurité et constitue une infraction sanctionnée, indépendamment de tout accident."},
  {"id": "kq192", "type": "knowledge", "theme": "circulation", "question": "En cas de bouchon ou de circulation très ralentie sur une route à plusieurs voies, la formation d'un « corridor de secours » consiste à :", "options": ["Se placer tous sur la même voie pour laisser les autres libres","Arrêter complètement son véhicule au milieu de la voie","N'a aucune existence légale en France","Se serrer à droite sur la voie de droite et à gauche sur la voie de gauche pour laisser un passage central aux secours"], "correctIndex": 3, "explanation": "Depuis 2019, dès qu'une circulation est fortement ralentie ou à l'arrêt sur une route à plusieurs voies, les véhicules doivent se serrer à droite et à gauche pour créer un couloir central permettant aux secours et dépanneuses de circuler."},
  {"id": "kq193", "type": "knowledge", "theme": "circulation", "question": "Par vent latéral fort, notamment sur un pont ou dans une zone dégagée, un conducteur doit :", "options": ["Réduire sa vitesse, tenir fermement le volant et rester attentif aux rafales","Accélérer pour traverser la zone plus vite","Rouler au plus près du bord de la chaussée","N'y prêter aucune attention particulière"], "correctIndex": 0, "explanation": "Le vent latéral fort peut déporter un véhicule, en particulier les véhicules hauts, motos ou attelages : il faut ralentir et tenir fermement le volant pour anticiper les rafales."},
  {"id": "kq194", "type": "knowledge", "theme": "circulation", "question": "Un panneau de rappel de limitation de vitesse, identique au panneau initial mais placé plus loin sur le même axe, sert à :", "options": ["Annoncer une nouvelle limitation différente","Rappeler que la limitation précédemment annoncée reste en vigueur","Indiquer la fin de la limitation","N'a aucune utilité particulière"], "correctIndex": 1, "explanation": "Un panneau de rappel confirme qu'une limitation de vitesse déjà annoncée continue de s'appliquer sur un axe long, sans qu'elle ait changé entre-temps."},
  {"id": "kq195", "type": "knowledge", "theme": "conducteur", "question": "0,5 gramme d'alcool par litre de sang correspond, en air expiré, à environ :", "options": ["0,10 mg/L","0,50 mg/L","0,25 mg/L","1 mg/L"], "correctIndex": 2, "explanation": "Le taux légal de 0,5 g/L de sang correspond à environ 0,25 mg d'alcool par litre d'air expiré, seuil mesuré lors d'un contrôle par éthylotest ou éthylomètre."},
  {"id": "kq196", "type": "knowledge", "theme": "conducteur", "question": "L'alcool affecte la conduite principalement en :", "options": ["Améliorant les réflexes et la concentration","N'ayant aucun effet en dessous de 0,5 g/L","Améliorant l'appréciation des distances","Altérant les réflexes, la vision et en donnant une fausse impression de confiance"], "correctIndex": 3, "explanation": "Même à faible dose, l'alcool ralentit les réflexes, réduit le champ visuel et augmente la prise de risque en donnant une confiance excessive en ses capacités."},
  {"id": "kq197", "type": "knowledge", "theme": "conducteur", "question": "La conduite après une consommation d'alcool comprise entre 0,5 g/L et 0,8 g/L de sang constitue :", "options": ["Une contravention de 4e classe, avec amende et retrait de points","Un délit passible de prison","Une infraction sans aucune sanction","Un simple avertissement écrit"], "correctIndex": 0, "explanation": "Entre 0,5 et 0,8 g/L, l'infraction reste une contravention (4e classe) sanctionnée par une amende, un retrait de 6 points et une possible suspension du permis, sans être un délit."},
  {"id": "kq198", "type": "knowledge", "theme": "conducteur", "question": "Le temps nécessaire pour éliminer totalement l'alcool consommé dépend principalement de :", "options": ["Rien, l'organisme l'élimine instantanément","La quantité bue et le métabolisme de la personne ; ni le café ni une douche froide n'accélèrent l'élimination","Uniquement de la marque de boisson consommée","Du fait de manger ou non après avoir bu"], "correctIndex": 1, "explanation": "Seul le temps élimine l'alcool du sang (environ 0,10 à 0,15 g/L par heure) : café fort, douche froide ou exercice physique ne réduisent en rien l'alcoolémie réelle."},
  {"id": "kq199", "type": "knowledge", "theme": "conducteur", "question": "Un éthylotest affichant un résultat positif signifie que :", "options": ["Le conducteur peut prendre le volant sans risque","L'appareil est défectueux","Le taux d'alcoolémie dépasse probablement le seuil légal et il ne faut pas conduire","Il faut attendre 5 minutes puis reconduire un test avant de partir"], "correctIndex": 2, "explanation": "Un résultat positif à l'éthylotest indique un taux d'alcoolémie probablement supérieur à la limite légale : il ne faut alors pas prendre le volant."},
  {"id": "kq200", "type": "knowledge", "theme": "conducteur", "question": "La consommation de stupéfiants au volant, même en petite quantité, expose à :", "options": ["Une simple contravention légère","Aucune sanction tant qu'il n'y a pas d'accident","Une sanction uniquement administrative sans conséquence pénale","Un délit avec amende, retrait de points, suspension voire annulation du permis, et peine de prison possible"], "correctIndex": 3, "explanation": "Conduire après usage de stupéfiants est un délit pénal, sanctionné par une amende, un retrait de 6 points, une suspension ou annulation du permis, et jusqu'à deux ans de prison."},
  {"id": "kq201", "type": "knowledge", "theme": "conducteur", "question": "Associer la consommation d'alcool et de stupéfiants au volant :", "options": ["Constitue une double infraction aggravant fortement les sanctions","N'aggrave pas les sanctions","N'est jamais recherché lors d'un contrôle","Annule les effets négatifs de chaque substance"], "correctIndex": 0, "explanation": "Le cumul alcool et stupéfiants constitue une double infraction, avec des sanctions pénales aggravées, les effets des deux substances s'additionnant sur les capacités de conduite."},
  {"id": "kq202", "type": "knowledge", "theme": "conducteur", "question": "Un dépistage de stupéfiants après un contrôle positif se confirme généralement par :", "options": ["Un simple interrogatoire oral","Une analyse salivaire ou sanguine effectuée par un professionnel de santé","Un test visuel du conducteur","Il n'existe aucun moyen de confirmer un dépistage"], "correctIndex": 1, "explanation": "Un dépistage positif (test salivaire) est généralement confirmé par une analyse biologique (salivaire ou sanguine) réalisée par un professionnel de santé, avec valeur probante pour les poursuites."},
  {"id": "kq203", "type": "knowledge", "theme": "conducteur", "question": "Refuser de se soumettre à un contrôle d'alcoolémie ou de stupéfiants est :", "options": ["Sans conséquence, le refus n'étant pas une infraction","Autorisé si le conducteur invoque un motif religieux","Assimilé à une infraction grave, sanctionnée comme le délit lui-même","Autorisé une seule fois par an"], "correctIndex": 2, "explanation": "Le refus de se soumettre aux vérifications d'alcoolémie ou de dépistage de stupéfiants constitue en lui-même un délit, sanctionné aussi sévèrement que l'infraction qu'il visait à établir."},
  {"id": "kq204", "type": "knowledge", "theme": "conducteur", "question": "La fatigue au volant est responsable d'une part importante des accidents mortels sur autoroute, notamment parce qu'elle :", "options": ["N'a aucun impact réel sur la conduite","Concerne uniquement les trajets de nuit","Se manifeste uniquement chez les conducteurs âgés","Entraîne des micro-sommeils de quelques secondes, suffisants pour provoquer un accident"], "correctIndex": 3, "explanation": "La fatigue peut provoquer des micro-sommeils de quelques secondes, largement suffisants pour qu'un véhicule sorte de sa voie ou percute un obstacle à grande vitesse."},
  {"id": "kq205", "type": "knowledge", "theme": "conducteur", "question": "La meilleure prévention contre l'endormissement au volant lors d'un trajet long consiste à :", "options": ["Bien dormir avant le départ, faire des pauses régulières et s'arrêter au moindre signe de fatigue","Boire un café juste avant de partir et ne plus s'arrêter","Ouvrir les fenêtres en grand pendant tout le trajet","Écouter de la musique forte en continu"], "correctIndex": 0, "explanation": "La prévention efficace repose sur un sommeil suffisant avant le départ, des pauses régulières toutes les deux heures, et un arrêt immédiat dès les premiers signes de fatigue."},
  {"id": "kq206", "type": "knowledge", "theme": "conducteur", "question": "Envoyer ou lire un SMS en conduisant, même à l'arrêt à un feu rouge, est :", "options": ["Toléré tant que le véhicule est immobile","Interdit et sanctionné comme l'usage du téléphone tenu en main","Autorisé si le trajet est très court","Autorisé uniquement pour un message urgent"], "correctIndex": 1, "explanation": "L'usage d'un téléphone tenu en main est interdit même à l'arrêt à un feu ou dans un bouchon, tant que le moteur tourne : la sanction s'applique dans tous les cas."},
  {"id": "kq207", "type": "knowledge", "theme": "conducteur", "question": "Un kit mains-libres ou un système Bluetooth intégré pour téléphoner en conduisant est :", "options": ["Interdit dans tous les cas","Obligatoire pour tout appel au volant","Légalement toléré, mais fortement déconseillé car la distraction cognitive reste importante","Autorisé uniquement pour les professionnels"], "correctIndex": 2, "explanation": "Le kit mains-libres est légalement autorisé, contrairement au téléphone tenu en main, mais la conversation téléphonique elle-même détourne l'attention du conducteur et reste déconseillée."},
  {"id": "kq208", "type": "knowledge", "theme": "conducteur", "question": "Régler son GPS, sa musique ou sa climatisation devrait idéalement se faire :", "options": ["En roulant, à tout moment","Uniquement sur autoroute","Jamais, ces réglages sont interdits","Avant de démarrer ou à l'arrêt, pour ne pas détourner l'attention de la route"], "correctIndex": 3, "explanation": "Régler ses équipements avant le départ ou à l'arrêt évite de détourner le regard et l'attention de la route pendant la conduite, source fréquente d'accidents."},
  {"id": "kq209", "type": "knowledge", "theme": "conducteur", "question": "Le stress au volant peut se traduire notamment par :", "options": ["Une conduite plus agressive, une prise de risque accrue et une perte de concentration","Une conduite toujours plus prudente","Aucun effet mesurable sur la conduite","Une amélioration des réflexes"], "correctIndex": 0, "explanation": "Le stress altère le jugement et peut pousser à une conduite plus agressive (excès de vitesse, dépassements risqués) ou au contraire à une perte de concentration dangereuse."},
  {"id": "kq210", "type": "knowledge", "theme": "conducteur", "question": "Un conducteur qui se sent en colère après un différend sur la route devrait avant tout :", "options": ["Poursuivre l'autre véhicule pour s'expliquer","Se calmer, éviter toute réaction agressive et prendre de la distance si besoin","Klaxonner et faire des appels de phares en représailles","Le doubler dangereusement pour lui couper la route"], "correctIndex": 1, "explanation": "Face à la colère, il vaut mieux se calmer et éviter toute escalade : les comportements agressifs entre conducteurs sont une cause reconnue d'accidents graves."},
  {"id": "kq211", "type": "knowledge", "theme": "conducteur", "question": "Une bonne anticipation de la conduite consiste notamment à :", "options": ["Se concentrer uniquement sur le véhicule qui précède immédiatement","Ne regarder que dans le rétroviseur","Observer loin devant soi et analyser en permanence les dangers potentiels","Réagir seulement lorsque le danger est déjà là"], "correctIndex": 2, "explanation": "Anticiper, c'est regarder loin devant, repérer les indices de danger (piétons, intersections, véhicules qui ralentissent) avant qu'ils ne deviennent critiques."},
  {"id": "kq212", "type": "knowledge", "theme": "conducteur", "question": "Concernant les seniors au volant, la loi française impose :", "options": ["Un examen médical obligatoire à partir de 70 ans pour tous les conducteurs","Le retrait automatique du permis à 75 ans","Une limitation de vitesse spécifique après 70 ans","Aucun contrôle médical obligatoire systématique lié à l'âge pour un permis B classique"], "correctIndex": 3, "explanation": "Contrairement à une idée répandue, il n'existe pas en France de visite médicale obligatoire liée à l'âge pour conserver un permis B classique ; chacun reste responsable d'évaluer son aptitude à conduire."},
  {"id": "kq213", "type": "knowledge", "theme": "conducteur", "question": "Un conducteur souffrant d'une pathologie pouvant affecter sa vigilance (épilepsie non stabilisée, apnée du sommeil sévère non traitée...) :", "options": ["Doit consulter un médecin agréé pour évaluer son aptitude à la conduite","Peut conduire sans restriction dans tous les cas","N'a aucune obligation de déclaration","Perd automatiquement son permis à vie"], "correctIndex": 0, "explanation": "Certaines pathologies peuvent nécessiter une évaluation par un médecin agréé, qui détermine l'aptitude à la conduite et d'éventuelles restrictions ou un suivi régulier."},
  {"id": "kq214", "type": "knowledge", "theme": "conducteur", "question": "Le champ visuel utile à la conduite se réduit notamment :", "options": ["Lorsque la vitesse diminue","Lorsque la vitesse augmente ou en cas de fatigue et de distraction","Uniquement de nuit","Il ne varie jamais chez un même conducteur"], "correctIndex": 1, "explanation": "Le champ visuel utile se rétrécit avec l'augmentation de la vitesse, mais aussi sous l'effet de la fatigue, du stress ou de la distraction, réduisant la perception des dangers périphériques."},
  {"id": "kq215", "type": "knowledge", "theme": "conducteur", "question": "Porter des lunettes de vue ou de soleil adaptées est important car :", "options": ["Une bonne vision n'a pas d'impact sur la sécurité","Cela ralentit les réflexes","Une vision corrigée et adaptée à la luminosité améliore la perception des dangers","C'est uniquement une question de confort esthétique"], "correctIndex": 2, "explanation": "Une vision correctement corrigée, ainsi qu'une protection adaptée contre l'éblouissement, sont essentielles pour percevoir à temps les dangers sur la route."},
  {"id": "kq216", "type": "knowledge", "theme": "conducteur", "question": "L'accompagnateur en conduite accompagnée (AAC) doit notamment :", "options": ["Être titulaire du permis depuis moins d'un an","N'avoir aucune condition particulière à remplir","Avoir plus de 65 ans obligatoirement","Être titulaire du permis B depuis au moins 5 ans sans interruption liée à une suspension ou annulation"], "correctIndex": 3, "explanation": "L'accompagnateur doit être titulaire du permis B depuis au moins 5 ans sans interruption due à une annulation ou une suspension, afin de garantir une expérience suffisante pour encadrer l'apprenti conducteur."},
  {"id": "kq217", "type": "knowledge", "theme": "conducteur", "question": "Pendant la conduite accompagnée, l'apprenti conducteur doit respecter :", "options": ["Des vitesses maximales légèrement réduites par rapport aux limites générales","Les mêmes limitations de vitesse que tout conducteur, sans réduction spécifique","Aucune limite de vitesse particulière","Une vitesse fixe de 50 km/h partout"], "correctIndex": 0, "explanation": "Pendant l'AAC, des vitesses maximales légèrement inférieures aux limites générales s'appliquent (par exemple sur autoroute), afin de sécuriser l'apprentissage."},
  {"id": "kq218", "type": "knowledge", "theme": "conducteur", "question": "Un conducteur en permis probatoire doit apposer sur son véhicule :", "options": ["Un disque bleu à l'avant du véhicule","Un disque « P » rouge sur fond blanc, visible à l'arrière","Aucun signe distinctif n'est requis","Un gilet fluorescent en permanence sur le tableau de bord"], "correctIndex": 1, "explanation": "Le conducteur novice doit apposer à l'arrière de son véhicule un disque « A » (lettre A rouge sur fond blanc), visible par les autres usagers, pendant toute la durée du permis probatoire."},
  {"id": "kq219", "type": "knowledge", "theme": "conducteur", "question": "En période probatoire, la vitesse maximale autorisée sur autoroute est réduite à :", "options": ["130 km/h comme tout conducteur","90 km/h dans tous les cas","110 km/h au lieu de 130 km/h","70 km/h"], "correctIndex": 2, "explanation": "Un conducteur en période probatoire est limité à 110 km/h sur autoroute (au lieu de 130 km/h), une réduction similaire s'appliquant aussi sur les autres types de routes."},
  {"id": "kq220", "type": "knowledge", "theme": "conducteur", "question": "La visibilité réduite due à un pare-brise sale ou à des vitres embuées doit être traitée :", "options": ["En roulant plus vite pour arriver rapidement","Uniquement si un contrôle de police est prévu","Elle n'a pas d'incidence réelle sur la conduite","Avant de démarrer ou en s'arrêtant si nécessaire, la visibilité étant essentielle à la sécurité"], "correctIndex": 3, "explanation": "Un pare-brise sale ou embué réduit dangereusement la visibilité : il faut le nettoyer avant de partir ou s'arrêter dès que possible pour rétablir une vision claire."},
  {"id": "kq221", "type": "knowledge", "theme": "conducteur", "question": "Manger un repas copieux juste avant de prendre la route peut :", "options": ["Favoriser la somnolence en phase de digestion","Améliorer la vigilance","N'avoir aucun effet sur la vigilance","Réduire le temps de réaction de façon positive"], "correctIndex": 0, "explanation": "Une digestion lourde favorise la somnolence ; il est conseillé de privilégier un repas léger avant un trajet, surtout long ou de nuit."},
  {"id": "kq222", "type": "knowledge", "theme": "conducteur", "question": "Face à un fort éblouissement par les phares d'un véhicule venant en face la nuit, il faut :", "options": ["Regarder fixement les phares pour évaluer la distance","Regarder légèrement vers le bord droit de la route et ralentir si nécessaire","Fermer les yeux quelques instants","Allumer ses feux de route en représailles"], "correctIndex": 1, "explanation": "Face à l'éblouissement, il faut éviter de fixer les phares, regarder plutôt le bord droit de la chaussée comme repère, et ralentir si la visibilité devient insuffisante."},
  {"id": "kq223", "type": "knowledge", "theme": "conducteur", "question": "Prendre le volant après une nuit très courte (moins de 4 à 5 heures de sommeil) présente un risque :", "options": ["Négligeable si le trajet est court","Uniquement sur autoroute","Comparable à celui de la conduite sous l'emprise de l'alcool","Inexistant chez les conducteurs jeunes"], "correctIndex": 2, "explanation": "Un manque de sommeil important dégrade les réflexes et la vigilance de façon comparable à l'alcool, augmentant fortement le risque d'accident, y compris sur de courts trajets."},
  {"id": "kq224", "type": "knowledge", "theme": "route", "question": "Un panneau carré à fond bleu représentant une flèche blanche indique :", "options": ["Une interdiction de tourner","Un sens interdit","Une simple indication d'itinéraire touristique","Une direction obligatoire à suivre"], "correctIndex": 3, "explanation": "Un panneau rond (et non carré) à fond bleu avec une flèche blanche impose une direction obligatoire ; les panneaux carrés/rectangulaires bleus servent eux à l'indication (parking, direction non obligatoire)."},
  {"id": "kq225", "type": "knowledge", "theme": "route", "question": "Le panneau triangulaire représentant une chaussée qui se rétrécit annonce :", "options": ["Un rétrécissement de la chaussée, nécessitant prudence","Une fin d'agglomération","Une piste cyclable","Un péage"], "correctIndex": 0, "explanation": "Ce panneau de danger prévient d'un rétrécissement prochain de la chaussée, invitant à ralentir et à anticiper un éventuel resserrement du trafic."},
  {"id": "kq226", "type": "knowledge", "theme": "route", "question": "Un panneau rectangulaire blanc marqué « FIN » suivi d'un pictogramme indique :", "options": ["Le début d'une nouvelle réglementation","La fin d'une prescription (limitation de vitesse, interdiction...) annoncée précédemment","Une interdiction absolue de circuler","Il ne signifie rien de particulier"], "correctIndex": 1, "explanation": "Un panneau de fin de prescription signale que la règle précédemment imposée (vitesse limitée, interdiction de dépasser...) cesse de s'appliquer à partir de cet endroit."},
  {"id": "kq227", "type": "knowledge", "theme": "route", "question": "Le panneau d'agglomération (nom de ville sur fond blanc, lettres noires) marque notamment :", "options": ["Une zone sans aucune limitation de vitesse","Un péage obligatoire","Le début de la limitation à 50 km/h par défaut","La fin de toute réglementation locale"], "correctIndex": 2, "explanation": "Le panneau d'entrée d'agglomération fixe le début de la zone où la vitesse est limitée à 50 km/h par défaut, sauf signalisation contraire à l'intérieur de cette zone."},
  {"id": "kq228", "type": "knowledge", "theme": "route", "question": "Le même panneau, barré d'un trait oblique rouge, marque :", "options": ["Le début de l'agglomération","Un danger particulier","Un sens interdit","La sortie de l'agglomération et la fin de la limitation à 50 km/h par défaut"], "correctIndex": 3, "explanation": "Le panneau de nom de ville barré signale la sortie de l'agglomération : la limitation par défaut à 50 km/h cesse, sauf autre signalisation."},
  {"id": "kq229", "type": "knowledge", "theme": "route", "question": "Une ligne blanche en damier peinte au sol avant un carrefour annonce généralement :", "options": ["Un passage piéton surélevé ou un ralentisseur","Une priorité absolue","Un carrefour giratoire","Une aire de covoiturage"], "correctIndex": 0, "explanation": "Ce marquage en damier signale souvent un dispositif ralentisseur (dos d'âne, plateau surélevé) invitant à réduire sensiblement sa vitesse."},
  {"id": "kq230", "type": "knowledge", "theme": "route", "question": "Un panneau représentant un « cédez le passage » associé à un panonceau « à 150 m » annonce :", "options": ["Que la priorité est immédiate","Que le cédez le passage se trouve à 150 mètres plus loin","Une distance jusqu'à la prochaine ville","Une zone de stationnement à 150 mètres"], "correctIndex": 1, "explanation": "Le panonceau de distance annonce à l'avance un panneau de prescription (ici cédez le passage), permettant au conducteur d'anticiper la situation."},
  {"id": "kq231", "type": "knowledge", "theme": "route", "question": "Les panneaux de type « danger » sont le plus souvent implantés :", "options": ["Juste à l'endroit du danger, sans anticipation","Uniquement après le danger","Avant le danger, pour laisser le temps d'anticiper (environ 150 m hors agglomération)","De façon aléatoire, sans règle de distance"], "correctIndex": 2, "explanation": "Les panneaux de danger sont implantés en amont du danger, généralement à environ 150 mètres hors agglomération, pour laisser au conducteur le temps d'adapter sa conduite."},
  {"id": "kq232", "type": "knowledge", "theme": "route", "question": "Sur autoroute, les panneaux de signalisation directionnelle pour les zones industrielles ou d'activités sont généralement de couleur :", "options": ["Bleue","Jaune","Verte","Marron"], "correctIndex": 3, "explanation": "Les panneaux de couleur marron signalent généralement des lieux touristiques ou culturels ; pour les zones d'activités, le vert ou le bleu selon le type de route est utilisé, tandis que le marron reste réservé au patrimoine et tourisme."},
  {"id": "kq233", "type": "knowledge", "theme": "route", "question": "Une ligne continue de couleur jaune peinte au bord de la chaussée signifie généralement :", "options": ["Une interdiction de stationner ou de s'arrêter à cet endroit","Une autorisation de stationner sans limite","Une voie réservée aux vélos","Une limite de vitesse spécifique"], "correctIndex": 0, "explanation": "Un marquage jaune continu au bord de la chaussée (souvent sur trottoir ou bordure) indique une interdiction de stationner, parfois même de s'arrêter selon le marquage."},
  {"id": "kq234", "type": "knowledge", "theme": "route", "question": "Les flèches de sélection peintes au sol dans les voies d'un carrefour indiquent :", "options": ["Une simple décoration sans valeur réglementaire","La direction que chaque voie impose de suivre au carrefour suivant","Un sens interdit temporaire","Une zone de dépassement autorisé"], "correctIndex": 1, "explanation": "Ces flèches de pré-signalisation imposent, dès leur franchissement, la direction que devra suivre le véhicule circulant sur cette voie au carrefour."},
  {"id": "kq235", "type": "knowledge", "theme": "route", "question": "Un panneau représentant une silhouette de vache ou d'animal traversant annonce :", "options": ["Une ferme à proximité","Une zone de pâturage sans danger","Un risque de traversée d'animaux sur la chaussée","Un marché agricole"], "correctIndex": 2, "explanation": "Ce panneau de danger signale un risque de traversée d'animaux (domestiques ou sauvages) sur la route, invitant à ralentir et à rester attentif."},
  {"id": "kq236", "type": "knowledge", "theme": "route", "question": "Le marquage au sol en forme de « stop » peint directement sur la chaussée, en plus du panneau vertical, sert à :", "options": ["Remplacer totalement le panneau, qui devient inutile","Indiquer une zone de dépassement","N'a aucune valeur légale","Renforcer la visibilité de l'obligation d'arrêt, notamment en cas de mauvaise visibilité du panneau"], "correctIndex": 3, "explanation": "Le marquage STOP au sol complète le panneau vertical, notamment lorsque celui-ci pourrait être masqué (neige, véhicule garé) et renforce la visibilité de l'obligation d'arrêt."},
  {"id": "kq237", "type": "knowledge", "theme": "route", "question": "Une voie bus identifiée par un losange blanc peint au sol signifie que cette voie est :", "options": ["Réservée aux seuls transports en commun, taxis et parfois vélos selon la signalisation locale","Ouverte à tous les véhicules sans restriction","Réservée uniquement aux poids lourds","Une voie de dépassement classique"], "correctIndex": 0, "explanation": "Le losange blanc marque une voie réservée à certains usagers (bus, taxis, parfois covoiturage ou vélos), dont l'accès est limité aux véhicules autorisés par la signalisation locale."},
  {"id": "kq238", "type": "knowledge", "theme": "route", "question": "Le panneau représentant deux flèches, l'une noire vers le haut et l'une rouge vers le bas, sur un fond blanc annonce :", "options": ["Une route à sens unique","Une route à double sens de circulation","Une impasse","Un rond-point"], "correctIndex": 1, "explanation": "Ce panneau de danger annonce que l'on va aborder une section à double sens de circulation, après avoir potentiellement circulé sur une portion à sens unique ou séparée."},
  {"id": "kq239", "type": "knowledge", "theme": "route", "question": "Un panneau représentant un feu tricolore dans un triangle annonce :", "options": ["Une interdiction de circuler","La fin d'une zone de feux","La présence d'un feu tricolore, souvent hors agglomération où il est moins attendu","Un radar automatique"], "correctIndex": 2, "explanation": "Ce panneau de danger annonce la présence prochaine d'un feu tricolore, notamment dans des zones où ce type de signalisation est moins attendu par les usagers."},
  {"id": "kq240", "type": "knowledge", "theme": "route", "question": "Une bande blanche discontinue très rapprochée (traits courts, espaces courts) au centre de la chaussée signifie généralement :", "options": ["Un stationnement autorisé","Une piste cyclable","Rien de particulier, c'est identique à un marquage classique","Une approche d'une zone où le dépassement va devenir interdit"], "correctIndex": 3, "explanation": "Une ligne discontinue avec des traits plus rapprochés (dite de dissuasion) annonce l'approche d'une zone à visibilité réduite où le dépassement va devenir dangereux ou interdit."},
  {"id": "kq241", "type": "knowledge", "theme": "route", "question": "Le panneau représentant un « i » entouré ou encadré, sur fond bleu, indique généralement :", "options": ["Un point d'information (office de tourisme, aire de service...)","Une interdiction de circuler","Une obligation de suivre une direction","Un danger imminent"], "correctIndex": 0, "explanation": "Le pictogramme « i » signale un point d'information, souvent situé sur les aires d'autoroute ou à l'entrée de zones touristiques."},
  {"id": "kq242", "type": "knowledge", "theme": "route", "question": "Sur une route à sens unique, un panneau représentant une flèche blanche verticale sur fond bleu, placé au début de la voie, signifie :", "options": ["Double sens autorisé","Sens unique dans la direction indiquée","Voie réservée aux cyclistes uniquement","Impasse sans issue"], "correctIndex": 1, "explanation": "Ce panneau d'obligation indique un sens unique de circulation dans la direction de la flèche ; il est interdit de circuler dans le sens inverse."},
  {"id": "kq243", "type": "knowledge", "theme": "route", "question": "Un panonceau représentant une distance (par exemple « 500 m ») sous un panneau de danger signifie :", "options": ["Une distance jusqu'à la prochaine aire de repos","Une vitesse maximale autorisée","Que le danger se situe à la distance indiquée","Aucune signification particulière"], "correctIndex": 2, "explanation": "Ce panonceau précise la distance à laquelle se situe le danger annoncé par le panneau principal, permettant d'évaluer le moment où redoubler de prudence."},
  {"id": "kq244", "type": "knowledge", "theme": "route", "question": "La signalisation d'une zone de rencontre impose notamment :", "options": ["Une vitesse maximale de 50 km/h","L'interdiction totale de circulation piétonne","Aucune règle spécifique, comme une rue normale","Une vitesse maximale de 20 km/h et une priorité aux piétons"], "correctIndex": 3, "explanation": "Dans une zone de rencontre, la vitesse est limitée à 20 km/h, les piétons sont prioritaires et peuvent circuler sur toute la largeur de la voie, sauf devant les véhicules en mouvement."},
  {"id": "kq245", "type": "knowledge", "theme": "route", "question": "Une aire piétonne (zone strictement piétonne) est en principe :", "options": ["Interdite à tous les véhicules, y compris cyclistes et véhicules de livraison sauf autorisation spécifique","Ouverte librement à tous les véhicules","Réservée uniquement aux vélos","Identique à une zone 30"], "correctIndex": 0, "explanation": "Dans une aire piétonne, seuls les véhicules autorisés (livraisons à certaines heures, riverains, services) peuvent circuler, à l'allure du pas, en cédant toujours le passage aux piétons."},
  {"id": "kq246", "type": "knowledge", "theme": "route", "question": "Une voie de détresse (voie d'échappatoire pour véhicules en perte de freinage) est généralement recouverte de :", "options": ["Bitume lisse classique","Gravier ou sable pour ralentir rapidement le véhicule","Herbe non entretenue","Béton armé glissant"], "correctIndex": 1, "explanation": "Les voies de détresse en montée, remplies de gravier ou de sable, permettent de ralentir puis d'immobiliser un véhicule ayant perdu ses freins dans une longue descente."},
  {"id": "kq247", "type": "knowledge", "theme": "route", "question": "Un panneau à fond blanc bordé de rouge représentant un cycliste barré interdit :", "options": ["Uniquement le stationnement des vélos","Le dépassement des cyclistes","La circulation des cyclistes à cet endroit","Rien, ce panneau n'existe pas"], "correctIndex": 2, "explanation": "Ce panneau d'interdiction signale que la circulation des cycles est interdite sur la voie ou la portion de route concernée."},
  {"id": "kq248", "type": "knowledge", "theme": "route", "question": "Le panneau représentant un piéton dans un triangle rouge annonce :", "options": ["Une interdiction pour les piétons","Un parking réservé aux piétons","La fin d'une zone piétonne","Un passage piéton proche ou une zone fréquentée par des piétons"], "correctIndex": 3, "explanation": "Ce panneau de danger prévient de la présence probable de piétons traversant ou circulant à proximité, notamment près des écoles ou zones commerçantes."},
  {"id": "kq249", "type": "knowledge", "theme": "route", "question": "Un panneau rond à fond bleu représentant une bicyclette blanche impose :", "options": ["L'obligation pour les cyclistes d'emprunter cette piste ou bande cyclable","L'interdiction de circuler à vélo","Le stationnement réservé aux vélos uniquement","Une simple indication facultative"], "correctIndex": 0, "explanation": "Ce panneau d'obligation impose aux cyclistes d'utiliser la piste ou bande cyclable signalée, plutôt que la chaussée principale, lorsque cet aménagement existe."},
  {"id": "kq250", "type": "knowledge", "theme": "route", "question": "Le panneau représentant un panneau STOP miniature dans un panonceau rectangulaire sous un panneau principal signifie :", "options": ["Qu'il faut s'arrêter à hauteur de ce panonceau uniquement","Que la circulation venant en face doit céder le passage ou s'arrêter selon les indications complètes","Une simple décoration","Un panneau obsolète sans valeur"], "correctIndex": 1, "explanation": "Ce type de panonceau précise les conditions de priorité, en indiquant par exemple que le trafic venant en sens inverse doit céder le passage ou marquer un arrêt selon la configuration du carrefour."},
  {"id": "kq251", "type": "knowledge", "theme": "route", "question": "Une route classée « route à grande circulation » se distingue notamment par :", "options": ["L'absence totale de signalisation","L'interdiction de tout dépassement","Une réglementation renforcée sur les accès et une priorité affirmée aux intersections avec les voies secondaires","Une limitation systématique à 50 km/h"], "correctIndex": 2, "explanation": "Une route à grande circulation bénéficie d'une réglementation particulière, avec souvent une priorité maintenue aux intersections avec les voies secondaires, afin de préserver la fluidité du trafic important qu'elle supporte."},
  {"id": "kq252", "type": "knowledge", "theme": "route", "question": "Le marquage au sol représentant un « T » renversé blanc à l'entrée d'une voie signifie généralement :", "options": ["Voie sans issue","Stationnement autorisé","Limitation de vitesse à 30 km/h","Cédez le passage"], "correctIndex": 3, "explanation": "Ce triangle peint au sol, pointe orientée vers le conducteur, reproduit au sol la même obligation que le panneau vertical cédez-le-passage."},
  {"id": "kq253", "type": "knowledge", "theme": "route", "question": "Un panneau représentant un radar photographique stylisé annonce :", "options": ["Un contrôle de vitesse fixe ou une zone de contrôle radar","Un poste de péage","Une caméra de surveillance touristique","Une simple zone de repos"], "correctIndex": 0, "explanation": "Ce panneau prévient les usagers de la présence d'un dispositif de contrôle de vitesse (radar fixe ou zone contrôlée), afin d'inciter au respect des limitations."},
  {"id": "kq254", "type": "knowledge", "theme": "usagers", "question": "Un piéton qui souhaite traverser en dehors d'un passage protégé, à plus de 50 mètres d'un passage piéton :", "options": ["A toujours la priorité, comme sur un passage piéton","Doit s'assurer qu'il peut traverser sans danger et n'est pas prioritaire sur les véhicules","N'a pas le droit de traverser à cet endroit","Peut traverser uniquement accompagné d'un adulte"], "correctIndex": 1, "explanation": "Hors passage protégé, un piéton n'est pas prioritaire : il doit s'assurer que la traversée est possible sans danger, même si les conducteurs doivent rester attentifs à sa présence."},
  {"id": "kq255", "type": "knowledge", "theme": "usagers", "question": "Un enfant qui joue à proximité de la chaussée, même sans intention apparente de traverser, doit inciter le conducteur à :", "options": ["Ne rien changer à sa conduite","Klaxonner pour l'écarter","Ralentir et rester très vigilant, le comportement d'un enfant étant imprévisible","Accélérer pour s'éloigner rapidement"], "correctIndex": 2, "explanation": "Le comportement des enfants est imprévisible : la prudence impose de ralentir et de redoubler de vigilance à leur approche, même sans signe de traversée."},
  {"id": "kq256", "type": "knowledge", "theme": "usagers", "question": "Les cyclistes peuvent circuler à deux de front sur la chaussée :", "options": ["Jamais, ils doivent toujours rouler en file indienne","Uniquement en agglomération","Uniquement sur autoroute","Oui, en se mettant en file simple dès qu'un véhicule souhaite les dépasser ou de nuit"], "correctIndex": 3, "explanation": "Les cyclistes peuvent circuler à deux de front, mais doivent se mettre en file simple dès qu'un véhicule veut les dépasser ou dès la tombée de la nuit, et systématiquement sur chaussée étroite ou à visibilité réduite."},
  {"id": "kq257", "type": "knowledge", "theme": "usagers", "question": "Un cycliste doit-il respecter les feux tricolores comme un automobiliste ?", "options": ["Oui, sauf autorisation spécifique signalée (panonceau cédez-le-passage cycliste)","Non, les feux ne concernent que les véhicules motorisés","Uniquement les feux rouges, pas les orange","Uniquement en agglomération"], "correctIndex": 0, "explanation": "Un cycliste est soumis aux mêmes règles de feux tricolores qu'un automobiliste, sauf dérogation signalée par un panonceau spécifique autorisant certains mouvements au rouge."},
  {"id": "kq258", "type": "knowledge", "theme": "usagers", "question": "Le port du casque à vélo est obligatoire en France pour :", "options": ["Tous les cyclistes, sans exception","Les enfants de moins de 12 ans, conducteurs ou passagers","Aucun cycliste, ce n'est qu'une recommandation générale","Uniquement en dehors des agglomérations"], "correctIndex": 1, "explanation": "En France, le port du casque à vélo est obligatoire pour les enfants de moins de 12 ans, qu'ils soient conducteurs de leur propre vélo ou transportés comme passagers ; il reste fortement recommandé pour les adultes."},
  {"id": "kq259", "type": "knowledge", "theme": "usagers", "question": "Les conducteurs de trottinettes électriques doivent avoir un âge minimum de :", "options": ["8 ans","16 ans","12 ans","Il n'existe pas d'âge minimum"], "correctIndex": 2, "explanation": "La conduite d'une trottinette électrique (EDPM) est interdite aux enfants de moins de 12 ans en France."},
  {"id": "kq260", "type": "knowledge", "theme": "usagers", "question": "Rouler à deux personnes sur une trottinette électrique conçue pour un seul utilisateur est :", "options": ["Autorisé si les deux passagers sont légers","Autorisé uniquement pour un enfant et un adulte","Autorisé sur les pistes cyclables uniquement","Interdit, ces engins n'étant homologués que pour un seul utilisateur"], "correctIndex": 3, "explanation": "Une trottinette électrique standard est homologuée pour un seul utilisateur ; transporter un passager supplémentaire est interdit et dangereux."},
  {"id": "kq261", "type": "knowledge", "theme": "usagers", "question": "La vitesse maximale autorisée pour une trottinette électrique en agglomération est généralement de :", "options": ["25 km/h","10 km/h","45 km/h","Il n'existe aucune limite"], "correctIndex": 0, "explanation": "Les engins de déplacement personnel motorisés (trottinettes électriques) sont limités à 25 km/h, la vitesse pouvant être réduite localement (zones piétonnes, certaines rues)."},
  {"id": "kq262", "type": "knowledge", "theme": "usagers", "question": "Un utilisateur de trottinette électrique doit obligatoirement, la nuit ou par visibilité insuffisante, disposer de :", "options": ["Aucun équipement particulier","Feux avant et arrière ainsi qu'un dispositif rétro-réfléchissant","Uniquement un casque","Uniquement un gilet fluorescent, sans obligation d'éclairage"], "correctIndex": 1, "explanation": "Comme un vélo, la trottinette électrique doit être équipée de feux avant et arrière ainsi que de catadioptres, obligatoires de nuit ou en cas de faible visibilité."},
  {"id": "kq263", "type": "knowledge", "theme": "usagers", "question": "Un conducteur de véhicule agricole (tracteur) circulant lentement sur une route doit :", "options": ["Être systématiquement suivi sans jamais être dépassé","Rouler au centre de la voie en permanence","Faciliter les dépassements quand la sécurité le permet, par exemple en se rabattant","Ignorer les véhicules qui le suivent"], "correctIndex": 2, "explanation": "Un conducteur de véhicule lent doit faciliter les dépassements par les véhicules plus rapides dès que les conditions de sécurité et de visibilité le permettent, par exemple en se rabattant sur le bas-côté."},
  {"id": "kq264", "type": "knowledge", "theme": "usagers", "question": "Les personnes en fauteuil roulant circulant sur la chaussée en l'absence de trottoir doivent être considérées comme :", "options": ["Des véhicules soumis au code de la route comme une voiture","Des usagers sans statut particulier","Interdites de circulation sur la chaussée","Des piétons, avec les mêmes droits de priorité"], "correctIndex": 3, "explanation": "Une personne en fauteuil roulant est considérée comme un piéton, y compris lorsqu'elle est contrainte d'emprunter la chaussée faute de trottoir accessible."},
  {"id": "kq265", "type": "knowledge", "theme": "usagers", "question": "Croiser un cycliste circulant en sens inverse sur une route étroite nécessite de :", "options": ["Ralentir et, si besoin, s'écarter pour lui laisser un espace suffisant","Le forcer à s'arrêter sur le bas-côté","Accélérer pour le croiser rapidement","L'ignorer, il doit se débrouiller seul"], "correctIndex": 0, "explanation": "Sur une route étroite, il faut ralentir et laisser un espace suffisant en croisant un cycliste, quitte à serrer légèrement à droite si la sécurité le permet."},
  {"id": "kq266", "type": "knowledge", "theme": "usagers", "question": "L'ouverture d'une portière de voiture garée doit se faire :", "options": ["Sans précaution particulière","En vérifiant qu'aucun cycliste ou véhicule n'arrive, pour éviter un accident (technique de « l'ouverture hollandaise »)","Uniquement de nuit","Uniquement par le conducteur, jamais les passagers"], "correctIndex": 1, "explanation": "Avant d'ouvrir une portière, il faut vérifier la circulation, notamment celle des cyclistes qui longent le trottoir : ouvrir sans regarder est une cause fréquente d'accidents avec les deux-roues."},
  {"id": "kq267", "type": "knowledge", "theme": "usagers", "question": "Les conducteurs de quads homologués pour la route doivent :", "options": ["N'avoir aucun permis particulier","Avoir uniquement 14 ans révolus, sans autre condition","Être titulaires d'un permis adapté à la catégorie du quad (AM, A1, B selon les cas)","Être exemptés du port du casque"], "correctIndex": 2, "explanation": "Selon leur puissance et leur catégorie, les quads homologués route nécessitent un permis adapté (AM, A1 ou B), le port du casque étant obligatoire pour les quads non carrossés."},
  {"id": "kq268", "type": "knowledge", "theme": "usagers", "question": "Un autobus scolaire à l'arrêt, feux spéciaux clignotants allumés, impose aux véhicules qui le croisent ou le suivent de :", "options": ["Continuer normalement sans changement","Klaxonner pour signaler leur présence","Doubler rapidement avant que les enfants ne descendent","Ralentir fortement et redoubler de prudence, des enfants pouvant traverser"], "correctIndex": 3, "explanation": "Face à un car scolaire arrêté avec ses feux spéciaux clignotants, il faut impérativement ralentir, car des enfants peuvent traverser la route de façon imprévisible à proximité."},
  {"id": "kq269", "type": "knowledge", "theme": "usagers", "question": "Les conducteurs de véhicules de transport public de personnes (bus, cars) bénéficient de facilités de circulation, notamment :", "options": ["De voies réservées et de priorités pour quitter certains arrêts en agglomération","D'aucune facilité particulière","D'une exemption totale du code de la route","D'une vitesse illimitée en agglomération"], "correctIndex": 0, "explanation": "Les bus et cars bénéficient souvent de voies réservées et d'une priorité pour quitter leur arrêt en agglomération, afin de fluidifier les transports en commun."},
  {"id": "kq270", "type": "knowledge", "theme": "usagers", "question": "Face à un attelage de chevaux ou un cavalier sur la route, un automobiliste doit :", "options": ["Klaxonner pour signaler sa présence de loin","Ralentir, garder ses distances et éviter tout bruit soudain qui pourrait effrayer l'animal","Accélérer pour le dépasser au plus vite","L'ignorer, les chevaux n'étant pas des usagers de la route"], "correctIndex": 1, "explanation": "Un cheval peut être effrayé par un bruit soudain ou un dépassement trop rapide : il faut ralentir, garder ses distances et éviter klaxon ou accélération brusque."},
  {"id": "kq271", "type": "knowledge", "theme": "usagers", "question": "Les livreurs à vélo ou à trottinette doivent respecter :", "options": ["Des règles spécifiques, différentes du code de la route classique","Aucune règle, leur activité professionnelle prime","Les mêmes règles de circulation que tout cycliste ou utilisateur d'EDPM","Uniquement les règles définies par leur plateforme de livraison"], "correctIndex": 2, "explanation": "Un livreur à vélo ou à trottinette reste soumis aux mêmes règles du code de la route que tout autre usager, malgré la pression liée aux délais de livraison."},
  {"id": "kq272", "type": "knowledge", "theme": "usagers", "question": "Un motocycliste doit porter, en plus du casque, des équipements de protection :", "options": ["Aucun équipement n'est légalement obligatoire hormis le casque","Uniquement des lunettes de soleil","Un gilet fluorescent en permanence sur autoroute uniquement","Des gants homologués sont obligatoires ; d'autres équipements (blouson, pantalon renforcé, bottes) sont fortement recommandés"], "correctIndex": 3, "explanation": "Le port de gants homologués est obligatoire pour tout conducteur ou passager de deux-roues motorisé ; blouson, pantalon renforcé et bottes sont vivement recommandés sans être une obligation légale directe."},
  {"id": "kq273", "type": "knowledge", "theme": "usagers", "question": "Les deux-roues motorisés doivent-ils allumer leurs feux de croisement en permanence, même de jour ?", "options": ["Oui, l'allumage des feux de croisement est obligatoire de jour comme de nuit pour les motos et scooters","Non, jamais de jour","Uniquement sur autoroute","Uniquement lorsqu'il pleut"], "correctIndex": 0, "explanation": "Les deux-roues motorisés doivent circuler feux de croisement allumés en permanence, de jour comme de nuit, afin d'être mieux repérés par les autres usagers."},
  {"id": "kq274", "type": "knowledge", "theme": "usagers", "question": "Face à un groupe de piétons marchant sur une route sans trottoir, hors agglomération, ceux-ci doivent en principe circuler :", "options": ["Au centre de la chaussée","Sur le côté gauche de la route, en sens inverse de la circulation, sauf cas particuliers","N'importe où, sans règle précise","Uniquement sur la voie de droite dans le sens de circulation"], "correctIndex": 1, "explanation": "En l'absence de trottoir hors agglomération, les piétons doivent en principe marcher à gauche, face à la circulation venant en sens inverse, pour mieux voir les véhicules approcher."},
  {"id": "kq275", "type": "knowledge", "theme": "usagers", "question": "Un piéton portant des écouteurs et regardant son téléphone en traversant :", "options": ["N'engage jamais sa propre responsabilité","Est automatiquement prioritaire quelle que soit la situation","Se met lui-même en danger, sans pour autant dispenser le conducteur de rester prudent","N'a plus le statut de piéton protégé"], "correctIndex": 2, "explanation": "Un piéton distrait se met en danger par son propre comportement, mais cela n'enlève rien à l'obligation du conducteur de rester attentif et prudent envers tous les usagers vulnérables."},
  {"id": "kq276", "type": "knowledge", "theme": "usagers", "question": "Les véhicules de collecte des déchets (bennes à ordures) à l'arrêt avec leurs feux spéciaux activés imposent aux véhicules qui les croisent de :", "options": ["Continuer sans changement particulier","S'arrêter complètement dans tous les cas","Klaxonner pour signaler leur passage","Ralentir et redoubler de prudence en raison des agents travaillant à proximité"], "correctIndex": 3, "explanation": "À l'approche d'un véhicule de collecte avec ses feux spéciaux, il faut ralentir et rester très prudent, des agents pouvant se trouver sur ou à proximité de la chaussée."},
  {"id": "kq277", "type": "knowledge", "theme": "usagers", "question": "Les motos et scooters peuvent-ils se garer sur les places réservées aux deux-roues situées sur les trottoirs ?", "options": ["Oui, lorsque la municipalité a spécifiquement aménagé et signalé ces emplacements","Non, jamais","Uniquement de nuit","Uniquement pour les scooters électriques"], "correctIndex": 0, "explanation": "Certaines municipalités aménagent des emplacements de stationnement pour deux-roues sur une partie du trottoir, clairement signalés : leur usage y est alors autorisé."},
  {"id": "kq278", "type": "knowledge", "theme": "usagers", "question": "Un conducteur novice titulaire du permis moto (A2) est soumis, comme pour le permis B, à :", "options": ["Aucune limitation de puissance","Une limitation de puissance du véhicule pendant une période définie","Une interdiction de circuler la nuit","Une obligation de rouler en dessous de 50 km/h"], "correctIndex": 1, "explanation": "Le permis A2 limite la puissance des motos pouvant être conduites, une étape intermédiaire avant l'accès à la catégorie A sans restriction de puissance après deux ans d'expérience minimum et une formation complémentaire."},
  {"id": "kq279", "type": "knowledge", "theme": "usagers", "question": "Un cycliste peut légalement circuler sur un trottoir :", "options": ["Toujours, sans restriction","Uniquement de nuit","Jamais, sauf s'il descend de son vélo et le pousse à la main, ou s'il est très jeune enfant en apprentissage","Uniquement s'il roule vite"], "correctIndex": 2, "explanation": "Un cycliste en selle ne doit pas circuler sur le trottoir, réservé aux piétons ; il peut seulement y marcher en tenant son vélo à la main, ou s'il s'agit d'un très jeune enfant selon les règles locales."},
  {"id": "kq280", "type": "knowledge", "theme": "usagers", "question": "Les enfants de moins de 8 ans peuvent circuler à vélo sur le trottoir :", "options": ["Jamais, quelle que soit leur allure","Sans aucune restriction","Uniquement s'ils sont accompagnés d'un adulte en voiture","À l'allure du pas, en respectant la priorité des piétons"], "correctIndex": 3, "explanation": "Les enfants de moins de 8 ans sont autorisés à circuler à vélo sur les trottoirs, mais uniquement à l'allure du pas et en cédant systématiquement le passage aux piétons."},
  {"id": "kq281", "type": "knowledge", "theme": "usagers", "question": "Un motard qui circule avec un phare avant éteint ou défectueux de jour :", "options": ["Commet une infraction, les feux de croisement étant obligatoires en permanence pour les deux-roues motorisés","Ne commet aucune infraction, l'éclairage n'étant utile que de nuit","Peut être verbalisé uniquement de nuit","N'a une obligation qu'en agglomération"], "correctIndex": 0, "explanation": "L'allumage des feux de croisement est obligatoire pour tout deux-roues motorisé de jour comme de nuit : rouler feux éteints de jour constitue une infraction."},
  {"id": "kq282", "type": "knowledge", "theme": "usagers", "question": "Face à une personne aveugle ou malvoyante accompagnée d'un chien-guide, un conducteur doit :", "options": ["Klaxonner pour signaler son approche","Lui céder systématiquement le passage, ce piéton étant considéré comme prioritaire","L'ignorer comme tout piéton hors passage protégé","Accélérer pour ne pas la faire attendre"], "correctIndex": 1, "explanation": "Une personne non-voyante ou malvoyante, avec ou sans chien-guide et munie d'une canne blanche, bénéficie d'une priorité de passage systématique reconnue par le code de la route."},
  {"id": "kq283", "type": "knowledge", "theme": "usagers", "question": "Les véhicules de transport de fonds ou véhicules blindés bénéficient-ils d'une priorité particulière sur la route ?", "options": ["Oui, comme les véhicules de secours (pompiers, SAMU, police)","Oui, mais uniquement en agglomération","Non, ils sont soumis aux règles normales de circulation comme tout véhicule","Non, sauf en cas d'attaque en cours"], "correctIndex": 2, "explanation": "Contrairement aux véhicules de secours ou d'intervention, les véhicules de transport de fonds n'ont aucune priorité particulière et doivent respecter les règles de circulation comme tout autre véhicule."},
  {"id": "kq284", "type": "knowledge", "theme": "usagers", "question": "Les nouveaux engins de déplacement personnel motorisés (gyroroues, hoverboards, monoroues) sont soumis :", "options": ["À aucune réglementation, ce sont de simples jouets","Uniquement à une réglementation locale facultative","À une interdiction totale de circuler sur la voie publique","Aux mêmes règles générales que les trottinettes électriques (circulation, âge minimum, équipements)"], "correctIndex": 3, "explanation": "Les engins de déplacement personnel motorisés (EDPM), qu'il s'agisse de trottinettes, gyroroues ou hoverboards, sont soumis à une réglementation commune : interdiction de circuler sur le trottoir sauf autorisation, âge minimum, équipements de sécurité."},
  {"id": "kq285", "type": "knowledge", "theme": "reglementation", "question": "Le nombre de points retirés pour une infraction dépend :", "options": ["De la gravité de l'infraction, allant généralement de 1 à 6 points","Toujours du même barème, quelle que soit l'infraction","Uniquement de la récidive","Du seul montant de l'amende"], "correctIndex": 0, "explanation": "Le retrait de points varie selon la gravité de l'infraction : de 1 point pour un petit excès de vitesse à 6 points pour les infractions les plus graves (grand excès de vitesse, alcool, stupéfiants, délit de fuite...)."},
  {"id": "kq286", "type": "knowledge", "theme": "reglementation", "question": "Une amende forfaitaire correspond en général à :", "options": ["Une sanction fixée par un juge après procès","Un montant prédéterminé, applicable sans passage devant un tribunal pour les contraventions courantes","Une sanction réservée aux seuls délits","Une simple mise en demeure sans obligation de payer"], "correctIndex": 1, "explanation": "L'amende forfaitaire est un montant fixé à l'avance pour les contraventions les plus courantes, payable directement sans comparution devant un tribunal, sauf contestation."},
  {"id": "kq287", "type": "knowledge", "theme": "reglementation", "question": "Une contravention de 5e classe (la plus grave des contraventions) peut concerner par exemple :", "options": ["Un simple oubli de vignette Crit'Air","Un léger dépassement du temps de stationnement payant","Un très grand excès de vitesse ou une récidive de certaines infractions graves","Un défaut de rétroviseur"], "correctIndex": 2, "explanation": "Les contraventions de 5e classe sanctionnent les infractions routières les plus graves parmi les contraventions, comme certains grands excès de vitesse ou récidives, avant de basculer en délit au-delà de certains seuils."},
  {"id": "kq288", "type": "knowledge", "theme": "reglementation", "question": "Une infraction qualifiée de « délit » (par opposition à une contravention) se caractérise par :", "options": ["Une gravité moindre qu'une contravention","L'absence de toute sanction pécuniaire","Le fait qu'elle ne concerne jamais la route","Une gravité supérieure, pouvant entraîner des peines de prison et un passage devant un tribunal correctionnel"], "correctIndex": 3, "explanation": "Un délit routier (conduite sans permis, grand excès de vitesse, alcoolémie délictuelle, délit de fuite...) est plus grave qu'une contravention : il peut entraîner une peine de prison et se juge devant un tribunal correctionnel."},
  {"id": "kq289", "type": "knowledge", "theme": "reglementation", "question": "Conduire alors que son permis est suspendu ou annulé expose à :", "options": ["Un délit sévèrement sanctionné (amende importante, prison possible, confiscation du véhicule)","Une simple amende légère, comme un défaut de ceinture","Aucune sanction si le trajet est très court","Une sanction uniquement civile envers les assurances"], "correctIndex": 0, "explanation": "Conduire malgré une suspension ou une annulation de permis est un délit grave, passible d'une lourde amende, d'une peine de prison et d'une possible confiscation du véhicule."},
  {"id": "kq290", "type": "knowledge", "theme": "reglementation", "question": "La carte grise (certificat d'immatriculation) doit être mise à jour notamment en cas de :", "options": ["Changement de couleur des sièges du véhicule","Changement de propriétaire du véhicule ou de domicile","Simple remplacement des pneus","Ajout d'accessoires esthétiques"], "correctIndex": 1, "explanation": "La carte grise doit être mise à jour lors d'un changement de propriétaire (vente) ou d'un changement d'adresse du titulaire, dans les délais fixés par la réglementation."},
  {"id": "kq291", "type": "knowledge", "theme": "reglementation", "question": "En cas de vente d'un véhicule d'occasion, le vendeur doit notamment remettre à l'acheteur :", "options": ["Uniquement les clés du véhicule","Aucun document, la vente peut se faire à l'oral","Le certificat de cession, la carte grise barrée et le certificat de situation administrative","Uniquement une facture manuscrite"], "correctIndex": 2, "explanation": "La vente d'un véhicule d'occasion nécessite un certificat de cession, la carte grise barrée et datée, ainsi qu'un certificat de situation administrative attestant l'absence de gage ou d'opposition."},
  {"id": "kq292", "type": "knowledge", "theme": "reglementation", "question": "Une attestation d'assurance (vignette verte) doit être :", "options": ["Affichée obligatoirement sur le pare-brise du véhicule","Toujours affichée à l'arrière du véhicule","Remplacée par la carte grise","N'a plus besoin d'être affichée depuis la suppression de cette obligation, mais l'assurance elle-même reste obligatoire"], "correctIndex": 3, "explanation": "L'obligation d'apposer la vignette verte d'assurance sur le pare-brise a été supprimée, mais l'obligation d'être assuré demeure totale et vérifiable via le fichier des véhicules assurés."},
  {"id": "kq293", "type": "knowledge", "theme": "reglementation", "question": "Un véhicule impliqué dans un accident matériel entre deux conducteurs doit donner lieu, si possible, à :", "options": ["Un constat amiable rempli et signé par les deux parties","Aucun document, un simple accord verbal suffit","Une plainte systématique auprès de la police","Un appel obligatoire au 112, même sans blessé"], "correctIndex": 0, "explanation": "En cas d'accident matériel, il est recommandé de remplir un constat amiable avec l'autre conducteur, document essentiel pour la déclaration à l'assurance."},
  {"id": "kq294", "type": "knowledge", "theme": "reglementation", "question": "Le défaut de contrôle technique, lorsqu'il est constaté lors d'un contrôle routier, expose notamment à :", "options": ["Aucune sanction, il s'agit d'une simple recommandation","Une amende et une immobilisation possible du véhicule jusqu'à régularisation","Une suspension de permis systématique","Uniquement une mise en demeure sans amende"], "correctIndex": 1, "explanation": "Rouler sans contrôle technique valide expose à une amende et le véhicule peut être immobilisé jusqu'à ce que la situation soit régularisée."},
  {"id": "kq295", "type": "knowledge", "theme": "reglementation", "question": "Un jeune conducteur ayant obtenu son permis peut-il conduire seul immédiatement après l'examen pratique ?", "options": ["Non, il doit attendre une confirmation postale plusieurs semaines avant de pouvoir conduire","Non, il doit d'abord effectuer un stage obligatoire","Oui, dès la communication du résultat favorable, il peut conduire en période probatoire, muni d'une attestation provisoire si besoin","Oui, mais uniquement accompagné pendant un mois supplémentaire"], "correctIndex": 2, "explanation": "Dès l'annonce du résultat favorable à l'examen, le candidat peut conduire seul en période probatoire, le permis définitif ou une attestation provisoire lui permettant de circuler en attendant le titre définitif."},
  {"id": "kq296", "type": "knowledge", "theme": "reglementation", "question": "Un excès de vitesse constaté entre 20 et 30 km/h au-dessus de la limite autorisée entraîne généralement :", "options": ["Un retrait de 1 point uniquement","Un retrait de 6 points systématique","Aucun retrait de points, seulement une amende","Un retrait de 2 points et une amende plus élevée qu'un petit excès"], "correctIndex": 3, "explanation": "Un excès de vitesse de 20 à 30 km/h au-dessus de la limite entraîne un retrait de 2 points, avec une amende plus élevée que pour un excès inférieur à 20 km/h."},
  {"id": "kq297", "type": "knowledge", "theme": "reglementation", "question": "Le fait de rouler sans permis (jamais obtenu) constitue :", "options": ["Un délit sévèrement sanctionné, notamment par une amende élevée et une possible peine de prison","Une simple contravention sans gravité","Une infraction tolérée pour les trajets courts","Une infraction concernant uniquement les mineurs"], "correctIndex": 0, "explanation": "Conduire un véhicule sans jamais avoir obtenu le permis correspondant est un délit, passible d'une amende pouvant atteindre 15 000€ et d'un an de prison."},
  {"id": "kq298", "type": "knowledge", "theme": "reglementation", "question": "L'usage d'un avertisseur de radars (détecteur signalant la présence exacte d'un radar) est en France :", "options": ["Totalement autorisé et vendu librement à cet effet","Interdit ; seuls les avertisseurs de zones de danger, sans localisation précise de radar, sont tolérés","Autorisé uniquement pour les professionnels de la route","Autorisé uniquement sur autoroute"], "correctIndex": 1, "explanation": "La détection précise de radars est interdite en France ; seule une signalisation de zones de danger plus large (sans localisation exacte de l'appareil) est tolérée, sous conditions."},
  {"id": "kq299", "type": "knowledge", "theme": "reglementation", "question": "En cas de contrôle, présenter un permis de conduire falsifié ou appartenant à une autre personne constitue :", "options": ["Une simple erreur administrative sans conséquence","Une contravention mineure","Un délit grave, sanctionné pénalement","Une infraction tolérée en l'absence d'accident"], "correctIndex": 2, "explanation": "L'usage d'un faux document ou du permis d'autrui constitue un délit grave (usage de faux, notamment), sévèrement sanctionné par la loi pénale."},
  {"id": "kq300", "type": "knowledge", "theme": "reglementation", "question": "La responsabilité civile d'un conducteur couvre principalement :", "options": ["Les dommages qu'il cause à son propre véhicule uniquement","Uniquement les dommages corporels du conducteur lui-même","Aucun dommage, c'est purement symbolique","Les dommages matériels et corporels causés à des tiers (autres personnes, véhicules, biens)"], "correctIndex": 3, "explanation": "L'assurance responsabilité civile obligatoire couvre les dommages, matériels et corporels, que le conducteur peut causer à autrui en cas d'accident dont il est responsable."},
  {"id": "kq301", "type": "knowledge", "theme": "reglementation", "question": "Un conducteur qui subit un vol de son véhicule doit notamment :", "options": ["Déposer plainte rapidement et informer son assureur dans les délais prévus par le contrat","Attendre plusieurs jours avant toute démarche","N'a aucune démarche particulière à effectuer","Doit uniquement prévenir la préfecture"], "correctIndex": 0, "explanation": "En cas de vol, il faut déposer plainte rapidement auprès des forces de l'ordre et déclarer le sinistre à son assureur dans le délai contractuel prévu (généralement 2 jours ouvrés)."},
  {"id": "kq302", "type": "knowledge", "theme": "reglementation", "question": "Le malus applicable après un accident responsable a pour effet :", "options": ["De réduire la prime d'assurance","D'augmenter la prime d'assurance du conducteur responsable","De supprimer l'obligation d'assurance pendant un an","De retirer automatiquement des points du permis"], "correctIndex": 1, "explanation": "Le système bonus-malus augmente la prime d'assurance après un accident responsable, indépendamment d'un éventuel retrait de points qui relève, lui, de l'infraction commise."},
  {"id": "kq303", "type": "knowledge", "theme": "reglementation", "question": "Un conducteur peut-il être verbalisé pour excès de vitesse par un radar automatique sans interception par les forces de l'ordre ?", "options": ["Non, un policier doit toujours intercepter le véhicule","Non, seuls les radars mobiles tenus par un agent sont valables","Oui, l'avis de contravention est envoyé directement au domicile du titulaire de la carte grise","Oui, mais uniquement pour les excès de plus de 50 km/h"], "correctIndex": 2, "explanation": "Les radars automatiques (fixes, mobiles, embarqués) photographient l'infraction et l'avis de contravention est envoyé par courrier directement au titulaire du certificat d'immatriculation."},
  {"id": "kq304", "type": "knowledge", "theme": "reglementation", "question": "Le titulaire d'une carte grise qui n'était pas le conducteur au moment de l'infraction constatée par radar automatique doit, pour éviter un retrait de points :", "options": ["Ne rien faire, la loi ne prévoit pas cette situation","Payer une amende double sans autre formalité","Contester systématiquement devant un tribunal","Désigner le véritable conducteur dans le délai imparti sur l'avis de contravention"], "correctIndex": 3, "explanation": "Le titulaire de la carte grise doit désigner le conducteur réel dans le délai indiqué, sous peine de devoir payer l'amende sans transfert du retrait de points, ou de s'exposer à une amende pour non-désignation."},
  {"id": "kq305", "type": "knowledge", "theme": "reglementation", "question": "Une contravention pour stationnement gênant (hors zones très gênantes) est en général classée en :", "options": ["2e ou 3e classe selon la situation","1re classe","5e classe","Ce n'est pas une contravention mais un délit"], "correctIndex": 0, "explanation": "Le stationnement gênant relève généralement d'une contravention de 2e ou 3e classe selon la situation, moins sévère que le stationnement dit très gênant."},
  {"id": "kq306", "type": "knowledge", "theme": "reglementation", "question": "Un véhicule circulant avec des plaques d'immatriculation illisibles ou non conformes s'expose à :", "options": ["Aucune sanction, tant que le numéro reste identifiable","Une amende, le véhicule pouvant également être immobilisé","Une sanction uniquement lors du contrôle technique","Un simple avertissement oral"], "correctIndex": 1, "explanation": "Des plaques illisibles, mal fixées ou non conformes constituent une infraction sanctionnée par une amende, avec un risque d'immobilisation du véhicule jusqu'à mise en conformité."},
  {"id": "kq307", "type": "knowledge", "theme": "reglementation", "question": "Le fait de ne pas s'arrêter à la demande des forces de l'ordre (refus d'obtempérer) constitue :", "options": ["Une simple contravention sans gravité","Une infraction sans lien avec la sécurité routière","Un délit, avec des sanctions aggravées si mise en danger d'autrui","Une infraction uniquement civile"], "correctIndex": 2, "explanation": "Le refus d'obtempérer est un délit sévèrement sanctionné, les peines étant aggravées lorsque ce refus met en danger la vie d'autrui, notamment des forces de l'ordre."},
  {"id": "kq308", "type": "knowledge", "theme": "reglementation", "question": "L'obligation d'installer un dispositif d'antidémarrage par éthylotest électronique (EAD) peut être imposée :", "options": ["Systématiquement à tous les nouveaux conducteurs","Uniquement aux conducteurs professionnels","Jamais en droit français","Comme alternative ou complément à une suspension de permis dans certains cas d'infraction liée à l'alcool"], "correctIndex": 3, "explanation": "Dans certains cas d'infraction liée à l'alcool, un juge ou le préfet peut imposer l'installation d'un éthylotest anti-démarrage (EAD), permettant de continuer à conduire sous conditions strictes."},
  {"id": "kq309", "type": "knowledge", "theme": "reglementation", "question": "Un conducteur peut consulter le solde de points de son permis de conduire :", "options": ["Via le site officiel de l'administration (télépoints) ou en préfecture","Nulle part, cette information reste confidentielle même pour l'intéressé","Uniquement lors d'un contrôle routier","Une seule fois dans sa vie"], "correctIndex": 0, "explanation": "Chaque conducteur peut consulter son solde de points via le service officiel en ligne dédié ou en se rendant en préfecture, afin de suivre l'évolution de son capital de points."},
  {"id": "kq310", "type": "knowledge", "theme": "reglementation", "question": "Le délai pour contester une amende forfaitaire est généralement de :", "options": ["Illimité, une contestation reste possible à tout moment","45 jours à compter de l'avis de contravention","24 heures seulement","10 ans"], "correctIndex": 1, "explanation": "Le délai légal pour contester une amende forfaitaire est en général de 45 jours à compter de la date de l'avis de contravention, faute de quoi elle devient définitive et majorée."},
  {"id": "kq311", "type": "knowledge", "theme": "reglementation", "question": "Circuler avec un véhicule dont le poids ou les dimensions dépassent la réglementation sans autorisation spéciale (convoi exceptionnel) est :", "options": ["Autorisé si le trajet est court","Autorisé pour tous les professionnels sans démarche","Interdit, sauf obtention préalable d'une autorisation de transport exceptionnel","Sans conséquence tant qu'aucun accident n'a lieu"], "correctIndex": 2, "explanation": "Le transport de charges ou de véhicules hors gabarit ou hors poids réglementaire nécessite une autorisation préalable de transport exceptionnel, avec des conditions de circulation encadrées."},
  {"id": "kq312", "type": "knowledge", "theme": "reglementation", "question": "L'obligation d'équiper son véhicule de pneus hiver ou de disposer de chaînes/chaussettes neige, dans les zones montagneuses concernées, s'applique :", "options": ["Toute l'année, sans distinction","Uniquement aux poids lourds","Nulle part en France, ce n'est jamais obligatoire","Durant une période hivernale définie (généralement de novembre à mars) dans les massifs concernés par la loi Montagne"], "correctIndex": 3, "explanation": "La loi Montagne impose, dans les zones concernées et pendant une période hivernale définie (souvent du 1er novembre au 31 mars), l'équipement en pneus hiver ou la présence de dispositifs antidérapants (chaînes, chaussettes)."},
  {"id": "kq313", "type": "knowledge", "theme": "reglementation", "question": "Un conducteur étranger résidant en France depuis plus d'un an doit en principe :", "options": ["Échanger son permis étranger contre un permis français dans les délais prévus, selon les accords en vigueur avec son pays","Continuer à conduire indéfiniment avec son permis étranger sans aucune démarche","Repasser systématiquement l'examen du code, quel que soit son pays d'origine","N'a aucune obligation, le permis international suffit indéfiniment"], "correctIndex": 0, "explanation": "Selon les accords bilatéraux ou le pays d'origine, un résident étranger doit généralement faire échanger son permis contre un titre français dans un délai déterminé après l'installation en France."},
  {"id": "kq314", "type": "knowledge", "theme": "environnement", "question": "La vignette Crit'Air numéro 0 (véhicule 100% électrique ou hydrogène) permet :", "options": ["De ne jamais pouvoir circuler en ville","De circuler sans restriction dans les zones à faibles émissions, y compris en cas de pic de pollution","De payer un péage réduit uniquement","N'a aucun avantage particulier"], "correctIndex": 1, "explanation": "Les véhicules classés Crit'Air 0 (électriques, hydrogène) bénéficient d'un accès privilégié aux zones à faibles émissions, y compris lors des restrictions de circulation liées aux pics de pollution."},
  {"id": "kq315", "type": "knowledge", "theme": "environnement", "question": "En cas de pic de pollution avec circulation différenciée, les véhicules les plus anciens ou les plus polluants (Crit'Air 4, 5 ou non classés) :", "options": ["Peuvent continuer à circuler normalement","Sont interdits de façon permanente sur tout le territoire","Peuvent voir leur circulation restreinte ou interdite temporairement dans les zones concernées","Bénéficient d'une priorité de circulation"], "correctIndex": 2, "explanation": "Lors d'un pic de pollution, les autorités peuvent mettre en place une circulation différenciée restreignant ou interdisant temporairement les véhicules les plus polluants dans les zones concernées."},
  {"id": "kq316", "type": "knowledge", "theme": "environnement", "question": "L'écoconduite recommande de changer de vitesse (boîte manuelle) :", "options": ["Le plus tard possible, à haut régime moteur","Uniquement en dessous de 1000 tr/min","Peu importe, cela n'a aucune influence","À un régime moteur modéré, sans faire hurler le moteur"], "correctIndex": 3, "explanation": "Passer les vitesses à un régime moteur modéré, sans le faire monter inutilement haut, permet de réduire la consommation de carburant et l'usure du moteur."},
  {"id": "kq317", "type": "knowledge", "theme": "environnement", "question": "L'utilisation du frein moteur en descente, en anticipant le relâchement de l'accélérateur, permet notamment de :", "options": ["Économiser du carburant et ménager les freins classiques","Consommer plus de carburant qu'en freinant classiquement","N'a aucun intérêt en termes de sécurité ou de consommation","Est interdite par le code de la route"], "correctIndex": 0, "explanation": "Utiliser le frein moteur en descente, en anticipant, permet d'économiser du carburant (l'injection est souvent coupée) et de préserver les freins classiques d'une surchauffe."},
  {"id": "kq318", "type": "knowledge", "theme": "environnement", "question": "Un véhicule hybride combine généralement :", "options": ["Deux moteurs thermiques différents","Un moteur thermique et un ou plusieurs moteurs électriques","Uniquement des moteurs électriques de puissances différentes","Un moteur électrique et une pile à combustible uniquement"], "correctIndex": 1, "explanation": "Un véhicule hybride associe un moteur thermique classique à un ou plusieurs moteurs électriques, permettant de réduire la consommation de carburant et les émissions selon le mode de conduite."},
  {"id": "kq319", "type": "knowledge", "theme": "environnement", "question": "La recharge d'un véhicule électrique sur une borne publique nécessite généralement :", "options": ["Un simple branchement sans aucune identification","Une autorisation préfectorale à chaque recharge","Une carte ou une application dédiée selon l'opérateur de la borne","Un abonnement obligatoire national unique valable partout"], "correctIndex": 2, "explanation": "Selon l'opérateur de la borne, la recharge nécessite généralement une carte RFID, une application mobile ou un badge dédié pour identifier l'utilisateur et facturer la recharge."},
  {"id": "kq320", "type": "knowledge", "theme": "environnement", "question": "L'autonomie d'un véhicule électrique peut être réduite significativement par :", "options": ["Une conduite douce et anticipée","Une charge de la batterie à domicile","L'entretien régulier du véhicule","Le froid, l'usage intensif du chauffage/climatisation et une conduite à vitesse élevée"], "correctIndex": 3, "explanation": "Le froid, l'usage important du chauffage ou de la climatisation, ainsi qu'une conduite rapide et peu anticipée, réduisent notablement l'autonomie réelle d'un véhicule électrique."},
  {"id": "kq321", "type": "knowledge", "theme": "environnement", "question": "Le bruit excessif d'un véhicule (pot d'échappement modifié, klaxon abusif) constitue :", "options": ["Une infraction, pouvant être sanctionnée par une amende","Un simple désagrément sans conséquence légale","Une pratique encouragée pour la sécurité","Une infraction uniquement la nuit"], "correctIndex": 0, "explanation": "Un véhicule dont le bruit dépasse les normes réglementaires (échappement modifié notamment) constitue une infraction sanctionnable, la pollution sonore étant aussi prise en compte par la loi."},
  {"id": "kq322", "type": "knowledge", "theme": "environnement", "question": "Le rejet volontaire de déchets par la fenêtre d'un véhicule en circulation (mégot, emballage...) est :", "options": ["Toléré si la route est peu fréquentée","Une infraction sanctionnée, en plus d'être un risque d'incendie ou de pollution","Autorisé sur autoroute uniquement","Sans conséquence si le déchet est petit"], "correctIndex": 1, "explanation": "Jeter un déchet depuis un véhicule en mouvement est une infraction sanctionnée par une amende, ce geste pouvant en plus provoquer un incendie (mégot) ou polluer l'environnement."},
  {"id": "kq323", "type": "knowledge", "theme": "environnement", "question": "Le principe du « stop and start » (arrêt automatique du moteur à l'arrêt) présent sur de nombreux véhicules récents vise à :", "options": ["Augmenter la consommation en ville","N'a aucun effet sur la pollution","Réduire la consommation et les émissions lors des arrêts fréquents (feux, bouchons)","Endommager systématiquement la batterie"], "correctIndex": 2, "explanation": "Le système stop and start coupe automatiquement le moteur lors des arrêts brefs (feu rouge, bouchon), réduisant la consommation de carburant et les émissions polluantes en ville."},
  {"id": "kq324", "type": "knowledge", "theme": "environnement", "question": "Anticiper les feux tricolores et ralentisseurs pour éviter les freinages puis accélérations inutiles relève :", "options": ["D'une conduite sportive sans lien avec l'écologie","D'une pratique interdite par le code de la route","D'une technique réservée aux professionnels","D'une conduite économique et écologique (écoconduite)"], "correctIndex": 3, "explanation": "Anticiper la circulation pour éviter les freinages et relances inutiles est l'un des principes fondamentaux de l'écoconduite, réduisant consommation et émissions."},
  {"id": "kq325", "type": "knowledge", "theme": "environnement", "question": "Le choix d'un itinéraire évitant les zones très embouteillées permet généralement de :", "options": ["Réduire le temps passé au ralenti et donc la consommation","Augmenter systématiquement la consommation de carburant","N'a aucun impact sur la consommation","Concerne uniquement les trajets professionnels"], "correctIndex": 0, "explanation": "Éviter les zones très embouteillées réduit le temps passé au ralenti ou à vitesse très faible, une situation où la consommation rapportée à la distance parcourue est particulièrement élevée."},
  {"id": "kq326", "type": "knowledge", "theme": "environnement", "question": "L'indice de performance environnementale d'un pneu (étiquette pneu) prend notamment en compte :", "options": ["Uniquement la couleur du pneu","La résistance au roulement, l'adhérence sur sol mouillé et le bruit extérieur","Uniquement le prix du pneu","Uniquement la marque du fabricant"], "correctIndex": 1, "explanation": "L'étiquetage européen des pneus informe sur la résistance au roulement (liée à la consommation), l'adhérence sur sol mouillé (sécurité) et le niveau de bruit extérieur émis."},
  {"id": "kq327", "type": "knowledge", "theme": "environnement", "question": "Une conduite avec un rapport de vitesse trop bas par rapport à l'allure (sur-régime) entraîne :", "options": ["Une réduction de la consommation de carburant","N'a aucun effet particulier","Une augmentation de la consommation et une usure prématurée du moteur","Une amélioration de l'accélération sans inconvénient"], "correctIndex": 2, "explanation": "Rouler en sur-régime (rapport trop bas pour la vitesse) augmente inutilement la consommation de carburant et accélère l'usure du moteur."},
  {"id": "kq328", "type": "knowledge", "theme": "environnement", "question": "L'aérodynamisme d'un véhicule influence sa consommation, notamment :", "options": ["Uniquement en ville à faible vitesse","N'a aucune influence, quelle que soit la vitesse","Uniquement pour les véhicules électriques","Surtout à vitesse élevée, comme sur autoroute"], "correctIndex": 3, "explanation": "La résistance de l'air augmente fortement avec la vitesse : l'aérodynamisme (et donc les accessoires ajoutés comme une galerie) influence surtout la consommation à haute vitesse, notamment sur autoroute."},
  {"id": "kq329", "type": "knowledge", "theme": "environnement", "question": "Le dispositif de recyclage des gaz d'échappement (EGR) sur un moteur diesel vise notamment à :", "options": ["Réduire certaines émissions polluantes (oxydes d'azote)","Augmenter la puissance du moteur sans limite","Remplacer le filtre à particules","N'a aucun rôle environnemental"], "correctIndex": 0, "explanation": "La vanne EGR recycle une partie des gaz d'échappement dans la combustion, ce qui permet de réduire la température de combustion et donc les émissions d'oxydes d'azote."},
  {"id": "kq330", "type": "knowledge", "theme": "environnement", "question": "L'utilisation du covoiturage pour les trajets domicile-travail contribue notamment à :", "options": ["Augmenter les embouteillages aux heures de pointe","Réduire la congestion routière et les émissions liées aux trajets pendulaires","N'a aucun effet mesurable sur le trafic","Concerne uniquement les longs trajets touristiques"], "correctIndex": 1, "explanation": "Le covoiturage pour les trajets domicile-travail réduit le nombre de véhicules en circulation aux heures de pointe, limitant congestion et émissions polluantes."},
  {"id": "kq331", "type": "knowledge", "theme": "environnement", "question": "Le choix d'un mode de transport alternatif (vélo, marche, transports en commun) pour les courts trajets urbains permet notamment de :", "options": ["Augmenter la pollution locale","N'a aucun avantage par rapport à la voiture","Réduire les émissions polluantes et améliorer sa propre condition physique","Concerne uniquement les trajets de loisirs"], "correctIndex": 2, "explanation": "Pour les trajets courts en ville, privilégier la marche, le vélo ou les transports en commun réduit les émissions polluantes locales tout en favorisant l'activité physique."},
  {"id": "kq332", "type": "knowledge", "theme": "environnement", "question": "Un véhicule surchargé (au-delà du poids autorisé) consomme et pollue :", "options": ["Moins qu'un véhicule à vide","Exactement autant qu'un véhicule vide","Cela dépend uniquement de la météo","Davantage, en plus de présenter des risques pour la tenue de route et le freinage"], "correctIndex": 3, "explanation": "Un véhicule surchargé consomme davantage de carburant et pollue plus, tout en présentant des risques accrus pour la tenue de route, le freinage et l'usure des pneus."},
  {"id": "kq333", "type": "knowledge", "theme": "environnement", "question": "Les zones à trafic limité (ZTL), que l'on trouve notamment dans certains centres-villes, ont pour objectif principal de :", "options": ["Réduire la circulation automobile dans les centres historiques ou sensibles","Favoriser la circulation de transit","Interdire uniquement les vélos","Faciliter le stationnement en surface"], "correctIndex": 0, "explanation": "Les zones à trafic limité restreignent l'accès des véhicules motorisés dans certains secteurs urbains, souvent historiques, afin de réduire la circulation, le bruit et la pollution."},
  {"id": "kq334", "type": "knowledge", "theme": "environnement", "question": "L'entretien régulier de la climatisation (recharge de gaz, filtres) d'un véhicule contribue à :", "options": ["Augmenter systématiquement la pollution","Limiter les fuites de gaz réfrigérant, nocif pour l'environnement, et optimiser la consommation","N'a aucun rapport avec l'environnement","Réduire uniquement le bruit du moteur"], "correctIndex": 1, "explanation": "Un entretien régulier limite les fuites de gaz réfrigérant, souvent nocif pour l'effet de serre, tout en assurant un fonctionnement optimal qui limite la surconsommation de carburant liée à la climatisation."},
  {"id": "kq335", "type": "knowledge", "theme": "environnement", "question": "Le fait de rouler avec des vitres ouvertes à vitesse élevée sur autoroute, plutôt qu'avec la climatisation, peut :", "options": ["Toujours réduire la consommation quelle que soit la vitesse","N'avoir aucun effet à haute vitesse","Augmenter la traînée aérodynamique et donc parfois la consommation à haute vitesse","Être interdit par la loi"], "correctIndex": 2, "explanation": "À haute vitesse, rouler vitres ouvertes augmente la résistance aérodynamique, ce qui peut in fine consommer davantage de carburant que d'utiliser la climatisation, contrairement à une conduite urbaine lente."},
  {"id": "kq336", "type": "knowledge", "theme": "environnement", "question": "Les biocarburants (comme l'E85 ou le B100) ont pour objectif principal de :", "options": ["Remplacer totalement et immédiatement les carburants fossiles sans transition","Augmenter systématiquement la pollution","N'ont aucun rapport avec l'environnement","Réduire une partie de la dépendance aux énergies fossiles et certaines émissions"], "correctIndex": 3, "explanation": "Les biocarburants, produits à partir de matières organiques, visent à réduire une partie de la dépendance aux énergies fossiles et peuvent diminuer certaines émissions, selon leur mode de production."},
  {"id": "kq337", "type": "knowledge", "theme": "environnement", "question": "L'écoconduite recommande, à l'approche d'un feu visiblement rouge depuis longtemps, de :", "options": ["Lever le pied et laisser le véhicule décélérer en roue libre ou en freinage moteur","Accélérer pour tenter de passer avant qu'il passe au vert","Freiner au dernier moment le plus fort possible","N'a aucune importance sur la conduite"], "correctIndex": 0, "explanation": "En anticipant un feu rouge visible de loin, il vaut mieux lever le pied tôt et laisser le véhicule décélérer naturellement, économisant du carburant plutôt que de freiner fort au dernier moment."},
  {"id": "kq338", "type": "knowledge", "theme": "environnement", "question": "Le suivi de l'indicateur de changement de vitesse (souvent présent sur le tableau de bord) sert à :", "options": ["Indiquer uniquement la vitesse maximale autorisée","Suggérer le moment optimal pour changer de rapport et limiter la consommation","Signaler une panne du moteur","N'a aucune utilité pratique"], "correctIndex": 1, "explanation": "Cet indicateur, présent sur de nombreux véhicules à boîte manuelle, suggère le moment optimal pour passer un rapport supérieur ou inférieur afin d'optimiser la consommation de carburant."},
  {"id": "kq339", "type": "knowledge", "theme": "environnement", "question": "Un véhicule mal réglé (parallélisme incorrect des roues) peut entraîner :", "options": ["Une réduction de la consommation de carburant","Aucun effet sur la consommation ni sur les pneus","Une usure irrégulière des pneus et une augmentation de la consommation","Une amélioration de la tenue de route sans inconvénient"], "correctIndex": 2, "explanation": "Un mauvais parallélisme entraîne une résistance au roulement accrue, une usure irrégulière et prématurée des pneus, ainsi qu'une surconsommation de carburant."},
  {"id": "kq340", "type": "knowledge", "theme": "environnement", "question": "Les certificats qualité de l'air (vignettes Crit'Air) sont classés de :", "options": ["1 à 10","A à F","Il n'existe qu'une seule catégorie","0 à 5"], "correctIndex": 3, "explanation": "Les vignettes Crit'Air sont classées de 0 (véhicules électriques/hydrogène) à 5 (véhicules les plus anciens et polluants), les véhicules non éligibles restant non classés."},
  {"id": "kq341", "type": "knowledge", "theme": "environnement", "question": "Ne pas obtenir ou ne pas apposer une vignette Crit'Air obligatoire dans une zone qui l'exige expose à :", "options": ["Une amende, comparable à une infraction de stationnement","Aucune sanction, c'est purement indicatif","Une suspension automatique du permis","Une confiscation systématique du véhicule"], "correctIndex": 0, "explanation": "Circuler dans une zone à faibles émissions sans la vignette Crit'Air requise, ou sans en disposer alors qu'elle est obligatoire, expose à une amende forfaitaire."},
  {"id": "kq342", "type": "knowledge", "theme": "environnement", "question": "Le bilan carbone d'un déplacement en voiture individuelle comparé au même trajet en train est généralement :", "options": ["Identique dans tous les cas","Nettement plus élevé pour la voiture individuelle sur un trajet équivalent","Toujours inférieur pour la voiture","Impossible à comparer"], "correctIndex": 1, "explanation": "Pour un trajet comparable, une voiture individuelle thermique émet en général nettement plus de CO2 par passager qu'un trajet équivalent en train, notamment sur les longues distances."},
  {"id": "kq343", "type": "knowledge", "theme": "environnement", "question": "L'usage d'une application d'aide à l'écoconduite (affichant la consommation en temps réel) permet notamment de :", "options": ["N'a aucune utilité pratique","Remplacer les obligations d'entretien du véhicule","Prendre conscience de l'impact de son style de conduite et l'adapter","Augmenter systématiquement la vitesse de conduite"], "correctIndex": 2, "explanation": "Visualiser sa consommation en temps réel aide à identifier les comportements consommateurs (accélérations brusques, sur-régime) et à ajuster sa conduite en conséquence."},
  {"id": "kq344", "type": "knowledge", "theme": "environnement", "question": "Le principal intérêt environnemental d'une conduite souple et anticipée, au-delà des économies de carburant, est de :", "options": ["Aucun autre intérêt","Augmenter la pollution sonore","N'a d'intérêt que pour le confort des passagers","Réduire l'usure des pièces mécaniques et donc les déchets liés à l'entretien"], "correctIndex": 3, "explanation": "Une conduite souple réduit aussi l'usure des freins, pneus et pièces mécaniques, ce qui limite indirectement la production de déchets liés à l'entretien et au remplacement des pièces."},
  {"id": "kq345", "type": "knowledge", "theme": "environnement", "question": "Un contrôle technique intègre notamment un volet relatif aux émissions polluantes, en vérifiant :", "options": ["Le taux d'opacité des fumées (diesel) ou d'émissions polluantes selon la motorisation","Uniquement l'état esthétique du véhicule","Uniquement le niveau sonore de l'autoradio","Rien de lié à l'environnement"], "correctIndex": 0, "explanation": "Le contrôle technique inclut une mesure des émissions polluantes du véhicule (opacité des fumées pour le diesel notamment), un dépassement des seuils pouvant entraîner une contre-visite."},
  {"id": "kq346", "type": "knowledge", "theme": "notions", "question": "Un siège auto du groupe 0+ est conçu pour :", "options": ["Les enfants de plus de 6 ans","Les nourrissons, jusqu'à environ 13 kg, installés dos à la route","Les adolescents","Tous les âges sans distinction"], "correctIndex": 1, "explanation": "Le groupe 0+ concerne les nourrissons jusqu'à environ 13 kg (ou selon la taille pour la norme i-Size), toujours installés dos à la route pour protéger leur tête et leur nuque fragiles."},
  {"id": "kq347", "type": "knowledge", "theme": "notions", "question": "Un réhausseur (groupe 2/3) sert principalement à :", "options": ["Remplacer totalement la ceinture de sécurité","Uniquement au confort, sans rôle de sécurité","Surélever l'enfant pour que la ceinture de sécurité adulte passe correctement sur son corps","Être utilisé uniquement par les adultes de petite taille"], "correctIndex": 2, "explanation": "Le réhausseur surélève l'enfant afin que la ceinture de sécurité du véhicule passe correctement sur l'épaule et le bassin, et non sur le cou ou l'abdomen, ce qui serait dangereux en cas de choc."},
  {"id": "kq348", "type": "knowledge", "theme": "notions", "question": "Le poids total roulant autorisé (PTRA) correspond au :", "options": ["Poids du véhicule seul, sans chargement","Poids maximal autorisé uniquement pour la remorque","Poids à vide indiqué sur la carte grise","Poids maximal autorisé de l'ensemble véhicule tracteur + remorque en charge"], "correctIndex": 3, "explanation": "Le PTRA indique le poids maximal autorisé pour l'ensemble formé par le véhicule tracteur et sa remorque, tous deux chargés, une donnée essentielle pour savoir ce que l'on peut légalement tracter."},
  {"id": "kq349", "type": "knowledge", "theme": "notions", "question": "Un chargement doit être arrimé de manière à :", "options": ["Ne pas se déplacer, tomber ou gêner la conduite, même en cas de freinage brusque","Pouvoir bouger légèrement sans conséquence","Être visible uniquement de nuit","N'avoir besoin d'arrimage qu'au-delà de 100 kg"], "correctIndex": 0, "explanation": "Tout chargement doit être solidement arrimé afin de ne jamais se déplacer, tomber sur la chaussée ou gêner la conduite, y compris lors d'un freinage d'urgence ou d'un virage serré."},
  {"id": "kq350", "type": "knowledge", "theme": "notions", "question": "Le permis B96 (ou la catégorie BE) permet notamment de :", "options": ["Conduire une moto de forte cylindrée","Tracter des remorques plus lourdes que la limite standard du permis B, après une formation complémentaire","Conduire un poids lourd sans autre formation","N'existe pas dans la réglementation française"], "correctIndex": 1, "explanation": "La formation B96 (ou le permis BE) permet, après une formation complémentaire, de tracter des remorques dépassant les limites de poids autorisées avec le seul permis B classique."},
  {"id": "kq351", "type": "knowledge", "theme": "notions", "question": "Le port de la ceinture de sécurité pour une femme enceinte est :", "options": ["Déconseillé, il vaut mieux ne pas l'attacher","Facultatif à partir du sixième mois de grossesse","Obligatoire, avec la sangle basse passée sous le ventre et non dessus","Interdit par la loi"], "correctIndex": 2, "explanation": "Le port de la ceinture reste obligatoire et recommandé pour les femmes enceintes, à condition de bien positionner la sangle basse sous le ventre et la sangle diagonale entre les seins, sans passer sur le ventre."},
  {"id": "kq352", "type": "knowledge", "theme": "notions", "question": "Un enfant de 4 ans pesant 17 kg doit, en principe, être installé dans :", "options": ["Un siège du groupe 0+ uniquement","Directement avec la ceinture adulte sans dispositif","Sur les genoux d'un adulte attaché","Un siège ou réhausseur adapté à son poids/sa taille, souvent un siège du groupe 1"], "correctIndex": 3, "explanation": "À cet âge et ce poids, un enfant doit encore utiliser un dispositif de retenue adapté (souvent groupe 1), la ceinture adulte seule n'étant pas sûre avant environ 135 cm."},
  {"id": "kq353", "type": "knowledge", "theme": "notions", "question": "Concernant le nombre maximal de personnes transportées dans un véhicule, il ne doit jamais dépasser :", "options": ["Le nombre de places assises indiqué sur la carte grise","Un nombre illimité tant que chacun trouve une place assise","Le double du nombre de places assises pour de courts trajets","Aucune limite n'existe légalement"], "correctIndex": 0, "explanation": "Le nombre de personnes transportées ne doit jamais excéder le nombre de places assises mentionné sur la carte grise, chaque occupant devant disposer d'une place et, si prévue, d'une ceinture."},
  {"id": "kq354", "type": "knowledge", "theme": "notions", "question": "Un vélo transporté sur un porte-vélo arrière masquant la plaque d'immatriculation impose de :", "options": ["Rien de particulier, ce n'est pas réglementé","Disposer d'une plaque et de feux additionnels reproduisant ceux du véhicule, conformes à la réglementation","Retirer systématiquement la plaque d'origine","Rouler uniquement de jour dans ce cas"], "correctIndex": 1, "explanation": "Lorsque le chargement masque la plaque ou les feux du véhicule, il faut installer une plaque et des feux additionnels conformes, afin que le véhicule reste identifiable et visible."},
  {"id": "kq355", "type": "knowledge", "theme": "notions", "question": "Le covoiturage régulier organisé via une plateforme dédiée relève :", "options": ["D'une activité de transport professionnel nécessitant une licence de taxi","D'une pratique interdite par la loi française","D'un partage de frais entre particuliers pour un trajet que le conducteur effectue de toute façon","D'un transport gratuit obligatoire pour tous les passagers"], "correctIndex": 2, "explanation": "Le covoiturage repose sur le partage des frais d'un trajet que le conducteur effectue pour son propre compte, ce qui le distingue juridiquement d'une activité de transport rémunéré comme le taxi ou le VTC."},
  {"id": "kq356", "type": "knowledge", "theme": "notions", "question": "Transporter un enfant de moins de 3 ans à l'avant du véhicule, dos à la route, avec un airbag frontal actif, est :", "options": ["Sans danger particulier","Autorisé uniquement sur autoroute","Autorisé si le trajet est très court","Extrêmement dangereux : l'airbag doit impérativement être désactivé dans ce cas"], "correctIndex": 3, "explanation": "Le déploiement d'un airbag frontal sur un siège dos à la route peut être mortel pour un nourrisson : l'airbag doit toujours être désactivé lorsqu'un tel siège est installé à l'avant."},
  {"id": "kq357", "type": "knowledge", "theme": "notions", "question": "Le PTAC (poids total autorisé en charge) d'un véhicule se trouve généralement :", "options": ["Sur la carte grise (certificat d'immatriculation), à la rubrique F2 ou F1","Sur la vignette Crit'Air","Sur le permis de conduire","Nulle part, il n'est pas indiqué"], "correctIndex": 0, "explanation": "Le PTAC est indiqué sur la carte grise du véhicule (rubrique F.2 ou F.1 selon les versions), et représente le poids maximal autorisé du véhicule chargé."},
  {"id": "kq358", "type": "knowledge", "theme": "notions", "question": "Voyager avec un chien non attaché ou libre à l'intérieur de l'habitacle est :", "options": ["Recommandé pour son confort","Risqué et potentiellement sanctionnable, l'animal pouvant gêner la conduite ou devenir un projectile en cas de choc","Sans conséquence quelle que soit sa taille","Obligatoire pour les grands chiens"], "correctIndex": 1, "explanation": "Un animal libre dans l'habitacle peut gêner la conduite et devient un projectile dangereux en cas de freinage brusque ou de choc : il doit être maintenu par un harnais, une caisse ou une grille de séparation."},
  {"id": "kq359", "type": "knowledge", "theme": "notions", "question": "La largeur maximale autorisée pour un véhicule ou un attelage circulant sans autorisation spéciale est généralement de :", "options": ["1,50 mètre","5 mètres","2,55 mètres (2,60 m pour certains véhicules frigorifiques)","Il n'existe aucune limite de largeur"], "correctIndex": 2, "explanation": "La largeur maximale autorisée pour circuler sans autorisation de transport exceptionnel est généralement de 2,55 mètres, portée à 2,60 mètres pour certains véhicules frigorifiques."},
  {"id": "kq360", "type": "knowledge", "theme": "notions", "question": "Un enfant transporté en poussette près de la chaussée doit être maintenu :", "options": ["Sans attention particulière, la poussette suffit","Toujours face à la route, jamais dos à la route","Uniquement par un adulte titulaire du permis","Avec le frein de la poussette engagé à l'arrêt, et à distance de sécurité de la circulation"], "correctIndex": 3, "explanation": "Une poussette doit toujours avoir son frein engagé à l'arrêt et être maintenue à distance de sécurité de la circulation, un enfant en poussette étant particulièrement vulnérable près de la route."},
  {"id": "kq361", "type": "knowledge", "theme": "notions", "question": "Le poids à vide d'un véhicule (indiqué sur la carte grise) correspond :", "options": ["Au poids du véhicule sans chargement ni passagers, avec les niveaux de fluides pleins","Au poids maximal autorisé en charge","Au poids du véhicule avec sa remorque","Au poids uniquement de la carrosserie"], "correctIndex": 0, "explanation": "Le poids à vide (ou poids en ordre de marche) correspond au véhicule prêt à circuler, avec ses fluides pleins, mais sans passagers ni chargement supplémentaire."},
  {"id": "kq362", "type": "knowledge", "theme": "notions", "question": "Utiliser un siège auto d'occasion nécessite de vérifier notamment :", "options": ["Uniquement son prix","Qu'il n'a jamais subi de choc important et que sa date de fabrication n'est pas trop ancienne","Uniquement sa couleur","Rien de particulier, tous les sièges se valent"], "correctIndex": 1, "explanation": "Un siège auto d'occasion doit être vérifié : absence de choc antérieur (accident), respect de la date limite d'utilisation, présence de la notice et conformité aux normes en vigueur."},
  {"id": "kq363", "type": "knowledge", "theme": "notions", "question": "Un enfant peut, à titre exceptionnel, être installé à l'avant d'un véhicule sans place arrière (utilitaire, certaines voitures deux places) :", "options": ["Jamais, quelle que soit la configuration","Uniquement s'il tient assis seul","Oui, à condition d'utiliser un dispositif de retenue adapté et de désactiver l'airbag si besoin","Uniquement s'il a plus de 5 ans"], "correctIndex": 2, "explanation": "Dans un véhicule sans place arrière, un enfant peut exceptionnellement voyager à l'avant, à condition d'utiliser un dispositif de retenue adapté à son âge et de désactiver l'airbag frontal si le siège est dos à la route."},
  {"id": "kq364", "type": "knowledge", "theme": "notions", "question": "Le fait de laisser un enfant seul dans un véhicule, même quelques minutes, notamment en cas de forte chaleur, est :", "options": ["Sans risque si les vitres sont légèrement ouvertes","Autorisé si le trajet à pied est très court","Recommandé pour habituer l'enfant à l'autonomie","Extrêmement dangereux, la température intérieure pouvant monter très rapidement"], "correctIndex": 3, "explanation": "La température à l'intérieur d'un véhicule peut monter de plusieurs dizaines de degrés en quelques minutes seulement, même par temps modéré : laisser un enfant seul dans une voiture est extrêmement dangereux, voire mortel."},
  {"id": "kq365", "type": "knowledge", "theme": "notions", "question": "Une remorque légère (moins de 750 kg de PTAC) attelée à une voiture peut en général être tractée :", "options": ["Avec un simple permis B, sans formation complémentaire obligatoire","Uniquement avec un permis remorque spécifique","Jamais avec un permis B","Uniquement de jour"], "correctIndex": 0, "explanation": "Une remorque de moins de 750 kg de PTAC peut être tractée avec un simple permis B, sans formation complémentaire, quelle que soit la masse du véhicule tracteur."},
  {"id": "kq366", "type": "knowledge", "theme": "notions", "question": "Charger une galerie de toit au-delà de la charge maximale autorisée par le constructeur peut entraîner :", "options": ["Aucun risque particulier","Une déstabilisation du véhicule, notamment dans les virages ou par vent latéral","Une amélioration de la tenue de route","Uniquement un risque esthétique"], "correctIndex": 1, "explanation": "Dépasser la charge maximale autorisée d'une galerie de toit modifie le centre de gravité du véhicule et peut le déstabiliser dangereusement, en particulier dans les virages ou par vent fort."},
  {"id": "kq367", "type": "knowledge", "theme": "notions", "question": "Le fait de transporter des animaux dans le coffre d'un break ou d'un SUV, sans grille de séparation, expose en cas de freinage brusque à :", "options": ["Aucun risque, le coffre est un espace sécurisé en soi","Un risque uniquement pour l'animal lui-même","Un risque de projection de l'animal vers l'avant, pouvant blesser les occupants","Une infraction concernant uniquement le bien-être animal"], "correctIndex": 2, "explanation": "Sans grille de séparation ni système de fixation, un animal dans le coffre peut être violemment projeté vers l'avant lors d'un freinage brusque, représentant un danger pour lui-même et pour les occupants."},
  {"id": "kq368", "type": "knowledge", "theme": "notions", "question": "Un enfant peut cesser d'utiliser un réhausseur lorsque :", "options": ["Il atteint l'âge de 6 ans, quelle que soit sa taille","Il le demande lui-même","Dès qu'il pèse plus de 15 kg","La ceinture de sécurité adulte passe correctement sur son épaule et son bassin, généralement vers 135-150 cm"], "correctIndex": 3, "explanation": "C'est la taille de l'enfant, et non son âge seul, qui détermine quand la ceinture adulte peut passer correctement sans dispositif : généralement autour de 135 à 150 cm selon la morphologie."},
  {"id": "kq369", "type": "knowledge", "theme": "notions", "question": "Le poids maximal autorisé pour une remorque tractée sans dépasser le PTAC du permis B classique (en général) est d'environ :", "options": ["Un ensemble véhicule + remorque limité à 3,5 tonnes de PTAC, sauf conditions particulières pouvant aller jusqu'à 4,25 t avec la formation B96","750 kg dans tous les cas, sans exception","Aucune limite tant que le véhicule tracteur est puissant","500 kg maximum sans aucune exception"], "correctIndex": 0, "explanation": "Avec un permis B classique, l'ensemble véhicule + remorque ne doit pas dépasser 3,5 tonnes de PTAC ; une formation complémentaire (B96) permet d'aller jusqu'à 4,25 tonnes sous certaines conditions."},
  {"id": "kq370", "type": "knowledge", "theme": "notions", "question": "Concernant les enfants en bas âge, l'installation d'un pare-soleil ou d'un rideau sur les vitres arrière :", "options": ["Est interdite dans tous les cas","Peut être utile contre l'éblouissement, sans jamais compromettre la visibilité du conducteur ni gêner la surveillance de l'enfant","Remplace l'obligation du dispositif de retenue","N'a aucune utilité"], "correctIndex": 1, "explanation": "Un pare-soleil sur les vitres arrière peut protéger l'enfant de l'éblouissement, à condition de ne jamais réduire la visibilité nécessaire du conducteur ni empêcher de surveiller l'enfant."},
  {"id": "kq371", "type": "knowledge", "theme": "notions", "question": "Le fait de transporter plus de personnes que de ceintures de sécurité disponibles est :", "options": ["Autorisé pour les trajets très courts","Autorisé uniquement pour les enfants","Interdit, chaque occupant devant disposer d'une ceinture ou d'un dispositif de retenue adapté","Sans conséquence légale"], "correctIndex": 2, "explanation": "Chaque occupant doit disposer d'une place assise avec ceinture de sécurité (ou dispositif adapté pour un enfant) ; transporter plus de personnes que de ceintures disponibles est interdit et sanctionnable."},
  {"id": "kq372", "type": "knowledge", "theme": "notions", "question": "L'installation d'un attelage de remorque sur un véhicule doit être :", "options": ["Libre, sans aucune norme technique","Interdite pour les véhicules particuliers","Réalisée uniquement par le propriétaire lui-même sans contrôle","Conforme aux normes en vigueur et compatible avec le véhicule, souvent vérifiée lors du contrôle technique"], "correctIndex": 3, "explanation": "Un attelage doit être homologué et compatible avec le véhicule, sa présence et son état étant susceptibles d'être vérifiés lors du contrôle technique."},
  {"id": "kq373", "type": "knowledge", "theme": "notions", "question": "Un chargement empilé dépassant la hauteur du véhicule doit notamment tenir compte :", "options": ["Des hauteurs limites des ponts, tunnels et autres ouvrages sur l'itinéraire emprunté","Uniquement de l'esthétique du chargement","D'aucune contrainte particulière","Uniquement de la météo"], "correctIndex": 0, "explanation": "Un chargement en hauteur impose de vérifier au préalable les hauteurs limitées signalées sur l'itinéraire (ponts, tunnels, passages sous voie), pour éviter tout accrochage dangereux."},
  {"id": "kq374", "type": "knowledge", "theme": "notions", "question": "Concernant le transport de plusieurs enfants à l'arrière d'un véhicule à trois places assises, avec seulement deux sièges auto disponibles :", "options": ["On peut installer un troisième enfant sans dispositif si la ceinture existe","Chaque enfant concerné doit disposer d'un dispositif de retenue adapté ; à défaut, il ne doit pas être transporté sans","On peut dépasser le nombre de places prévu sur la carte grise","Il suffit d'attacher deux enfants avec la même ceinture"], "correctIndex": 1, "explanation": "Chaque enfant devant utiliser un dispositif de retenue adapté doit en disposer d'un individuellement ; il n'est pas possible de le transporter en toute légalité sans ce dispositif, même si une place assise existe."},
  {"id": "kq375", "type": "knowledge", "theme": "notions", "question": "Un chien ou un animal domestique transporté doit, selon le code de la route, être installé de façon à :", "options": ["Pouvoir se déplacer librement dans tout le véhicule","Être systématiquement muselé, quelle que soit sa race","Ne pas gêner la conduite ni causer de danger aux passagers en cas de mouvement brusque","N'a aucune obligation particulière tant qu'il est calme"], "correctIndex": 2, "explanation": "Le code de la route impose que les animaux transportés ne gênent pas la conduite et ne représentent pas un danger pour les occupants en cas de freinage ou de choc, d'où l'usage de dispositifs de sécurisation adaptés."},
  {"id": "kq376", "type": "knowledge", "theme": "notions", "question": "Une remorque de camping (caravane) doit disposer, à l'arrière, d'un éclairage :", "options": ["Facultatif, la caravane étant considérée comme un simple chargement","Uniquement de nuit","Réduit à un simple triangle réfléchissant","Complet et fonctionnel (feux stop, clignotants, feux de position), identique à celui d'un véhicule"], "correctIndex": 3, "explanation": "Une caravane doit être équipée d'un système d'éclairage complet et fonctionnel à l'arrière (feux de position, stop, clignotants, plaque d'immatriculation éclairée), comme tout véhicule circulant sur la route."},
  {"id": "kq377", "type": "knowledge", "theme": "notions", "question": "Concernant l'installation d'un siège auto avec le système Isofix, ce dispositif permet notamment de :", "options": ["Fixer le siège auto de façon rigide et standardisée aux points d'ancrage du véhicule, sans utiliser la ceinture","Remplacer totalement la ceinture de sécurité du véhicule pour l'adulte","N'est compatible avec aucun véhicule récent","Uniquement utilisable pour les enfants de plus de 6 ans"], "correctIndex": 0, "explanation": "Le système Isofix permet de fixer le siège auto directement aux points d'ancrage standardisés du véhicule, offrant une installation plus rigide, stable et sécurisée qu'un maintien par la ceinture classique."},
  {"id": "kq378", "type": "knowledge", "theme": "securite_passagers", "question": "Une ceinture de sécurité mal ajustée, trop lâche, en cas de choc :", "options": ["Offre la même protection qu'une ceinture bien ajustée","Offre une protection nettement réduite, le corps pouvant être projeté avant que la ceinture ne le retienne","Est plus confortable et donc plus sûre","N'a aucune incidence sur la sécurité"], "correctIndex": 1, "explanation": "Une ceinture trop lâche laisse le corps se déplacer avant d'être retenu, ce qui réduit fortement son efficacité et peut aggraver les blessures en cas de choc."},
  {"id": "kq379", "type": "knowledge", "theme": "securite_passagers", "question": "Faire passer la sangle diagonale de la ceinture de sécurité sous le bras plutôt que sur l'épaule est :", "options": ["Plus confortable et tout aussi sûr","Recommandé pour les trajets courts","Dangereux, cela réduit fortement la protection en cas de choc et peut causer des blessures internes","Obligatoire pour les personnes de petite taille"], "correctIndex": 2, "explanation": "Passer la sangle sous le bras au lieu de sur l'épaule réduit fortement son efficacité et peut causer des blessures graves (fractures de côtes, lésions internes) en cas de choc, la ceinture ne répartissant plus correctement les forces."},
  {"id": "kq380", "type": "knowledge", "theme": "securite_passagers", "question": "Le prétensionneur de ceinture de sécurité, présent sur de nombreux véhicules récents, a pour fonction de :", "options": ["Détendre la ceinture en cas de choc","Couper l'alimentation électrique du véhicule","Gonfler la ceinture comme un airbag","Retendre instantanément la ceinture dès le début d'un choc pour plaquer l'occupant contre son siège"], "correctIndex": 3, "explanation": "Le prétensionneur retend instantanément la ceinture dès la détection d'un choc, réduisant le jeu de la sangle et plaquant l'occupant contre son siège pour limiter les déplacements dangereux."},
  {"id": "kq381", "type": "knowledge", "theme": "securite_passagers", "question": "Les airbags latéraux ont pour rôle principal de protéger :", "options": ["Le thorax et/ou la tête des occupants en cas de choc latéral","Uniquement la tête en cas de choc frontal","Les jambes en cas de choc arrière","Aucune zone précise du corps"], "correctIndex": 0, "explanation": "Les airbags latéraux (thorax, rideau) protègent principalement le buste et la tête des occupants lors d'un choc latéral, un type d'impact où la protection de la carrosserie est plus limitée."},
  {"id": "kq382", "type": "knowledge", "theme": "securite_passagers", "question": "Un siège auto orienté face à la route, avant l'âge recommandé, augmente le risque :", "options": ["N'a aucun impact sur la sécurité de l'enfant","De blessures à la tête et à la nuque en cas de choc frontal","De mal de dos uniquement","De somnolence de l'enfant"], "correctIndex": 1, "explanation": "Chez le jeune enfant dont la nuque est encore fragile, un siège orienté face à la route trop tôt augmente le risque de lésions graves de la tête et de la nuque en cas de choc frontal, d'où la recommandation de garder le dos à la route le plus longtemps possible."},
  {"id": "kq383", "type": "knowledge", "theme": "securite_passagers", "question": "Porter un casque de moto non homologué (sans marquage réglementaire) est :", "options": ["Sans conséquence tant que le casque protège visuellement la tête","Autorisé pour les trajets courts","Considéré comme une absence de casque, sanctionnée comme telle","Autorisé uniquement en agglomération"], "correctIndex": 2, "explanation": "Un casque non homologué (sans marquage ECE ou équivalent) n'offre pas les garanties de protection requises et est assimilé légalement à une absence de casque, sanctionnée de la même façon."},
  {"id": "kq384", "type": "knowledge", "theme": "securite_passagers", "question": "Le port de gants pour les deux-roues motorisés est obligatoire :", "options": ["Uniquement pour le conducteur, pas pour le passager","Uniquement en hiver","Il ne s'agit que d'une simple recommandation","Pour le conducteur et le passager, avec des gants homologués (norme CE)"], "correctIndex": 3, "explanation": "Depuis 2016, le port de gants homologués (norme CE) est obligatoire aussi bien pour le conducteur que pour tout passager d'un deux-roues motorisé."},
  {"id": "kq385", "type": "knowledge", "theme": "securite_passagers", "question": "Un enfant transporté dans une remorque à vélo (attelée à un vélo) doit notamment :", "options": ["Porter un casque adapté et être maintenu par un harnais dans la remorque","N'avoir aucun équipement particulier","Être âgé d'au moins 10 ans","Ne jamais être transporté ainsi, c'est interdit"], "correctIndex": 0, "explanation": "Un enfant transporté en remorque de vélo doit porter un casque adapté et être maintenu par un harnais de sécurité, la remorque devant elle-même répondre à des normes de sécurité."},
  {"id": "kq386", "type": "knowledge", "theme": "securite_passagers", "question": "Le siège passager avant équipé d'un airbag frontal actif doit-il accueillir un enfant en siège dos à la route ?", "options": ["Oui, sans aucune précaution","Non, sauf si l'airbag frontal est désactivé","Oui, uniquement pour les enfants de plus de 3 ans","Cette situation n'existe pas en pratique"], "correctIndex": 1, "explanation": "Un siège dos à la route ne doit jamais être installé à l'avant avec un airbag frontal actif : celui-ci doit impérativement être désactivé pour éviter un risque mortel pour l'enfant en cas de déclenchement."},
  {"id": "kq387", "type": "knowledge", "theme": "securite_passagers", "question": "Une personne de très petite taille (par exemple certaines personnes en situation de handicap) peut, si besoin, utiliser :", "options": ["Aucun dispositif, la ceinture standard suffit toujours","Est dispensée de porter la ceinture sans justification","Un dispositif d'adaptation de ceinture (guide-sangle) pour un meilleur ajustement, sur avis médical si besoin","Doit toujours s'asseoir à l'arrière uniquement"], "correctIndex": 2, "explanation": "Des dispositifs d'adaptation (guide-sangle, coussin réducteur) existent pour ajuster la ceinture aux morphologies particulières, garantissant une protection efficace sans dispense injustifiée."},
  {"id": "kq388", "type": "knowledge", "theme": "securite_passagers", "question": "La dispense de port de la ceinture de sécurité pour raison médicale nécessite :", "options": ["Une simple déclaration orale du conducteur","Aucune formalité particulière","Une autorisation préfectorale uniquement","Un certificat médical d'exemption délivré par un médecin"], "correctIndex": 3, "explanation": "Une dispense de port de la ceinture pour raison médicale doit être justifiée par un certificat médical d'exemption délivré par un médecin, à présenter en cas de contrôle."},
  {"id": "kq389", "type": "knowledge", "theme": "securite_passagers", "question": "En cas de tonneau ou de retournement du véhicule, le port de la ceinture de sécurité :", "options": ["Reste essentiel pour maintenir l'occupant dans l'habitacle et limiter les risques d'éjection","N'a aucune utilité dans ce type de choc","Augmente le risque de blessure","Est inutile si les airbags sont présents"], "correctIndex": 0, "explanation": "En cas de tonneau, la ceinture de sécurité reste déterminante pour maintenir l'occupant à sa place et éviter une éjection du véhicule, situation particulièrement mortelle."},
  {"id": "kq390", "type": "knowledge", "theme": "securite_passagers", "question": "Un enfant transporté dans un siège auto doit avoir les sangles du harnais réglées de façon à :", "options": ["Rester assez lâches pour son confort","Être bien ajustées, en laissant tout juste le passage de deux doigts entre la sangle et l'enfant","Être serrées au maximum, sans aucune souplesse","N'avoir aucune importance particulière"], "correctIndex": 1, "explanation": "Le harnais du siège auto doit être ajusté correctement : ni trop lâche (protection réduite) ni trop serré, l'espace de deux doigts entre la sangle et l'enfant étant le repère communément recommandé."},
  {"id": "kq391", "type": "knowledge", "theme": "securite_passagers", "question": "Porter des vêtements épais ou une doudoune volumineuse sous le harnais d'un siège auto peut :", "options": ["Améliorer la protection de l'enfant","N'a aucune influence sur la sécurité","Fausser le réglage du harnais et réduire son efficacité en cas de choc","Être obligatoire en hiver pour la sécurité"], "correctIndex": 2, "explanation": "Un vêtement épais se comprime lors d'un choc, laissant alors un jeu excessif dans le harnais qui devient moins efficace ; il est recommandé d'attacher l'enfant en vêtements fins puis de le couvrir ensuite d'une couverture par-dessus le harnais."},
  {"id": "kq392", "type": "knowledge", "theme": "securite_passagers", "question": "La ceinture ventrale seule (sans sangle diagonale), présente sur certains sièges centraux arrière anciens, offre :", "options": ["Une protection équivalente à une ceinture trois points","Une protection supérieure pour les enfants","Aucune protection utile","Une protection inférieure, notamment pour le haut du corps en cas de choc frontal"], "correctIndex": 3, "explanation": "La ceinture ventrale seule protège moins bien le haut du corps qu'une ceinture trois points, le buste pouvant être fortement projeté vers l'avant lors d'un choc frontal."},
  {"id": "kq393", "type": "knowledge", "theme": "securite_passagers", "question": "Un airbag genoux, présent sur certains véhicules, vise à :", "options": ["Protéger les genoux et le bassin du conducteur ou du passager avant lors d'un choc frontal","Remplacer l'airbag frontal principal","Protéger uniquement les passagers arrière","N'existe pas dans la réalité"], "correctIndex": 0, "explanation": "L'airbag genoux se déploie sous le tableau de bord pour limiter les mouvements des jambes et protéger les genoux et le bassin lors d'un choc frontal, en complément des autres airbags."},
  {"id": "kq394", "type": "knowledge", "theme": "securite_passagers", "question": "Le voyant d'alerte de ceinture non bouclée, présent sur le tableau de bord, sert à :", "options": ["Signaler une panne moteur","Rappeler à l'occupant concerné (conducteur ou passager selon les véhicules) d'attacher sa ceinture","N'a aucune utilité réelle","Indiquer un problème de freinage"], "correctIndex": 1, "explanation": "Ce voyant, souvent accompagné d'un signal sonore, rappelle qu'une ceinture de sécurité n'est pas bouclée, incitant l'occupant concerné à l'attacher avant de circuler."},
  {"id": "kq395", "type": "knowledge", "theme": "securite_passagers", "question": "Un siège auto endommagé lors d'un accident, même léger, doit en principe être :", "options": ["Réutilisé sans problème s'il paraît intact visuellement","Réparé soi-même à l'aide de colle ou de vis","Remplacé, car sa structure interne peut être fragilisée de façon invisible","Conservé, seule sa housse doit être changée"], "correctIndex": 2, "explanation": "Après un choc, même léger en apparence, la structure interne d'un siège auto peut être fragilisée sans dommage visible ; par précaution, il est recommandé de le remplacer."},
  {"id": "kq396", "type": "knowledge", "theme": "securite_passagers", "question": "Concernant le port du casque à vélo pour les adultes en France :", "options": ["Il est obligatoire dans toutes les circonstances","Il est interdit hors agglomération","Il remplace l'obligation d'équipement rétro-réfléchissant","Il n'est pas obligatoire pour les adultes, mais il reste fortement recommandé pour la sécurité"], "correctIndex": 3, "explanation": "Le port du casque à vélo n'est pas obligatoire pour les adultes en France, contrairement aux enfants de moins de 12 ans, mais il reste vivement recommandé pour limiter les traumatismes crâniens."},
  {"id": "kq397", "type": "knowledge", "theme": "securite_passagers", "question": "Le système de retenue enfant dit « i-Size » se distingue des groupes classiques (0+, 1, 2, 3) car il se base principalement sur :", "options": ["La taille de l'enfant, avec des exigences de sécurité renforcées (notamment contre les chocs latéraux)","Le poids de l'enfant uniquement","L'âge de l'enfant uniquement","La couleur du véhicule"], "correctIndex": 0, "explanation": "La norme i-Size classe les sièges selon la taille de l'enfant plutôt que son poids seul, avec des exigences renforcées, notamment en matière de protection contre les chocs latéraux et de maintien dos à la route plus prolongé."},
  {"id": "kq398", "type": "knowledge", "theme": "securite_passagers", "question": "Les vitres teintées (film sur-teinté) posées sur les vitres avant d'un véhicule, au-delà des normes autorisées, sont :", "options": ["Toujours autorisées pour raison esthétique","Interdites lorsqu'elles réduisent la transparence en dessous du seuil légal, car elles gênent la visibilité et les contrôles","Obligatoires sur autoroute","Autorisées uniquement la nuit"], "correctIndex": 1, "explanation": "Un sur-teintage excessif des vitres avant, réduisant la transparence en dessous du seuil légal, est interdit car il nuit à la visibilité du conducteur et complique l'identification des occupants lors des contrôles."},
  {"id": "kq399", "type": "knowledge", "theme": "securite_passagers", "question": "Un enfant transporté à moto ou en scooter, en tant que passager, doit notamment :", "options": ["N'avoir aucune condition particulière au-delà du casque","Être âgé d'au moins 16 ans obligatoirement","Pouvoir atteindre les repose-pieds et se tenir correctement, en plus de porter un équipement adapté","Être assis devant le conducteur"], "correctIndex": 2, "explanation": "Un enfant passager de deux-roues motorisé doit pouvoir atteindre les repose-pieds et se tenir de façon stable, en plus de porter casque et équipements adaptés, pour limiter les risques en cas de manœuvre ou de choc."},
  {"id": "kq400", "type": "knowledge", "theme": "securite_passagers", "question": "Les feux stop supplémentaires (troisième feu stop central, souvent situé sur la lunette arrière) ont pour objectif de :", "options": ["Décorer le véhicule","Remplacer les feux stop classiques","Indiquer un changement de direction","Améliorer la visibilité du freinage pour les véhicules suivants, notamment en cas de gêne visuelle"], "correctIndex": 3, "explanation": "Ce troisième feu stop, plus haut placé, améliore la visibilité du freinage pour les conducteurs suivants, en particulier lorsque la vue sur les feux stop classiques est masquée par un véhicule intermédiaire."},
  {"id": "kq401", "type": "knowledge", "theme": "securite_passagers", "question": "Concernant la position du siège conducteur, une distance trop faible entre le volant et le buste augmente le risque de :", "options": ["Blessures liées à l'airbag lors de son déploiement","N'a aucune incidence sur la sécurité","Amélioration du confort de conduite uniquement","Fatigue oculaire uniquement"], "correctIndex": 0, "explanation": "Une distance trop faible entre le buste et le volant augmente le risque de blessures lors du déploiement de l'airbag, celui-ci se gonflant à très grande vitesse ; une distance d'environ 25 à 30 cm est généralement recommandée."},
  {"id": "kq402", "type": "knowledge", "theme": "securite_passagers", "question": "En cas d'accident, les airbags latéraux et rideaux se déploient généralement :", "options": ["Uniquement en cas de choc frontal","En cas de choc latéral ou de risque de tonneau selon les capteurs du véhicule","Uniquement en cas de choc arrière","Jamais automatiquement, il faut les activer manuellement"], "correctIndex": 1, "explanation": "Les airbags latéraux et rideaux se déclenchent automatiquement en fonction des capteurs du véhicule, principalement lors d'un choc latéral ou d'un risque de retournement, en complément des airbags frontaux."},
  {"id": "kq403", "type": "knowledge", "theme": "securite_passagers", "question": "Les protections auditives ou bouchons d'oreilles portés par un conducteur au volant sont :", "options": ["Autorisés sans restriction, comme pour un passager","Obligatoires sur autoroute","Interdits, car ils réduisent la perception des bruits environnants indispensables à la conduite (sirènes, klaxons)","Uniquement interdits de nuit"], "correctIndex": 2, "explanation": "Réduire sa perception auditive au volant, par des bouchons d'oreilles ou tout dispositif similaire, est interdit car cela empêche de percevoir les avertissements sonores essentiels à la sécurité (klaxons, sirènes)."},
  {"id": "kq404", "type": "knowledge", "theme": "securite_passagers", "question": "Une ceinture de sécurité endommagée (sangle effilochée, boucle défectueuse) doit être :", "options": ["Utilisée sans problème tant qu'elle attache toujours","Ignorée, ce n'est pas un point de contrôle technique","Remplacée uniquement si elle casse complètement","Réparée ou remplacée rapidement, son efficacité n'étant plus garantie"], "correctIndex": 3, "explanation": "Une ceinture endommagée peut céder ou mal fonctionner lors d'un choc : elle doit être réparée ou remplacée rapidement, ce point étant d'ailleurs vérifié lors du contrôle technique."},
  {"id": "kq405", "type": "knowledge", "theme": "securite_passagers", "question": "En France, le port du casque est-il obligatoire pour les enfants transportés en vélo cargo ou biporteur ?", "options": ["Oui, comme pour tout enfant de moins de 12 ans circulant à vélo, y compris comme passager","Non, jamais, quel que soit leur âge","Uniquement à partir de 6 ans","Uniquement sur autoroute"], "correctIndex": 0, "explanation": "Le port du casque s'applique à tout enfant de moins de 12 ans circulant à vélo, qu'il en soit le conducteur ou simplement transporté comme passager, y compris dans un vélo cargo ou biporteur."},
  {"id": "kq406", "type": "knowledge", "theme": "securite_passagers", "question": "Un siège auto installé face à la route trop tôt, avant que l'enfant n'ait la maturité osseuse suffisante, expose principalement à un risque accru en cas de :", "options": ["Choc arrière uniquement","Choc frontal, le plus fréquent et le plus violent statistiquement","Aucun risque particulier","Accident sans collision"], "correctIndex": 1, "explanation": "Le choc frontal étant le type d'accident le plus fréquent et souvent le plus violent, un enfant trop tôt installé face à la route y est particulièrement exposé, d'où la recommandation de rester dos à la route le plus longtemps possible."},
  {"id": "kq407", "type": "knowledge", "theme": "securite_passagers", "question": "Les rétroviseurs extérieurs, en plus du rétroviseur intérieur, doivent être réglés de façon à :", "options": ["Voir uniquement l'arrière immédiat du véhicule","N'avoir aucune importance particulière","Réduire au maximum les angles morts en couvrant une zone légèrement chevauchant celle du rétroviseur intérieur","Être réglés uniquement par un professionnel"], "correctIndex": 2, "explanation": "Un bon réglage des rétroviseurs extérieurs, complétant le rétroviseur intérieur avec une légère zone de recouvrement, permet de réduire au maximum les angles morts dangereux lors des changements de direction."},
  {"id": "kq408", "type": "knowledge", "theme": "securite_passagers", "question": "Concernant un enfant transporté en trottinette électrique en tant que passager (debout devant ou derrière le conducteur), cette pratique est :", "options": ["Autorisée sans restriction sur une trottinette prévue pour un seul utilisateur","Autorisée uniquement sur piste cyclable","Autorisée si l'enfant porte un casque","Interdite et dangereuse, les trottinettes électriques standard n'étant homologuées que pour un seul utilisateur"], "correctIndex": 3, "explanation": "Une trottinette électrique classique n'est conçue et homologuée que pour un seul utilisateur : y transporter un enfant en plus est interdit et particulièrement dangereux, l'engin devenant instable."},
  {"id": "kq409", "type": "knowledge", "theme": "equipements", "question": "Le témoin lumineux orange en forme de moteur (« check engine ») allumé au tableau de bord signale :", "options": ["Un dysfonctionnement du moteur ou de son système antipollution nécessitant une vérification","Un niveau de carburant bas","Une porte mal fermée","Un simple rappel d'entretien sans urgence"], "correctIndex": 0, "explanation": "Ce témoin signale un dysfonctionnement détecté par l'électronique du moteur ou du système antipollution ; il est recommandé de faire vérifier le véhicule rapidement, sans attendre une panne plus grave."},
  {"id": "kq410", "type": "knowledge", "theme": "equipements", "question": "Le témoin rouge en forme de burette d'huile allumé pendant la conduite indique généralement :", "options": ["Un simple rappel de vidange à prévoir prochainement","Une pression d'huile insuffisante, nécessitant l'arrêt immédiat du moteur","Un niveau de liquide lave-glace bas","Un problème avec la climatisation"], "correctIndex": 1, "explanation": "Un témoin rouge de pression d'huile signale un problème grave et immédiat : il faut arrêter le moteur au plus vite pour éviter une casse mécanique majeure."},
  {"id": "kq411", "type": "knowledge", "theme": "equipements", "question": "Les phares antibrouillard avant doivent être utilisés :", "options": ["En permanence de nuit, même par temps clair","Uniquement en agglomération","En cas de conditions de visibilité réduite (brouillard, forte pluie, neige)","Jamais, ils sont purement décoratifs"], "correctIndex": 2, "explanation": "Les feux antibrouillard avant, positionnés bas, servent à améliorer l'éclairage de la chaussée en cas de conditions de visibilité réduite (brouillard, fortes pluies, neige), et non en usage permanent de nuit."},
  {"id": "kq412", "type": "knowledge", "theme": "equipements", "question": "L'usage abusif des feux de route (pleins phares) en présence d'un véhicule venant en face est sanctionné car il :", "options": ["Améliore la visibilité de l'autre conducteur","N'a aucun effet sur les autres usagers","Est réservé aux véhicules prioritaires","Peut éblouir et donc mettre en danger le conducteur venant en face"], "correctIndex": 3, "explanation": "Les feux de route, très puissants, doivent être basculés en feux de croisement dès qu'un véhicule arrive en face ou est suivi de près, pour ne pas éblouir et provoquer un accident."},
  {"id": "kq413", "type": "knowledge", "theme": "equipements", "question": "Un rétroviseur cassé ou manquant sur un véhicule constitue :", "options": ["Une infraction sanctionnable, réduisant la visibilité nécessaire à une conduite sûre","Un simple défaut esthétique sans conséquence","Un motif de retrait automatique du permis","Une situation tolérée tant qu'il en reste un"], "correctIndex": 0, "explanation": "Un rétroviseur manquant ou cassé réduit la visibilité du conducteur sur son environnement et constitue une infraction sanctionnable, en plus d'être un point de contrôle technique."},
  {"id": "kq414", "type": "knowledge", "theme": "equipements", "question": "Le liquide de frein d'un véhicule doit être :", "options": ["Vérifié uniquement en cas de panne","Contrôlé régulièrement et remplacé selon les préconisations du constructeur, car il se dégrade avec le temps","Rempli une seule fois à l'achat du véhicule","Sans importance pour la sécurité"], "correctIndex": 1, "explanation": "Le liquide de frein absorbe l'humidité avec le temps, ce qui réduit son efficacité ; il doit être contrôlé régulièrement et changé selon les recommandations du constructeur, faute de quoi le freinage peut être compromis."},
  {"id": "kq415", "type": "knowledge", "theme": "equipements", "question": "Le témoin ABS allumé en permanence au tableau de bord signifie :", "options": ["Que le système ABS fonctionne parfaitement","Que les freins classiques sont hors service","Qu'une anomalie du système antiblocage a été détectée et qu'il faut faire vérifier le véhicule","Que le véhicule doit rouler plus vite"], "correctIndex": 2, "explanation": "Un témoin ABS allumé en continu (hors phase de démarrage) signale une anomalie du système antiblocage, qui doit être diagnostiquée rapidement, le freinage classique restant néanmoins opérationnel."},
  {"id": "kq416", "type": "knowledge", "theme": "equipements", "question": "Les pneus doivent être remplacés lorsque :", "options": ["Ils atteignent exactement 5 ans, quel que soit leur état","Ils changent légèrement de couleur","Uniquement lorsqu'ils crèvent","Leur profondeur de sculpture approche ou dépasse le seuil légal de 1,6 mm, ou qu'ils sont endommagés"], "correctIndex": 3, "explanation": "Un pneu doit être remplacé dès que sa profondeur de sculpture approche le seuil légal de 1,6 mm, ou en cas de dommage visible (hernie, coupure), indépendamment de son âge seul."},
  {"id": "kq417", "type": "knowledge", "theme": "equipements", "question": "L'utilisation de pneus différents à l'avant et à l'arrière (marque, dimension, type) est :", "options": ["Réglementée : certains écarts sont interdits pour préserver la stabilité du véhicule","Toujours autorisée sans restriction","Recommandée pour améliorer la tenue de route","Sans importance pour la sécurité"], "correctIndex": 0, "explanation": "Monter des pneus de dimensions ou de types très différents entre l'avant et l'arrière peut déstabiliser le comportement du véhicule ; la réglementation encadre strictement ces écarts pour garantir la sécurité."},
  {"id": "kq418", "type": "knowledge", "theme": "equipements", "question": "Les essuie-glaces arrière sont particulièrement utiles sur :", "options": ["Les seules berlines","Les véhicules avec hayon (break, SUV, monospace), la lunette arrière étant plus exposée aux projections","Aucun type de véhicule en particulier","Uniquement les véhicules électriques"], "correctIndex": 1, "explanation": "Sur les véhicules à hayon, la lunette arrière est particulièrement exposée aux projections de boue ou d'eau ; l'essuie-glace arrière y est donc très utile pour maintenir une bonne visibilité."},
  {"id": "kq419", "type": "knowledge", "theme": "equipements", "question": "Une batterie de véhicule déchargée en hiver s'explique notamment par :", "options": ["Une augmentation de sa capacité par temps froid","Un phénomène propre aux véhicules électriques uniquement","Une réduction de sa capacité par temps froid, combinée à une sollicitation accrue (chauffage, éclairage)","L'absence totale de lien avec la température"], "correctIndex": 2, "explanation": "Le froid réduit la capacité chimique d'une batterie tout en augmentant les besoins électriques (chauffage, dégivrage, éclairage), ce qui explique la fréquence des pannes de batterie en hiver."},
  {"id": "kq420", "type": "knowledge", "theme": "equipements", "question": "Concernant les feux de jour (DRL) présents sur de nombreux véhicules récents, ils permettent notamment :", "options": ["De remplacer totalement les feux de croisement de nuit","De réduire la consommation de carburant du moteur","Ne servent à rien de particulier","D'améliorer la visibilité du véhicule de jour, sans pour autant remplacer les feux de croisement obligatoires de nuit"], "correctIndex": 3, "explanation": "Les feux de jour améliorent la visibilité du véhicule en journée, mais ne remplacent jamais les feux de croisement obligatoires de nuit ou par visibilité insuffisante, ces derniers éclairant bien plus la route."},
  {"id": "kq421", "type": "knowledge", "theme": "equipements", "question": "Une roue de secours dite « galette » (roue de dépannage temporaire) impose généralement :", "options": ["De limiter sa vitesse (souvent à 80 km/h) et de la remplacer par un pneu standard rapidement","De rouler normalement, sans aucune restriction","De rouler exclusivement sur autoroute","D'attendre plusieurs semaines avant de la changer"], "correctIndex": 0, "explanation": "Une roue de secours temporaire (galette) impose une limitation de vitesse, généralement autour de 80 km/h, et doit être remplacée par un pneu standard dès que possible, n'étant pas conçue pour un usage prolongé."},
  {"id": "kq422", "type": "knowledge", "theme": "equipements", "question": "Le contrôle du niveau de liquide de refroidissement est important car :", "options": ["Il n'a aucune influence sur le fonctionnement du moteur","Un niveau insuffisant peut provoquer une surchauffe et endommager gravement le moteur","Il concerne uniquement l'esthétique du moteur","Il remplace le contrôle du niveau d'huile"], "correctIndex": 1, "explanation": "Le liquide de refroidissement évite la surchauffe du moteur ; un niveau insuffisant peut entraîner une surchauffe et des dommages mécaniques graves, parfois irréversibles."},
  {"id": "kq423", "type": "knowledge", "theme": "equipements", "question": "Les catadioptres (réflecteurs) placés à l'arrière d'un véhicule servent à :", "options": ["Éclairer la route la nuit","Indiquer un changement de direction","Réfléchir la lumière des phares d'un véhicule suiveur pour le rendre visible de nuit sans éclairage propre","N'ont aucune utilité pratique"], "correctIndex": 2, "explanation": "Les catadioptres ne produisent pas de lumière eux-mêmes mais réfléchissent celle des phares d'un véhicule suiveur, rendant le véhicule visible même feux éteints, notamment en cas de panne électrique."},
  {"id": "kq424", "type": "knowledge", "theme": "equipements", "question": "Les plaquettes de frein usées se manifestent souvent par :", "options": ["Un silence total lors du freinage","Une amélioration du freinage","Aucun signe détectable avant la panne totale","Un grincement ou un crissement lors du freinage, signe d'usure à vérifier rapidement"], "correctIndex": 3, "explanation": "Des plaquettes de frein usées produisent souvent un grincement ou un crissement caractéristique lors du freinage : un signal à ne pas ignorer pour éviter une perte d'efficacité du freinage, voire une panne des freins."},
  {"id": "kq425", "type": "knowledge", "theme": "equipements", "question": "L'éthylotest anti-démarrage (EAD), lorsqu'il est imposé, empêche le démarrage du véhicule si :", "options": ["Le taux d'alcool détecté dépasse le seuil autorisé configuré sur l'appareil","Le conducteur n'a pas bouclé sa ceinture","Le véhicule n'est pas assuré","Le contrôle technique n'est pas valide"], "correctIndex": 0, "explanation": "L'éthylotest anti-démarrage bloque le démarrage du véhicule tant que le conducteur n'a pas soufflé dans l'appareil et que son taux d'alcool ne dépasse pas le seuil configuré."},
  {"id": "kq426", "type": "knowledge", "theme": "equipements", "question": "Sur autoroute, en cas de crevaison, il est déconseillé de :", "options": ["Se garer le plus à droite possible sur la bande d'arrêt d'urgence","Continuer à rouler sur une longue distance à faible vitesse pour rejoindre la prochaine sortie","Allumer ses feux de détresse","Enfiler le gilet haute visibilité avant de sortir"], "correctIndex": 1, "explanation": "Rouler longtemps sur un pneu crevé, même lentement, endommage la jante et peut faire perdre le contrôle du véhicule : il faut s'arrêter dès que possible sur la bande d'arrêt d'urgence."},
  {"id": "kq427", "type": "knowledge", "theme": "equipements", "question": "Les jantes ou pneus visiblement endommagés (déformation, hernie, fissure) doivent :", "options": ["Être surveillés sans urgence particulière","Être réparés uniquement s'ils fuient","Être remplacés rapidement, le risque d'éclatement étant important","N'ont aucune conséquence sur la sécurité tant que le pneu tient l'air"], "correctIndex": 2, "explanation": "Une hernie, une fissure ou une déformation de jante ou de pneu augmente fortement le risque d'éclatement en roulant : un remplacement rapide s'impose, sans attendre un signe de fuite."},
  {"id": "kq428", "type": "knowledge", "theme": "equipements", "question": "Concernant le port de la ceinture, les prétensionneurs pyrotechniques doivent-ils être remplacés après un déclenchement ?", "options": ["Non, ils se réarment automatiquement","Cela dépend uniquement de la marque du véhicule","Non, ils ne se déclenchent jamais qu'une seule fois dans la vie du véhicule sans besoin de remplacement","Oui, un prétensionneur pyrotechnique déclenché doit être remplacé, comme un airbag"], "correctIndex": 3, "explanation": "Comme les airbags, les prétensionneurs pyrotechniques utilisent une charge à usage unique : une fois déclenchés lors d'un choc, ils doivent être remplacés pour rester efficaces en cas de nouvel accident."},
  {"id": "kq429", "type": "knowledge", "theme": "equipements", "question": "Les phares xénon ou LED mal réglés, éblouissant les autres usagers, constituent :", "options": ["Un danger et une infraction, le réglage des feux devant limiter l'éblouissement","Un simple inconvénient esthétique","Un avantage pour la sécurité du conducteur uniquement","Une situation sans solution technique"], "correctIndex": 0, "explanation": "Un mauvais réglage des projecteurs, quelle que soit leur technologie, peut éblouir dangereusement les autres usagers : le réglage correct des feux est un point vérifié lors du contrôle technique."},
  {"id": "kq430", "type": "knowledge", "theme": "equipements", "question": "Le port de chaînes à neige nécessite en général de :", "options": ["Rouler à vitesse normale, sans restriction","Adapter sa vitesse (généralement limitée à environ 50 km/h) et les retirer dès que la chaussée redevient dégagée","Ne jamais dépasser 10 km/h","Les utiliser uniquement sur autoroute"], "correctIndex": 1, "explanation": "Les chaînes à neige imposent une vitesse réduite (souvent limitée à environ 50 km/h) et doivent être retirées dès que la route redevient praticable sans elles, pour ne pas endommager la chaussée ni les pneus."},
  {"id": "kq431", "type": "knowledge", "theme": "equipements", "question": "Un pare-brise fissuré, même légèrement, dans le champ de vision du conducteur :", "options": ["Peut être ignoré tant que la fissure est petite","Améliore la résistance du pare-brise","Doit être réparé ou remplacé rapidement, car il peut gêner la vision et fragiliser la structure du véhicule","N'est jamais contrôlé lors du contrôle technique"], "correctIndex": 2, "explanation": "Une fissure dans le champ de vision du conducteur gêne la perception des dangers et peut s'agrandir, fragilisant la structure du pare-brise qui participe à la rigidité de l'habitacle ; une réparation rapide est recommandée."},
  {"id": "kq432", "type": "knowledge", "theme": "equipements", "question": "L'entretien de la courroie de distribution d'un moteur, selon les préconisations du constructeur, est important car :", "options": ["Sa rupture n'a aucune conséquence grave","Elle n'a aucun rôle mécanique","Elle concerne uniquement les véhicules diesel","Sa rupture peut endommager gravement, voire détruire le moteur"], "correctIndex": 3, "explanation": "La rupture d'une courroie de distribution usée peut provoquer une casse moteur importante et coûteuse ; son remplacement selon les préconisations du constructeur (kilométrage ou durée) est essentiel."},
  {"id": "kq433", "type": "knowledge", "theme": "equipements", "question": "Concernant les feux de recul (marche arrière), ils s'allument automatiquement pour :", "options": ["Éclairer et signaler une manœuvre de recul aux usagers situés derrière le véhicule","Signaler un dépassement","Indiquer un freinage d'urgence","Remplacer les feux de croisement"], "correctIndex": 0, "explanation": "Les feux de recul, blancs, s'allument automatiquement en marche arrière pour éclairer la zone et avertir les autres usagers (piétons, véhicules) de la manœuvre en cours."},
  {"id": "kq434", "type": "knowledge", "theme": "equipements", "question": "Une plaque d'immatriculation non éclairée de nuit constitue :", "options": ["Une situation sans importance","Une infraction, l'éclairage de la plaque arrière étant obligatoire de nuit","Une obligation réservée aux seuls poids lourds","Une infraction uniquement sur autoroute"], "correctIndex": 1, "explanation": "La plaque d'immatriculation arrière doit être éclairée dès que les feux de position ou de croisement sont allumés, afin de rester lisible de nuit ; son absence d'éclairage est une infraction."},
  {"id": "kq435", "type": "knowledge", "theme": "equipements", "question": "Les vitres et le pare-brise doivent être dégivrés entièrement avant de circuler, car conduire avec une vision partielle (un simple « trou » dégivré) est :", "options": ["Autorisé si le trajet est court","Sans conséquence pratique","Dangereux et sanctionnable, la visibilité devant être complète","Uniquement un problème de confort"], "correctIndex": 2, "explanation": "Conduire avec un pare-brise partiellement dégivré réduit fortement le champ de vision et constitue une infraction, en plus d'un risque important pour la sécurité."},
  {"id": "kq436", "type": "knowledge", "theme": "equipements", "question": "L'installation d'un attelage supplémentaire non homologué sur un véhicule peut entraîner, lors du contrôle technique :", "options": ["Aucune remarque particulière","Une validation automatique","Une interdiction définitive du véhicule","Une contre-visite, cet équipement devant être conforme et compatible avec le véhicule"], "correctIndex": 3, "explanation": "Un attelage non homologué ou incompatible avec le véhicule peut entraîner une contre-visite lors du contrôle technique, cet équipement devant répondre à des normes précises."},
  {"id": "kq437", "type": "knowledge", "theme": "equipements", "question": "La date de péremption ou de fabrication d'un pneu (indiquée par un code sur le flanc) est utile car :", "options": ["Un pneu vieillit et perd en performance même s'il est peu usé","Elle est purement décorative","Elle indique uniquement le pays de fabrication","Elle n'a aucun lien avec la sécurité"], "correctIndex": 0, "explanation": "Le caoutchouc d'un pneu se durcit et perd en performance avec le temps, même s'il est peu usé en surface : le code DOT sur le flanc indique la semaine et l'année de fabrication, une information utile pour évaluer son vieillissement."},
  {"id": "kq438", "type": "knowledge", "theme": "equipements", "question": "Un klaxon (avertisseur sonore) défectueux constitue, en cas de contrôle :", "options": ["Un point sans importance, il n'est jamais vérifié","Une infraction, cet équipement de sécurité devant être fonctionnel","Une simple recommandation d'entretien","Une infraction uniquement pour les motos"], "correctIndex": 1, "explanation": "L'avertisseur sonore est un équipement de sécurité obligatoire et doit être fonctionnel ; son absence de fonctionnement constitue une infraction, notamment vérifiable lors d'un contrôle technique ou routier."},
  {"id": "kq439", "type": "knowledge", "theme": "equipements", "question": "Une remorque ou une caravane doit disposer de son propre système de freinage lorsque :", "options": ["Dans tous les cas, quelle que soit sa masse","Jamais, seul le véhicule tracteur doit freiner","Son PTAC dépasse un certain seuil (généralement 750 kg)","Uniquement si elle transporte des animaux"], "correctIndex": 2, "explanation": "Au-delà d'un certain seuil de PTAC (généralement 750 kg), une remorque doit être équipée de son propre système de freinage, se déclenchant automatiquement avec celui du véhicule tracteur."},
  {"id": "kq440", "type": "knowledge", "theme": "secours", "question": "Face à un accident, la deuxième étape du sigle PAS, « Alerter », consiste à :", "options": ["Déplacer immédiatement les victimes","Prendre des photos pour l'assurance uniquement","Attendre qu'un autre témoin s'en charge","Prévenir les secours en composant le bon numéro et en donnant des informations précises"], "correctIndex": 3, "explanation": "Alerter consiste à prévenir rapidement les services de secours appropriés (15, 17, 18 ou 112) en fournissant une localisation précise et les informations essentielles sur la situation."},
  {"id": "kq441", "type": "knowledge", "theme": "secours", "question": "La troisième étape du sigle PAS, « Secourir », signifie :", "options": ["Effectuer les gestes de premiers secours à sa portée, dans la limite de ses compétences, en attendant les secours professionnels","Pratiquer systématiquement un massage cardiaque, même sans formation","Transporter la victime soi-même à l'hôpital","Donner à boire à la victime pour la réconforter"], "correctIndex": 0, "explanation": "Secourir signifie apporter les gestes de premiers secours adaptés à la situation et à ses compétences (arrêt d'une hémorragie, PLS...) en attendant l'arrivée des secours professionnels, sans se substituer à eux."},
  {"id": "kq442", "type": "knowledge", "theme": "secours", "question": "Avant d'intervenir auprès d'une victime, il faut d'abord vérifier :", "options": ["Uniquement l'état de conscience de la victime","Qu'aucun danger persistant ne menace le sauveteur lui-même","Uniquement la présence d'autres témoins","Rien, il faut agir immédiatement sans vérification"], "correctIndex": 1, "explanation": "La première règle de secourisme est de ne jamais se mettre soi-même en danger : il faut s'assurer que la zone est sécurisée avant d'approcher la victime."},
  {"id": "kq443", "type": "knowledge", "theme": "secours", "question": "Pour vérifier si une victime est consciente, le geste habituel consiste à :", "options": ["La secouer fortement par les épaules","Lui donner une gifle légère","Lui parler et lui demander de serrer la main ou d'ouvrir les yeux","Vérifier uniquement sa respiration sans lui parler"], "correctIndex": 2, "explanation": "On évalue la conscience en parlant à la victime et en lui demandant de réagir (serrer la main, ouvrir les yeux), sans la secouer, ce qui pourrait aggraver une éventuelle blessure."},
  {"id": "kq444", "type": "knowledge", "theme": "secours", "question": "Une victime inconsciente qui ne respire pas nécessite immédiatement :", "options": ["La position latérale de sécurité","De lui donner à boire","D'attendre les secours sans intervenir","Un massage cardiaque, idéalement associé à l'usage d'un défibrillateur si disponible"], "correctIndex": 3, "explanation": "Face à une victime inconsciente qui ne respire pas (arrêt cardio-respiratoire), il faut débuter immédiatement un massage cardiaque et utiliser un défibrillateur automatisé externe si un est disponible à proximité."},
  {"id": "kq445", "type": "knowledge", "theme": "secours", "question": "Un défibrillateur automatisé externe (DAE) accessible au public peut être utilisé par :", "options": ["Toute personne, y compris sans formation médicale, l'appareil guidant vocalement l'utilisateur","Uniquement des professionnels de santé","Uniquement les pompiers","Personne, c'est un appareil réservé aux hôpitaux"], "correctIndex": 0, "explanation": "Un DAE est conçu pour être utilisé par toute personne, même sans formation médicale : l'appareil guide vocalement chaque étape et n'administre un choc que si celui-ci est réellement nécessaire."},
  {"id": "kq446", "type": "knowledge", "theme": "secours", "question": "Concernant l'utilisation d'un extincteur en cas de départ de feu dans un véhicule, il faut avant tout :", "options": ["S'approcher le plus près possible avant d'agir","Évaluer le danger et ne l'utiliser que si le feu est encore maîtrisable, en gardant une voie de repli","L'utiliser uniquement sur un feu déjà éteint","L'utiliser sans jamais couper le contact du véhicule"], "correctIndex": 1, "explanation": "Un extincteur ne doit être utilisé que sur un début d'incendie encore maîtrisable, en gardant toujours une possibilité de repli ; si le feu est trop développé, il vaut mieux s'éloigner et alerter les secours."},
  {"id": "kq447", "type": "knowledge", "theme": "secours", "question": "En cas de choc électrique sur une personne à proximité d'un véhicule électrique accidenté, il faut avant tout :", "options": ["La toucher directement pour la dégager","L'arroser d'eau pour refroidir la zone","Ne pas la toucher directement et couper si possible l'alimentation électrique avant tout contact, ou alerter immédiatement les secours spécialisés","Attendre sans rien faire"], "correctIndex": 2, "explanation": "Face à un risque électrique, il ne faut jamais toucher directement la victime tant que le courant n'est pas coupé ; il vaut mieux alerter immédiatement les secours formés à ce type d'intervention spécifique."},
  {"id": "kq448", "type": "knowledge", "theme": "secours", "question": "Une victime en état de choc (pâleur, sueurs froides, pouls rapide) après un accident doit être :", "options": ["Mise debout rapidement pour vérifier son état","Laissée totalement seule pour se reposer","Encouragée à marcher pour se calmer","Allongée si possible, rassurée, couverte, et surveillée en attendant les secours"], "correctIndex": 3, "explanation": "Une victime en état de choc doit être allongée si son état le permet, rassurée, couverte pour éviter le refroidissement, et surveillée attentivement jusqu'à l'arrivée des secours."},
  {"id": "kq449", "type": "knowledge", "theme": "secours", "question": "Pour une brûlure légère consécutive à un accident, le premier geste recommandé est :", "options": ["Refroidir la zone à l'eau tempérée pendant plusieurs minutes","Appliquer immédiatement de la glace directement sur la peau","Appliquer une pommade grasse immédiatement","Percer les éventuelles cloques"], "correctIndex": 0, "explanation": "Le refroidissement d'une brûlure à l'eau tempérée (ni glacée ni chaude) pendant plusieurs minutes limite l'approfondissement de la lésion ; il ne faut ni glace directe, ni pommade, ni percer les cloques."},
  {"id": "kq450", "type": "knowledge", "theme": "secours", "question": "Face à une fracture apparente d'un membre chez une victime consciente, il faut :", "options": ["Tenter de remettre l'os en place soi-même","Ne pas mobiliser le membre et attendre les secours qui l'immobiliseront correctement","Masser fortement la zone pour soulager la douleur","Faire marcher la victime pour tester la gravité"], "correctIndex": 1, "explanation": "Face à une fracture suspectée, il ne faut surtout pas mobiliser le membre ni tenter de le remettre en place : seuls les secours disposent du matériel et des compétences pour une immobilisation sans risque supplémentaire."},
  {"id": "kq451", "type": "knowledge", "theme": "secours", "question": "Le rôle des « témoins » d'un accident, en dehors des secouristes, peut inclure :", "options": ["Ne jamais s'arrêter, la loi l'interdit","Filmer la scène pour les réseaux sociaux avant d'agir","Baliser les lieux, alerter les secours et rassurer les victimes, dans la limite de leurs compétences","Intervenir uniquement s'ils sont médecins"], "correctIndex": 2, "explanation": "Tout témoin peut légitimement contribuer à protéger les lieux, alerter les secours et rassurer les victimes, sans avoir besoin d'une qualification médicale pour ces gestes de base."},
  {"id": "kq452", "type": "knowledge", "theme": "secours", "question": "Ne pas porter secours à une personne en danger, alors qu'on aurait pu le faire sans risque pour soi-même, constitue en droit français :", "options": ["Une simple négligence sans conséquence légale","Une faute uniquement civile","Une situation sans existence légale","Le délit de non-assistance à personne en danger, sanctionné pénalement"], "correctIndex": 3, "explanation": "La non-assistance à personne en danger est un délit pénal en France, sanctionné lorsque l'on s'abstient volontairement de porter secours ou de le faire porter alors qu'on le pouvait sans risque pour soi ou pour des tiers."},
  {"id": "kq453", "type": "knowledge", "theme": "secours", "question": "Un extincteur de type ABC convient généralement pour éteindre :", "options": ["Une large variété de feux : solides, liquides et gaz courants","Uniquement les feux électriques","Uniquement les feux de graisse","Uniquement les feux de forêt"], "correctIndex": 0, "explanation": "Un extincteur polyvalent de type ABC est conçu pour être efficace sur les principaux types de feux courants (solides, liquides, gaz), ce qui en fait un bon choix général, notamment pour un véhicule."},
  {"id": "kq454", "type": "knowledge", "theme": "secours", "question": "Face à une personne inconsciente qui respire, mais que l'on soupçonne un traumatisme du dos ou de la nuque (chute, choc violent), il faut :", "options": ["La mettre systématiquement en PLS sans précaution","Limiter au maximum toute mobilisation du cou et du dos, et privilégier l'appel aux secours spécialisés qui adapteront leur geste","La redresser en position assise","La faire marcher immédiatement pour vérifier ses réflexes"], "correctIndex": 1, "explanation": "En cas de suspicion de traumatisme du rachis, il faut limiter au maximum toute mobilisation et alerter au plus vite les secours, formés à des techniques adaptées (mise en PLS sécurisée si vraiment nécessaire, avec protection de l'axe tête-cou-tronc)."},
  {"id": "kq455", "type": "knowledge", "theme": "secours", "question": "Concernant une trousse de premiers secours dans un véhicule, bien qu'elle ne soit pas légalement obligatoire pour un véhicule particulier, elle est utile pour :", "options": ["Remplacer l'intervention des secours professionnels","Réparer le véhicule en cas de panne","Effectuer les premiers gestes simples (pansements, désinfection) en attendant les secours si nécessaire","N'a aucune utilité pratique"], "correctIndex": 2, "explanation": "Bien que non obligatoire pour une voiture particulière, une trousse de premiers secours permet de traiter de petites blessures ou d'attendre les secours dans de meilleures conditions en cas d'accident léger."},
  {"id": "kq456", "type": "knowledge", "theme": "secours", "question": "Lorsqu'on alerte les secours par téléphone, il ne faut jamais raccrocher :", "options": ["Après avoir donné son nom","Dès que l'on a donné l'adresse","Après 10 secondes maximum","Avant que l'opérateur ne le demande explicitement, pour ne perdre aucune information utile"], "correctIndex": 3, "explanation": "Il est essentiel de rester en ligne et de ne raccrocher qu'à l'indication de l'opérateur des secours, qui peut avoir besoin de précisions complémentaires ou donner des instructions pendant l'attente des secours."},
  {"id": "kq457", "type": "knowledge", "theme": "secours", "question": "Sur route ou autoroute la nuit, en cas d'arrêt d'urgence, en plus du gilet et du triangle, il est recommandé de :", "options": ["Allumer les feux de détresse et se signaler le plus tôt possible aux autres usagers","Éteindre tous les feux du véhicule pour ne pas gêner","Se placer devant le véhicule pour être vu","Ne rien faire de particulier, la nuit ne change rien"], "correctIndex": 0, "explanation": "De nuit, il est essentiel d'allumer les feux de détresse et de se signaler au plus vite (gilet, triangle) pour être vu par les autres usagers, le risque de sur-accident étant plus élevé dans l'obscurité."},
  {"id": "kq458", "type": "knowledge", "theme": "secours", "question": "Après un accident impliquant plusieurs véhicules, s'il n'y a aucun blessé et que la circulation n'est pas gênée, il est recommandé de :", "options": ["Laisser les véhicules en l'état, sur la chaussée, en attendant la police","Dégager si possible les véhicules hors de la chaussée avant de remplir le constat","Appeler systématiquement les pompiers","Quitter les lieux immédiatement sans échanger d'informations"], "correctIndex": 1, "explanation": "En l'absence de blessé, il est conseillé de dégager rapidement les véhicules de la chaussée (pour éviter un sur-accident) avant de remplir tranquillement le constat amiable en sécurité."},
  {"id": "kq459", "type": "knowledge", "theme": "secours", "question": "Concernant l'hémorragie interne (non visible de l'extérieur), les signes pouvant alerter incluent notamment :", "options": ["Une peau très colorée et chaude","Une amélioration soudaine de l'état général","Une pâleur importante, des sueurs, une soif intense et un pouls rapide","Aucun signe n'est jamais détectable"], "correctIndex": 2, "explanation": "Une hémorragie interne, invisible directement, peut se traduire par une pâleur marquée, des sueurs, une soif intense et un pouls rapide : des signes de choc hémorragique qui doivent alerter et être signalés aux secours."},
  {"id": "kq460", "type": "knowledge", "theme": "secours", "question": "Concernant un objet planté profondément dans une plaie (corps étranger empalé), il faut :", "options": ["Le retirer immédiatement pour désinfecter la plaie","Le pousser plus profondément pour éviter qu'il ne bouge","L'ignorer et couvrir simplement la plaie sans précaution","Ne jamais le retirer soi-même, mais le stabiliser en attendant les secours"], "correctIndex": 3, "explanation": "Un objet empalé ne doit jamais être retiré par un témoin, son retrait pouvant aggraver une hémorragie ; il faut le stabiliser autour (sans appuyer dessus) et attendre les secours qui géreront son extraction en sécurité."},
  {"id": "kq461", "type": "knowledge", "theme": "secours", "question": "Un enfant victime d'un accident nécessite, en cas d'arrêt cardio-respiratoire, une technique de massage cardiaque :", "options": ["Adaptée à sa morphologie (force et zone d'appui différentes), idéalement guidée par l'opérateur des secours au téléphone","Rigoureusement identique à celle d'un adulte, sans aucune adaptation","Interdite, il faut uniquement attendre les secours sans agir","Réalisable uniquement par un médecin"], "correctIndex": 0, "explanation": "Le massage cardiaque chez l'enfant nécessite une adaptation de la force et parfois de la technique (une ou deux mains selon l'âge) ; l'opérateur des secours peut guider un témoin non formé au téléphone en attendant les secours."},
  {"id": "kq462", "type": "knowledge", "theme": "secours", "question": "Face à un accident avec plusieurs blessés de gravité différente, en attendant les secours, la priorité doit être donnée à :", "options": ["La personne qui se plaint le plus fort","Les fonctions vitales (conscience, respiration, hémorragie), en traitant en premier les urgences vitales","La personne la plus âgée systématiquement","Le conducteur responsable de l'accident"], "correctIndex": 1, "explanation": "Face à plusieurs victimes, il faut évaluer rapidement les fonctions vitales de chacune et traiter en priorité les urgences vitales (arrêt respiratoire, hémorragie massive), indépendamment de qui se manifeste le plus."},
  {"id": "kq463", "type": "knowledge", "theme": "secours", "question": "Concernant les numéros d'urgence, le 114 en France est réservé :", "options": ["Aux urgences vétérinaires","Aux dépannages automobiles uniquement","Aux appels d'urgence par SMS pour les personnes sourdes ou malentendantes","Il n'existe aucun numéro appelé 114"], "correctIndex": 2, "explanation": "Le 114 est le numéro d'urgence national accessible par SMS ou visio, destiné aux personnes sourdes, malentendantes, aphasiques ou dysphasiques ne pouvant pas téléphoner classiquement."},
  {"id": "kq464", "type": "knowledge", "theme": "secours", "question": "Un airbag qui s'est déclenché lors d'un accident peut, dans les minutes qui suivent, dégager :", "options": ["Un gaz toujours mortel qu'il faut fuir immédiatement","Rien du tout, c'est totalement inodore","Uniquement de la fumée d'incendie","Une odeur et une poussière normalement sans danger particulier à court terme, sauf gêne respiratoire chez une personne fragile"], "correctIndex": 3, "explanation": "Le déclenchement d'un airbag peut dégager une légère poussière et une odeur particulière, généralement sans danger, bien qu'il soit conseillé d'aérer et de surveiller toute gêne respiratoire chez une personne sensible."},
  {"id": "kq465", "type": "knowledge", "theme": "secours", "question": "Lorsqu'un témoin décide d'intervenir sur une victime, il doit avant tout :", "options": ["Se présenter, expliquer son intention et rassurer la victime avant d'agir si elle est consciente","Agir sans se présenter ni parler à la victime","Demander l'autorisation écrite de la victime","Attendre l'accord d'un policier avant tout geste"], "correctIndex": 0, "explanation": "Avant d'intervenir sur une victime consciente, il est recommandé de se présenter, d'expliquer ce que l'on va faire et de la rassurer, ce qui facilite sa coopération et limite son anxiété."},
  {"id": "kq466", "type": "knowledge", "theme": "secours", "question": "Concernant la sécurisation des lieux d'un accident hors agglomération, la nuit, il est conseillé de placer le triangle de présignalisation à une distance minimale d'environ :", "options": ["10 mètres","30 mètres, davantage si la visibilité est réduite (courbe, sommet de côte)","5 mètres","500 mètres dans tous les cas"], "correctIndex": 1, "explanation": "Le triangle doit être placé à une distance suffisante (au moins 30 mètres) pour laisser aux autres conducteurs le temps de réagir, cette distance devant être augmentée en cas de virage, de sommet de côte ou de faible visibilité."},
  {"id": "kq467", "type": "knowledge", "theme": "secours", "question": "Une personne victime d'un malaise cardiaque (douleur thoracique intense, oppression) au volant doit, si elle en a encore la capacité :", "options": ["Continuer à rouler jusqu'à destination","Accélérer pour rejoindre rapidement un hôpital par ses propres moyens","S'arrêter dès que possible en sécurité et alerter les secours (15 ou 112)","Attendre que la douleur passe avant d'agir"], "correctIndex": 2, "explanation": "Face à des signes de malaise cardiaque, il faut s'arrêter en sécurité dès que possible et alerter immédiatement les secours médicalisés (15 ou 112), plutôt que de continuer à conduire ou d'attendre."},
  {"id": "kq468", "type": "knowledge", "theme": "secours", "question": "Un feu de moteur qui se propage rapidement et ne peut être maîtrisé avec les moyens à disposition impose de :", "options": ["Continuer à tenter de l'éteindre coûte que coûte","Rester à proximité pour surveiller l'évolution du feu","Essayer de déplacer le véhicule en marche","S'éloigner immédiatement à bonne distance du véhicule et alerter les secours"], "correctIndex": 3, "explanation": "Face à un feu qui se propage rapidement et dépasse les moyens de maîtrise disponibles, la priorité absolue est de s'éloigner à bonne distance (risque d'explosion) et d'alerter immédiatement les secours."},
  {"id": "kq469", "type": "knowledge", "theme": "secours", "question": "La position latérale de sécurité (PLS) a notamment pour but d'éviter :", "options": ["Que la langue ou des vomissements n'obstruent les voies respiratoires d'une victime inconsciente","Que la victime se réveille trop vite","Que la victime ait froid","Aucun objectif particulier, c'est une position de confort"], "correctIndex": 0, "explanation": "La PLS maintient les voies respiratoires dégagées chez une victime inconsciente qui respire, en évitant que sa langue ne bascule en arrière ou que d'éventuels vomissements ne l'étouffent."},
  {"id": "kq470", "type": "knowledge", "theme": "secours", "question": "En résumé, la meilleure façon de se préparer à réagir efficacement en cas d'accident de la route est de :", "options": ["Ne rien apprendre, les secours professionnels suffisent toujours à eux seuls","Suivre une formation aux premiers secours (type PSC1) et connaître la conduite PAS","Uniquement conserver une trousse de secours sans formation","Uniquement mémoriser les numéros d'urgence, sans autre préparation"], "correctIndex": 1, "explanation": "Suivre une formation aux premiers secours (comme le PSC1) et connaître la conduite à tenir résumée par PAS (Protéger, Alerter, Secourir) permet de réagir efficacement et sereinement en cas d'accident, en complément de l'intervention des secours professionnels."}
];
